Definition VDEL_1 : Z := 0xedfd8.   Definition VDEL_RA_1 : Z := 0xee10c.
Definition VDEL_2 : Z := 0xee18c.   Definition VDEL_RA_2 : Z := 0xee2bc.
Definition VDEL_3 : Z := 0xee33c.   Definition VDEL_RA_3 : Z := 0xee46c.
Definition VDEL_STACK : Z := 64 + AFREE_STACK.

Section VDel.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.

  Definition vdel_LB (LB : list block) (pid : bptr) (b1 : Z) : list block :=
    if b1 =? 0 then LB else as_lb_remove H pid LB.

  Definition vdel_X (v b1 c1 : Z) : list (Z * Z) :=
    [(v, v + 24)] ++ (if b1 =? 0 then [] else [(b1, c1); (sh b1, sh b1 + nsh (c1 - b1))]).

  Definition vdel_hdr_ok (LF : list fframe) (x : Z) (m : mem) : Prop :=
    x mod 8 = 0 /\ SHAD m x (repeat (b8 0) 3)
    /\ exists f, In f LF /\ ff_addr f <= x /\ x + 24 <= ff_addr f + fsz (ff_class f).

  Definition vdel_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : as_St H) (LB : list block) (LF : list fframe) (pid : bptr) (v b1 c1 lo B shi : Z) (errv : word)
      (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : as_St H),
      as_VIS H s' (cfg_ms c) = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                                       t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ as_AKREL H s' c /\ as_MPRES H mo (cfg_model c)
      /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
      /\ rw_cells asegs m' (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m' B
      /\ xpres H (vdel_LB LB pid b1) (bv_unsigned sp) (vdel_X v b1 c1) m m'
      /\ as_RHEAP H s' (vdel_LB LB pid b1) m' /\ lb_own (vdel_LB LB pid b1) m'
      /\ rw_cells asegs m' v [C8 (wz 0); C8 (wz 0); C8 (wz 0)] /\ SHAD m' v (repeat (b8 0) 3)
      /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi
      /\ as_AL H s' >= as_AL H s - as_Cf H (c1 - b1).

  Definition vdel_stmt_at (entry del_ra K : Z) : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (msF : machine_state) (m : mem) (mo : Model)
           (s : as_St H) (LB : list block) (LF : list fframe) (pid : bptr) (v b1 e1 c1 lo B shi : Z) (errv : word),
      as_VIS H s msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (Z_to_bv 64 entry) fc None m (seg_rom asegs) ->
      a0 = Z_to_bv 64 v ->
      rw_cells asegs m v [C8 (wz b1); C8 (wz e1); C8 (wz c1)] -> vdel_hdr_ok LF v m -> v + 24 <= aceil ->
      (b1 = 0 -> e1 = 0 /\ c1 = 0) ->
      (b1 <> 0 -> In (pid, b1, c1 - b1) LB /\ b1 <= e1 <= c1 /\ c1 - b1 <= 2 ^ 40 /\ SHAD m b1 (cc_gen (c1 - b1) (e1 - b1))
                  /\ (e1 - b1) mod K = 0 /\ (b1 + (c1 - b1) <= v \/ v + 24 <= b1)) ->
      lb_own LB m ->
      as_RHEAP H s LB m -> as_AKREL H s (mkCfg msF mo) -> as_Cf H (c1 - b1) <= as_AL H s ->
      as_rauxv_ok H m B -> bv_unsigned sp <= B ->
      bv_unsigned sp mod 16 = 0 ->
      stk asegs m lo (bv_unsigned sp) -> aceil <= lo -> lo <= bv_unsigned sp - VDEL_STACK ->
      rw_cells asegs m (errno_addr tp) [C4 errv] -> mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
      ACONST m -> as_RFS H LF m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
      (b1 <> 0 -> trace_ok (as_TR H) APC0_FREE [del_ra]) ->
      as_SR H (vdel_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF pid v b1 c1 lo B shi errv m mo)
        (mkCfg msF mo).

  Definition vdel_stmtB : Prop :=
    vdel_stmt_at VDEL_1 VDEL_RA_1 20 /\ vdel_stmt_at VDEL_2 VDEL_RA_2 4 /\ vdel_stmt_at VDEL_3 VDEL_RA_3 4.

  Hypothesis HH : asan_rt_hyps H.
  Hypothesis HAN : annotate_gen_stmt.

  Definition VD1_MID : Z := 0xee038.  Definition VD1_L : Z := 0xee044.  Definition VD1_P : Z := 0xee054.
  Definition VD1_A1 : Z := 0xee090.   Definition VD1_A2 : Z := 0xee0ec.  Definition VD1_END : Z := 0xee11c.
  Definition VD1_RET : Z := 0xee13c.
  Definition VD2_MID : Z := 0xee1ec.  Definition VD2_L : Z := 0xee1f8.  Definition VD2_P : Z := 0xee204.
  Definition VD2_A1 : Z := 0xee240.   Definition VD2_A2 : Z := 0xee29c.  Definition VD2_END : Z := 0xee2cc.
  Definition VD2_RET : Z := 0xee2ec.
  Definition VD3_MID : Z := 0xee39c.  Definition VD3_L : Z := 0xee3a8.  Definition VD3_P : Z := 0xee3b4.
  Definition VD3_A1 : Z := 0xee3f0.   Definition VD3_A2 : Z := 0xee44c.  Definition VD3_END : Z := 0xee47c.
  Definition VD3_RET : Z := 0xee49c.

  Definition vshw (x : Z) : word := alu64 ALU_ADD (alu64 ALU_SRL (Z_to_bv 64 x) (Z_to_bv 64 3)) (Z_to_bv 64 2147450880).

  Lemma vd_sltu : forall a b, 0 <= a < 2 ^ 64 -> 0 <= b < 2 ^ 64 ->
    alu64 ALU_SLTU (Z_to_bv 64 a) (Z_to_bv 64 b) = Z_to_bv 64 (if a <? b then 1 else 0).
  Proof.
    intros a b Ha Hb. apply bv_eq. rewrite u_sltu64, !u64_of_Z by lia.
    destruct (a <? b); rewrite u64_of_Z by lia; reflexivity.
  Qed.

  Lemma vd_addsub : forall a b, alu64 ALU_ADD (Z_to_bv 64 a) (alu64 ALU_SUB (Z_to_bv 64 b) (Z_to_bv 64 a)) = Z_to_bv 64 b.
  Proof. intros a b. rewrite SymExec.alu64_sub_lit, SymExec.alu64_add_lit. f_equal. ring. Qed.

  Ltac vd_brw := lazymatch goal with |- sc_denot _ _ _ (SCBr _ _ _ _) => idtac end; cbn [sc_denot]; evs;
    rewrite ?w_addm, ?w_add by lia; rewrite ?br_eq, ?br_ne, ?br_ltu, ?br_geu by lia; bool_lia.
  Ltac vd_brx := lazymatch goal with |- sc_denot _ _ _ (SCBr _ _ _ _) => idtac end; cbn [sc_denot]; evs;
    rewrite ?vd_sltu by lia;
    repeat match goal with |- context [?a <? ?b] =>
      first [ replace (a <? b) with false by (symmetry; apply Z.ltb_ge; lia)
            | replace (a <? b) with true by (symmetry; apply Z.ltb_lt; lia) ] end;
    first [ reflexivity | vm_compute; reflexivity ].

  Ltac vd_lgcell Hlf WA k :=
    eapply (rw_cells_log_nth _ _ _ k);
    [ exact Hlf | reflexivity
    | repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia;
                                  cbn [a_off Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]); apply Forall_nil
    | unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [a_off]; lia
    | exact WA | reflexivity | exact I
    | first [ reflexivity | evs; rewrite ?w_add by lia; reflexivity
            | evs; match goal with HRx : ?R = mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ =>
                     rewrite HRx; reflexivity end ] ].

  Lemma vd_cells_same : forall m A cs cs', rw_cells asegs m A cs -> cells_wf cs' ->
    cells_bytes cs' = cells_bytes cs -> cells_size cs' = cells_size cs -> rw_cells asegs m A cs'.
  Proof.
    intros m A cs cs' [[_ HB] HW] Wf EB ES. split; [split; [exact Wf | rewrite EB; exact HB] | rewrite ES; exact HW].
  Qed.

  Lemma vd_zero3 : forall m A, rw_cells asegs m A [CB 24 (poison_bytes 24 0)] ->
    rw_cells asegs m A [C8 (wz 0); C8 (wz 0); C8 (wz 0)].
  Proof.
    intros m A HC. eapply vd_cells_same; [exact HC | cbn; tauto | vm_compute; reflexivity | reflexivity].
  Qed.
  Lemma vd2_loop : forall (k : nat)
      (x1 x2 x3 x4 x5 x6 x7 x8 x9 x12 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (b p : Z),
    8 <= b -> b + 4 * Z.of_nat (S k) < 2 ^ 47 -> p = b + 4 * Z.of_nat (S k) ->
    evt asegs (fun ms' => ms' = MS (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 4) x12 (Z_to_bv 64 b) x14 x15 x16 x17
                                        x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                                   F (Z_to_bv 64 VD2_P) fc None m (seg_rom asegs))
      (MS (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 4) x12 (Z_to_bv 64 p) x14 x15 x16 x17
               x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 VD2_L) fc None m (seg_rom asegs)).
  Proof.
    induction k as [|k IH]; intros until p; intros B8 BH EP; subst p.
    - remember (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 4) x12 (Z_to_bv 64 (b + 4 * Z.of_nat 1)) x14 x15 x16 x17
                    x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
      pose (E := Eseed R [Z_to_bv 64 b; Z_to_bv 64 (b + 4 * Z.of_nat 1)]).
      assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (11%bv, ELit 4); (13%bv, EVar 33)]) R).
      { apply regs_ok_srs; [apply regs_ok_seed|].
        repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
      assert (HK : know_ok asegs E m [KRange (EVar 32) 8 (2 ^ 47); KRange (EVar 33) 12 (2 ^ 47)]).
      { unfold know_ok. repeat (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]). apply Forall_nil. }
