          F (Z_to_bv 64 VDEL_2) fc None m (seg_rom asegs)).
  Proof.
    intros until lo. intros CV SV V8 VA BR ST CE LO SPH MI AC.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    unfold AIMG_TOP in VB1.
    pose proof (ACONST_shbase m AC) as [CG CS].
    remember (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
                  x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
    pose (E := Eseed R [Z_to_bv 64 v; Z_to_bv 64 spz; Z_to_bv 64 b; Z_to_bv 64 e]).
    assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (GZV : gz m v 24) by (intros i Hi; eapply sh0_of_SHAD0; [exact SV | cbn; lia]).
    assert (WS : forall a, lo <= a -> a + 8 <= spz -> wr_at asegs m a 8).
    { intros a X1 X2. pose proof (wr_at_of_stk _ _ _ _ ST) as (W1 & W2 & W). split; [lia|]. split; [lia|].
      intros i Hi. replace (a + i) with (lo + (a - lo + i)) by lia. apply W. lia. }
    assert (HK : know_ok asegs E m
       (kn_fix 20 [VD2_MID] (SCR [] [] []) VDEL_2 (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33)])
       [ KWord (SA (EVar 32) 0) 8 (EVar 34); KWord (SA (EVar 32) 8) 8 (EVar 35);
         KWr (SA (EVar 33) (-56)) (ELit 56);
         KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL); KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit 2147450880);
         KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) AIMG_TOP (2 ^ 47); KRange (EVar 34) 8 (2 ^ 47);
         KAlign (EVar 32) 8 ] 40)).
