    assert (CV2 : rw_cells asegs M2 v [C8 (wz b); C8 (wz b); C8 (wz c)]).
    { change [C8 (wz b); C8 (wz e); C8 (wz c)] with ([C8 (wz b)] ++ [C8 (wz e)] ++ [C8 (wz c)]) in CV1.
      apply rw_cells_app in CV1 as [CV0 CV']. apply rw_cells_app in CV' as [_ CV3].
      replace (v + Z.of_nat (cells_size [C8 (wz b)]) + Z.of_nat (cells_size [C8 (wz e)])) with (v + 16) in CV3 by (cbn; lia).
      apply rw_cells_cons8_c.
      { eapply rw_cells_transport; [exact CV0 | exact MU2 | exact WM2 | cbn; lia]. }
      apply rw_cells_cons8_c.
      { subst M2. clear - Hlf WV1 VB1 VB2 VB3 VB4 VB5 ACF1 ACF2. vd_lgcell Hlf (WV1 (v + 8) ltac:(lia) ltac:(lia)) 0%nat. }
