      by (eapply rw_cells_transport; [exact FR1 | exact MU2 | exact WM2 | cbn; lia]).
    pose proof (stk_split asegs M2 lo (spz - 64) spz ST2 ltac:(lia)) as [ST2a ST2b].
    eapply evt_of_msteps; [exact Hms|].
    rewrite mkst_MS, HRe1, ?K1, ?K2, ?K8, ?K9, ?K10, ?K11, ?K12, ?K13, ?K18, ?K19, ?K20, ?K21.
    clear HRe1 HR' Hlf Hms HF1' K1 K2 K8 K9 K10 K11 K12 K13 K18 K19 K20 K21.
    eapply evt_cut.
    { eapply HAN with (beg := b) (len := c - b) (oldmid := e - b) (newmid := 0) (lo := lo); rewrite ?u64_of_Z by lia.
      - reflexivity.
      - f_equal; lia.
      - f_equal; lia.
      - rewrite Z.add_0_r. reflexivity.
      - Z.div_mod_to_equations; lia.
      - lia.
      - lia.
      - lia.
      - exact BA.
      - unfold AAPP_HI; lia.
      - exact SB2.
      - exact ST2a.
      - exact CE.
      - unfold AINTRIN_STACK; lia.
      - exact MI2.
      - exact AC2.
      - eapply aapp_in_app_mem; [exact BA | lia | lia]. }
    intros ms3 POST3.
    destruct POST3 as (v0 & v1 & v2 & e0 & e1 & e2 & e3 & e4 & e5 & e6 & e7 & v3 & v4 & v5 & v6 & m3 & EQ3 & MU3 & WM3 & MI3 & ST3 & SH3 & AC3).
    subst ms3. rewrite u64_of_Z in MU3, ST3 by lia.
    rewrite ret_pc_even by (first [reflexivity | lia]).
    assert (CV3 : rw_cells asegs m3 v [C8 (wz b); C8 (wz b); C8 (wz c)])
      by (eapply rw_cells_transport; [exact CV2 | exact MU3 | exact WM3 | cbn; unfold AINTRIN_STACK; lia]).
    assert (SV3 : SHAD m3 v (repeat (b8 0) 3)).
    { eapply SHAD_transport; [exact SV2 | exact MU3 | exact WM3 |]. cbn [length repeat Z.of_nat Pos.of_succ_nat]. cbn.
      unfold AINTRIN_STACK. lia. }
    assert (S03 : stack0 m3 lo shi).
    { eapply stack0_transport; [exact S02 | exact MU3 | exact WM3 |].
      apply Forall_cons; [right; cbn; exact SPA|].
      apply Forall_cons; [apply stack0_ok_app; cbn; unfold AHI_LO, AINTRIN_STACK; lia | apply Forall_nil]. }
    assert (FR3 : rw_cells asegs m3 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
      by (eapply rw_cells_transport; [exact FR2 | exact MU3 | exact WM3 | cbn; unfold AINTRIN_STACK; lia]).
    assert (ST3' : stk asegs m3 lo spz).
    { eapply (stk_merge asegs m3 lo (spz - 64) spz); [exact ST3 | | lia].
      eapply stk_transport_disjoint; [exact ST2b | exact MU3 | exact WM3 | cbn; unfold AINTRIN_STACK; lia]. }
    apply evt_done. exists v0, v1, v2, e0, e1, e2, e3, e4, e5, e6, e7, v3, v4, v5, v6, m3.
    split; [unfold vshw; rewrite ?w_add by lia; reflexivity|].
    split; [exact (munch_app _ _ _ _ _ (munch_app _ _ _ _ _ MU1 MU2) MU3)|].
    split; [exact (wmono_trans asegs _ _ _ (wmono_trans asegs _ _ _ WM1 WM2) WM3)|].
    split; [exact MI3|]. split; [exact ST3'|]. split; [exact CV3|].
    split; [exact SV3|]. split; [exact S03|]. split; [exact SH3|]. split; [exact AC3 | exact FR3].
  Qed.
  Lemma vd1_loop : forall (k : nat)
      (x1 x2 x3 x4 x5 x6 x7 x8 x9 x12 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (b p : Z),
    8 <= b -> b + 20 * Z.of_nat (S k) < 2 ^ 47 -> p = b + 20 * Z.of_nat (S k) ->
    evt asegs (fun ms' => ms' = MS (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 20) x12 (Z_to_bv 64 b) x14 x15 x16 x17
                                        x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                                   F (Z_to_bv 64 VD1_P) fc None m (seg_rom asegs))
      (MS (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 20) x12 (Z_to_bv 64 p) x14 x15 x16 x17
               x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 VD1_L) fc None m (seg_rom asegs)).
  Proof.
    induction k as [|k IH]; intros until p; intros B8 BH EP; subst p.
    - remember (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 20) x12 (Z_to_bv 64 (b + 20 * Z.of_nat 1)) x14 x15 x16 x17
                    x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
      pose (E := Eseed R [Z_to_bv 64 b; Z_to_bv 64 (b + 20 * Z.of_nat 1)]).
      assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (11%bv, ELit 20); (13%bv, EVar 33)]) R).
      { apply regs_ok_srs; [apply regs_ok_seed|].
        repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
      assert (HK : know_ok asegs E m [KRange (EVar 32) 8 (2 ^ 47); KRange (EVar 33) 28 (2 ^ 47)]).
      { unfold know_ok. repeat (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]). apply Forall_nil. }
      xrun_at (PropExec.mkFP F fc) asegs R VD1_L m (seg_rom asegs) HR HK 10%nat [VD1_L; VD1_P] (SCR [false] [] []) 40%N.
      { split_scs; first [sc_br | vd_brw]. }
      assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
      pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
      readback HR' HF1 HR0 HRe.
      rreg HR' 13%bv L13. rreg HR' 10%bv L10. rreg HR' 11%bv L11.
      rewrite w_addm in L13 by lia.
      eapply evt_of_msteps; [exact Hms|].
      rewrite mkst_MS, HRe, L13, L10, L11. apply evt_done.
      replace (b + 20 * Z.of_nat 1 + -20) with b by lia. reflexivity.
    - remember (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) (Z_to_bv 64 20) x12 (Z_to_bv 64 (b + 20 * Z.of_nat (S (S k)))) x14 x15 x16 x17
                    x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
      pose (E := Eseed R [Z_to_bv 64 b; Z_to_bv 64 (b + 20 * Z.of_nat (S (S k)))]).
      assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (11%bv, ELit 20); (13%bv, EVar 33)]) R).
      { apply regs_ok_srs; [apply regs_ok_seed|].
        repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
      assert (HK : know_ok asegs E m [KRange (EVar 32) 8 (2 ^ 47); KRange (EVar 33) 28 (2 ^ 47)]).
      { unfold know_ok. repeat (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]). apply Forall_nil. }
      xrun_at (PropExec.mkFP F fc) asegs R VD1_L m (seg_rom asegs) HR HK 10%nat [VD1_L; VD1_P] (SCR [true] [] []) 40%N.
      { split_scs; first [sc_br | vd_brw]. }
      assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
      pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
      readback HR' HF1 HR0 HRe.
      rreg HR' 13%bv L13. rreg HR' 10%bv L10. rreg HR' 11%bv L11.
      rewrite w_addm in L13 by lia.
      eapply evt_of_msteps; [exact Hms|].
      rewrite mkst_MS, HRe, L13, L10, L11.
      replace (b + 20 * Z.of_nat (S (S k)) + -20) with (b + 20 * Z.of_nat (S k)) by lia.
      apply IH; lia.
  Qed.

