      eapply evt_of_msteps; [exact Hms|].
      rewrite mkst_MS, HRe, L10, L12. apply evt_done. exists x11, x13. reflexivity.
    - remember (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 (Z_to_bv 64 b) x11 (Z_to_bv 64 e) x13 x14 x15 x16 x17
                    x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
      pose (E := Eseed R [Z_to_bv 64 b; Z_to_bv 64 e]).
      assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (12%bv, EVar 33)]) R).
      { apply regs_ok_srs; [apply regs_ok_seed|].
        repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
      assert (HK : know_ok asegs E m [KRange (EVar 32) 8 (2 ^ 47); KRange (EVar 33) 28 (2 ^ 47)]).
      { unfold know_ok. repeat (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]). apply Forall_nil. }
      xrun_at (PropExec.mkFP F fc) asegs R VD1_MID m (seg_rom asegs) HR HK 10%nat [VD1_L] (SCR [false] [] []) 40%N.
      { split_scs; first [sc_br | vd_brw]. }
      assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
      pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
      readback HR' HF1 HR0 HRe.
      rreg HR' 10%bv L10. rreg HR' 11%bv L11. rreg HR' 12%bv L12. rreg HR' 13%bv L13.
      eapply evt_of_msteps; [exact Hms|].
      rewrite mkst_MS, HRe, L10, L11, L12, L13.
      eapply evt_mono; [eapply (vd1_loop k); lia |].
