    evt asegs (fun ms' => ms' = MS (mkR ra (Z_to_bv 64 spz) x3 x4 x5 x6 x7 s0 s1 x10 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
                                        x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (ret_pc ra) fc None m (seg_rom asegs))
      (MS (mkR x1 (Z_to_bv 64 (spz - 64)) x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21
               x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 VD3_END) fc None m (seg_rom asegs)).
  Proof.
    intros until s5. intros FR SPL SPH.
    remember (mkR x1 (Z_to_bv 64 (spz - 64)) x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21
                  x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
    pose (E := Eseed R [Z_to_bv 64 (spz - 64); ra; s0; s1; s2; s3; s4; s5]).
    assert (HR : regs_ok E (srs sr_id [(2%bv, EVar 32)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (HK : know_ok asegs E m
       [ KRange (EVar 32) (2 ^ 45) (2 ^ 47 - 64);
         KWord (SA (EVar 32) 56) 8 (EVar 33); KWord (SA (EVar 32) 48) 8 (EVar 34); KWord (SA (EVar 32) 40) 8 (EVar 35);
         KWord (SA (EVar 32) 32) 8 (EVar 36); KWord (SA (EVar 32) 24) 8 (EVar 37); KWord (SA (EVar 32) 16) 8 (EVar 38);
         KWord (SA (EVar 32) 8) 8 (EVar 39) ]).
    { unfold know_ok.
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. lia. }
      apply Forall_cons; [kframeM FR 48%nat|]. apply Forall_cons; [kframeM FR 40%nat|]. apply Forall_cons; [kframeM FR 32%nat|].
      apply Forall_cons; [kframeM FR 24%nat|]. apply Forall_cons; [kframeM FR 16%nat|]. apply Forall_cons; [kframeM FR 8%nat|].
      apply Forall_cons; [kframeM FR 0%nat|]. apply Forall_nil. }
    xrun_at (PropExec.mkFP F fc) asegs R VD3_END m (seg_rom asegs) HR HK 20%nat [VD3_RET] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1. }
    assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
