  Qed.

  Lemma vd3_s1 : forall (ra gp tp x5 x6 x7 s0 s1 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v b e c lo : Z),
    rw_cells asegs m v [C8 (wz b); C8 (wz e); C8 (wz c)] -> SHAD m v (repeat (b8 0) 3) -> v mod 8 = 0 -> aapp v 24 ->
    8 <= b < 2 ^ 47 ->
    stk asegs m lo spz -> aceil <= lo -> lo <= spz - 64 -> spz <= 2 ^ 47 -> mem_inv asegs m -> ACONST m ->
    evt asegs (fun ms' => exists w11 m1,
        ms' = MS (mkR ra (Z_to_bv 64 (spz - 64)) gp tp x5 x6 x7 (Z_to_bv 64 v) s1 (Z_to_bv 64 b) w11 (Z_to_bv 64 e)
                      x13 x14 x15 x16 x17 (Z_to_bv 64 (v + 8)) (vshw v) (Z_to_bv 64 2147450880) (vshw (v + 8))
                      x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                 F (Z_to_bv 64 VD3_MID) fc None m1 (seg_rom asegs)
        /\ munch [(spz - 56, spz)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1 /\ stk asegs m1 lo spz
        /\ rw_cells asegs m1 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
      (MS (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
               x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 VDEL_3) fc None m (seg_rom asegs)).
  Proof.
    intros until lo. intros CV SV V8 VA BR ST CE LO SPH MI AC.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    unfold AIMG_TOP in VB1.
    pose proof (ACONST_shbase m AC) as [CG CS].
    remember (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
                  x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
    pose (E := Eseed R [Z_to_bv 64 v; Z_to_bv 64 spz; Z_to_bv 64 b; Z_to_bv 64 e]).
    assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (GZV : gz m v 24) by (intros i Hi; eapply sh0_of_SHAD0; [exact SV | cbn; lia]).
    assert (WS : forall a, lo <= a -> a + 8 <= spz -> wr_at asegs m a 8).
    { intros a X1 X2. pose proof (wr_at_of_stk _ _ _ _ ST) as (W1 & W2 & W). split; [lia|]. split; [lia|].
      intros i Hi. replace (a + i) with (lo + (a - lo + i)) by lia. apply W. lia. }
    assert (HK : know_ok asegs E m
       (kn_fix 20 [VD3_MID] (SCR [] [] []) VDEL_3 (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33)])
       [ KWord (SA (EVar 32) 0) 8 (EVar 34); KWord (SA (EVar 32) 8) 8 (EVar 35);
         KWr (SA (EVar 33) (-56)) (ELit 56);
         KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL); KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit 2147450880);
         KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) AIMG_TOP (2 ^ 47); KRange (EVar 34) 8 (2 ^ 47);
         KAlign (EVar 32) 8 ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { kword_cell CV 0%nat (C8 (wz b)). }
      apply Forall_cons. { kword_cell CV 8%nat (C8 (wz e)). }
      apply Forall_cons.
      { eapply kwr_of_stk; [exact ST | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off]; lia
                           | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; cbn [a_off]; lia | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
      apply Forall_cons.
      { eapply (kword_of_rw_cells asegs E m AGOT_SHBASE _ 0%nat (C8 (wz ASHBASE_CELL))); first [exact CG | reflexivity | (unfold AGOT_SHBASE; lia) | (cbn; lia)]. }
      apply Forall_cons.
      { eapply (kword_of_rw_cells asegs E m ASHBASE_CELL _ 0%nat (C8 (wz 2147450880))); first [exact CS | reflexivity | (unfold ASHBASE_CELL; lia) | (cbn; lia)]. }
      do 3 (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]).
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact V8]. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R VDEL_3 m (seg_rom asegs) HR HK 200%nat [VD3_MID] (SCR [] [] []) 40%N.
    { split_scs.
      all: try (first [sc_br | vd_brw]).
      all: clear - E VA SPH LO CE ACF1 ACF2 VB1 VB2 VB3 BR.
      all: unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO, AIMG_TOP in VA.
      all: first [ sc_shdj | sc_dj ]. }
    clear HK.
    lazymatch type of Hlf with log_flat _ ?lg =>
      lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
        change mm with (mem_denot E m lg) in Hms; set (M1 := mem_denot E m lg) in Hms end end.
    assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rreg HR' 2%bv L2. rreg HR' 8%bv L8. rreg HR' 10%bv L10. rreg HR' 12%bv L12.
    rreg HR' 18%bv L18. rreg HR' 19%bv L19. rreg HR' 20%bv L20. rreg HR' 21%bv L21.
    rewrite w_addm in L2 by lia. rewrite w_add in L18 by lia.
    assert (MU1 : munch [(spz - 56, spz)] m M1).
    { subst M1. clear - Hlf SPH LO CE ACF1 ACF2. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite u64_of_Z by lia;
                                  cbn [inside Z.of_nat Pos.of_succ_nat Pos.succ a_off]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (ST1 : stk asegs M1 lo spz) by (subst M1; apply stk_mem_denot; exact ST).
    assert (FR1 : rw_cells asegs M1 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
    { apply rw_cells_cons8_c. { subst M1. vd_lgcell Hlf (WS (spz - 56) ltac:(lia) ltac:(lia)) 0%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8) with (spz - 48) by lia. vd_lgcell Hlf (WS (spz - 48) ltac:(lia) ltac:(lia)) 1%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8) with (spz - 40) by lia. vd_lgcell Hlf (WS (spz - 40) ltac:(lia) ltac:(lia)) 2%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8 + 8) with (spz - 32) by lia. vd_lgcell Hlf (WS (spz - 32) ltac:(lia) ltac:(lia)) 3%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8 + 8 + 8) with (spz - 24) by lia. vd_lgcell Hlf (WS (spz - 24) ltac:(lia) ltac:(lia)) 4%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8 + 8 + 8 + 8) with (spz - 16) by lia. vd_lgcell Hlf (WS (spz - 16) ltac:(lia) ltac:(lia)) 5%nat. }
      subst M1. replace (spz - 56 + 8 + 8 + 8 + 8 + 8 + 8) with (spz - 8) by lia. vd_lgcell Hlf (WS (spz - 8) ltac:(lia) ltac:(lia)) 6%nat. }
    eapply evt_of_msteps; [exact Hms|].
    rewrite mkst_MS, HRe, L2, L8, L10, L12, L18, L19, L20, L21.
    apply evt_done. exists (getr R' 11), M1.
    split; [| split; [exact MU1 | split; [exact WM1 | split; [exact MI1 | split; [exact ST1 | exact FR1]]]]].
    unfold vshw. rewrite <- (w_add v 8) by lia. reflexivity.
  Qed.

  Lemma vd3_zr : forall (ra gp tp x5 x6 x7 s0 s1 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v lo : Z),
    rw_cells asegs m v [C8 (wz 0); C8 (wz 0); C8 (wz 0)] -> SHAD m v (repeat (b8 0) 3) -> v mod 8 = 0 -> aapp v 24 ->
    stk asegs m lo spz -> aceil <= lo -> lo <= spz - 64 -> spz <= 2 ^ 47 -> mem_inv asegs m -> ACONST m ->
    evt asegs (fun ms' => exists w10 w11 m1,
        ms' = MS (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 w10 w11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
                      x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                 F (ret_pc ra) fc None m1 (seg_rom asegs)
        /\ munch [(spz - 56, spz)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1 /\ stk asegs m1 lo spz)
      (MS (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
               x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 VDEL_3) fc None m (seg_rom asegs)).
  Proof.
    intros until lo. intros CV SV V8 VA ST CE LO SPH MI AC.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    unfold AIMG_TOP in VB1.
    pose proof (ACONST_shbase m AC) as [CG CS].
    remember (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
                  x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) as R eqn:HR0.
    pose (E := Eseed R [Z_to_bv 64 v; Z_to_bv 64 spz]).
    assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (GZV : gz m v 24) by (intros i Hi; eapply sh0_of_SHAD0; [exact SV | cbn; lia]).
    assert (WS : forall a, lo <= a -> a + 8 <= spz -> wr_at asegs m a 8).
    { intros a X1 X2. pose proof (wr_at_of_stk _ _ _ _ ST) as (W1 & W2 & W). split; [lia|]. split; [lia|].
      intros i Hi. replace (a + i) with (lo + (a - lo + i)) by lia. apply W. lia. }
    assert (HK : know_ok asegs E m
       (kn_fix 20 [VD3_END] (SCR [] [] []) VDEL_3 (srs sr_id [(10%bv, EVar 32); (2%bv, EVar 33)])
       [ KWord (SA (EVar 32) 0) 8 (ELit 0);
         KWr (SA (EVar 33) (-56)) (ELit 56);
         KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL); KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit 2147450880);
         KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) AIMG_TOP (2 ^ 47);
         KAlign (EVar 32) 8 ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { kword_cell CV 0%nat (C8 (wz 0)). }
      apply Forall_cons.
      { eapply kwr_of_stk; [exact ST | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off]; lia
                           | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; cbn [a_off]; lia | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
      apply Forall_cons.
      { eapply (kword_of_rw_cells asegs E m AGOT_SHBASE _ 0%nat (C8 (wz ASHBASE_CELL))); first [exact CG | reflexivity | (unfold AGOT_SHBASE; lia) | (cbn; lia)]. }
      apply Forall_cons.
      { eapply (kword_of_rw_cells asegs E m ASHBASE_CELL _ 0%nat (C8 (wz 2147450880))); first [exact CS | reflexivity | (unfold ASHBASE_CELL; lia) | (cbn; lia)]. }
      do 2 (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]).
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact V8]. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R VDEL_3 m (seg_rom asegs) HR HK 200%nat [VD3_END] (SCR [] [] []) 40%N.
    { split_scs.
      all: try (first [sc_br | vd_brw]).
      all: clear - E VA SPH LO CE ACF1 ACF2 VB1 VB2 VB3.
      all: unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO, AIMG_TOP in VA.
      all: first [ sc_shdj | sc_dj ]. }
    clear HK.
    lazymatch type of Hlf with log_flat _ ?lg =>
      lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
        change mm with (mem_denot E m lg) in Hms; set (M1 := mem_denot E m lg) in Hms end end.
    assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rreg HR' 2%bv L2.
    rewrite w_addm in L2 by lia.
    assert (MU1 : munch [(spz - 56, spz)] m M1).
    { subst M1. clear - Hlf SPH LO CE ACF1 ACF2. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite u64_of_Z by lia;
                                  cbn [inside Z.of_nat Pos.of_succ_nat Pos.succ a_off]; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (ST1 : stk asegs M1 lo spz) by (subst M1; apply stk_mem_denot; exact ST).
    assert (FR1 : rw_cells asegs M1 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
    { apply rw_cells_cons8_c. { subst M1. vd_lgcell Hlf (WS (spz - 56) ltac:(lia) ltac:(lia)) 0%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8) with (spz - 48) by lia. vd_lgcell Hlf (WS (spz - 48) ltac:(lia) ltac:(lia)) 1%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8) with (spz - 40) by lia. vd_lgcell Hlf (WS (spz - 40) ltac:(lia) ltac:(lia)) 2%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8 + 8) with (spz - 32) by lia. vd_lgcell Hlf (WS (spz - 32) ltac:(lia) ltac:(lia)) 3%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8 + 8 + 8) with (spz - 24) by lia. vd_lgcell Hlf (WS (spz - 24) ltac:(lia) ltac:(lia)) 4%nat. }
      apply rw_cells_cons8_c. { subst M1. replace (spz - 56 + 8 + 8 + 8 + 8 + 8) with (spz - 16) by lia. vd_lgcell Hlf (WS (spz - 16) ltac:(lia) ltac:(lia)) 5%nat. }
      subst M1. replace (spz - 56 + 8 + 8 + 8 + 8 + 8 + 8) with (spz - 8) by lia. vd_lgcell Hlf (WS (spz - 8) ltac:(lia) ltac:(lia)) 6%nat. }
    eapply evt_of_msteps; [exact Hms|].
    rewrite mkst_MS, HRe, L2.
    eapply evt_mono; [eapply vd3_end; [exact FR1 | lia | lia]|].
    intros ms' ->. do 2 eexists. exists M1.
    split; [reflexivity|]. split; [exact MU1|]. split; [exact WM1|]. split; [exact MI1 | exact ST1].
  Qed.

  Definition vd3_mid1 (ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 : word) (F : bvmap 5 word) (fc : bv 32)
      (spz v b c lo shi : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists w5 w6 w7 d10 d11 d12 d13 d14 d15 d16 d17 w28 w29 w30 w31 m2,
      ms' = MS (mkR (Z_to_bv 64 VD3_A1) (Z_to_bv 64 (spz - 64)) gp tp w5 w6 w7 (Z_to_bv 64 v) (Z_to_bv 64 (v + 16))
                    d10 d11 d12 d13 d14 d15 d16 d17 (Z_to_bv 64 (v + 8)) (vshw v) (vshw (v + 16)) (vshw (v + 8))
                    x22 x23 x24 x25 x26 x27 w28 w29 w30 w31)
               F (Z_to_bv 64 VD3_A1) fc None m2 (seg_rom asegs)
      /\ munch [(spz - 56, spz); (v + 8, v + 16); (sh b, sh b + nsh (c - b)); (spz - 64 - AINTRIN_STACK, spz - 64)] m m2
      /\ wmono asegs m m2 /\ mem_inv asegs m2 /\ stk asegs m2 lo spz
      /\ rw_cells asegs m2 v [C8 (wz b); C8 (wz b); C8 (wz c)]
      /\ SHAD m2 v (repeat (b8 0) 3) /\ stack0 m2 lo shi /\ SHAD m2 b (cc_gen (c - b) 0) /\ ACONST m2
      /\ rw_cells asegs m2 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Lemma vd3_a : forall (ra gp tp x5 x6 x7 s0 s1 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v b e c lo shi : Z),
    rw_cells asegs m v [C8 (wz b); C8 (wz e); C8 (wz c)] -> SHAD m v (repeat (b8 0) 3) -> v mod 8 = 0 -> aapp v 24 ->
    b <> 0 -> aapp b (c - b) -> b mod 16 = 0 -> b <= e <= c -> c - b <= 2 ^ 40 -> (e - b) mod 4 = 0 ->
    SHAD m b (cc_gen (c - b) (e - b)) -> (c <= v \/ v + 24 <= b) ->
    stack0 m lo shi -> spz <= shi ->
    stk asegs m lo spz -> aceil <= lo -> lo <= spz - VDEL_STACK -> mem_inv asegs m -> ACONST m ->
    evt asegs (vd3_mid1 ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 F fc spz v b c lo shi m)
      (MS (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
               x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 VDEL_3) fc None m (seg_rom asegs)).
  Proof.
    intros until shi. intros CV SV V8 VA B0 BA B16 BE BL EM SB VBD S0 SHI ST CE LO MI AC.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (stack0_bounds m lo shi S0) as SB0. unfold AAPP_HI in SB0.
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    pose proof (aapp_bounds b (c - b) BA ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5).
    unfold AIMG_TOP in VB1, PB1. unfold VDEL_STACK, AFREE_STACK in LO.
    eapply evt_cut.
    { eapply (vd3_s1 ra gp tp x5 x6 x7 s0 s1 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31
                F fc m spz v b e c lo); try eassumption; lia. }
    intros ms1 (w11 & m1 & EQ1 & MU1 & WM1 & MI1 & ST1 & FR1). subst ms1.
    set (k := Z.to_nat ((e - b) / 4)).
    assert (EK : e = b + 4 * Z.of_nat k)
      by (subst k; rewrite Z2Nat.id by (Z.div_mod_to_equations; lia); Z.div_mod_to_equations; lia).
    eapply evt_cut; [eapply (vd3_mid k); [lia | exact EK | lia]|].
    intros ms2 (w11' & w13 & EQ2). subst ms2.
    assert (SVP : sh b + nsh (c - b) <= v \/ v + 24 <= sh b)
      by (pose proof (aapp_disjoint_sh v 24 b (c - b) VA ltac:(lia) ltac:(unfold AAPP_HI; lia) ltac:(lia)); lia).
    assert (SPH : sh b + nsh (c - b) <= AHI_LO)
      by (exact (sh_nsh_high b (c - b) ltac:(lia) ltac:(lia) ltac:(unfold AAPP_HI; lia))).
    assert (SPA : sh b + nsh (c - b) <= sh aceil) by (unfold sh, nsh; Z.div_mod_to_equations; nia).
    assert (SHV : sh v + 3 <= sh b \/ sh b + nsh (c - b) <= sh v).
    { clear - VBD V8 B16 BE. unfold sh, nsh. Z.div_mod_to_equations. nia. }
    assert (SSH : sh v + 3 <= AHI_LO)
      by (unfold sh, ASHADOW_BASE; unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO in VA |- *; Z.div_mod_to_equations; lia).
    assert (SSL : v + 24 <= sh v \/ AHI_LO <= v).
    { unfold sh, ASHADOW_BASE; unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO in VA |- *; Z.div_mod_to_equations; lia. }
    unfold AHI_LO in SPH, SSH, SSL.
    assert (SAT : sh AIMG_TOP <= 2 ^ 45) by (apply Z.leb_le; vm_compute; reflexivity).

    assert (CV1 : rw_cells asegs m1 v [C8 (wz b); C8 (wz e); C8 (wz c)])
      by (eapply rw_cells_transport; [exact CV | exact MU1 | exact WM1 | cbn; lia]).
    assert (SV1 : SHAD m1 v (repeat (b8 0) 3)).
    { eapply SHAD_transport; [exact SV | exact MU1 | exact WM1 |]. cbn [length repeat Z.of_nat Pos.of_succ_nat]. cbn. lia. }
    assert (SB1 : SHAD m1 b (cc_gen (c - b) (e - b))).
    { eapply SHAD_transport; [exact SB | exact MU1 | exact WM1 |]. rewrite cc_gen_length by lia. cbn. lia. }
    assert (S01 : stack0 m1 lo shi).
    { eapply stack0_transport; [exact S0 | exact MU1 | exact WM1 |].
      apply Forall_cons; [apply stack0_ok_app; cbn; unfold AHI_LO; lia | apply Forall_nil]. }
    assert (AC1 : ACONST m1).
    { eapply ACONST_frame; [exact AC | exact MU1 | exact WM1 |].
      apply Forall_cons; [apply aconst_ok_high; [cbn; lia | right; left; cbn; lia] | apply Forall_nil]. }

    lazymatch goal with |- evt _ _ (MS ?T _ _ _ _ _ _) => remember T as R1 eqn:HR1 end.
    pose (E1 := Eseed R1 [Z_to_bv 64 v; Z_to_bv 64 (spz - 64); Z_to_bv 64 b; Z_to_bv 64 e; Z_to_bv 64 c]).
    assert (HR1s : regs_ok E1 (srs sr_id
       [(2%bv, EVar 33); (8%bv, EVar 32); (10%bv, EVar 34); (12%bv, EVar 35);
        (18%bv, EAlu ALU_ADD (EVar 32) (ELit 8)); (19%bv, EAlu ALU_ADD (EAlu ALU_SRL (EVar 32) (ELit 3)) (ELit 2147450880));
        (20%bv, ELit 2147450880); (21%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 8)) (ELit 3)) (ELit 2147450880))]) R1).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R1; evs; try reflexivity;
        unfold vshw; rewrite ?w_addm, ?w_add by lia; reflexivity. }
    assert (GZV1 : gz m1 v 24) by (intros i Hi; eapply sh0_of_SHAD0; [exact SV1 | cbn; lia]).
    assert (HK1 : know_ok asegs E1 m1
       (kn_fix 20 [AANNOTATE_CC] (SCR [false; false] [] []) VD3_P (srs sr_id
          [(2%bv, EVar 33); (8%bv, EVar 32); (10%bv, EVar 34); (12%bv, EVar 35);
           (18%bv, EAlu ALU_ADD (EVar 32) (ELit 8)); (19%bv, EAlu ALU_ADD (EAlu ALU_SRL (EVar 32) (ELit 3)) (ELit 2147450880));
           (20%bv, ELit 2147450880); (21%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 8)) (ELit 3)) (ELit 2147450880))])
       [ KWord (SA (EVar 32) 16) 8 (EVar 36); KWr (SA (EVar 32) 8) (ELit 8);
         KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) AIMG_TOP (2 ^ 47); KRange (EVar 34) AIMG_TOP (2 ^ 47);
         KAlign (EVar 32) 8 ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { kword_cell CV1 16%nat (C8 (wz c)). }
      apply Forall_cons.
      { eapply kwr_of_wr_at; [exact (proj2 CV1) | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off]; lia
                             | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; cbn [a_off]; cbn; lia | unfold elenZ; evs; rewrite u64_of_Z by lia; cbn; lia]. }
      do 3 (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]).
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact V8]. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R1 VD3_P m1 (seg_rom asegs) HR1s HK1 200%nat [AANNOTATE_CC] (SCR [false; false] [] []) 40%N.
    { split_scs.
      all: try (first [sc_br | vd_brw]).
      all: clear - E1 VA SB0 LO CE ACF1 ACF2 VB1 VB2 VB3 PB1 PB2 PB3 BE.
      all: unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO, AIMG_TOP in VA.
      all: first [ sc_shdj | sc_dj ]. }
    clear HK1.
    lazymatch type of Hlf with log_flat _ ?lg =>
      lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
        change mm with (mem_denot E1 m1 lg) in Hms; set (M2 := mem_denot E1 m1 lg) in Hms end end.
    assert (HF1 : rfull R1) by (rewrite HR1; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF1) as HF1'. cbn [ms_regs] in HF1'.
    readback HR' HF1' HR1 HRe1.
    rreg HR' 1%bv K1. rreg HR' 2%bv K2. rreg HR' 8%bv K8. rreg HR' 9%bv K9. rreg HR' 10%bv K10. rreg HR' 11%bv K11.
    rreg HR' 12%bv K12. rreg HR' 13%bv K13. rreg HR' 18%bv K18. rreg HR' 19%bv K19. rreg HR' 20%bv K20. rreg HR' 21%bv K21.
    assert (WV1 : forall a, v <= a -> a + 8 <= v + 24 -> wr_at asegs m1 a 8).
    { intros a X1 X2. pose proof (proj2 CV1) as W. destruct W as (W1 & W2 & W). cbn [cells_size csize Z.of_nat] in W.
      split; [lia|]. split; [lia|]. intros i Hi. replace (a + i) with (v + (a - v + i)) by lia. apply W. cbn. lia. }
    assert (MU2 : munch [(v + 8, v + 16)] m1 M2).
    { subst M2. clear - Hlf VB1 VB2 VB3 VB4 VB5 ACF1 ACF2. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite u64_of_Z by lia; cbn [inside Z.of_nat Pos.of_succ_nat Pos.succ a_off]; lia|]).
      apply Forall_nil. }
    assert (WM2 : wmono asegs m1 M2) by (subst M2; apply wmono_mem_denot).
    assert (MI2 : mem_inv asegs M2) by exact (msteps_mem_inv asegs _ _ Hms MI1).
    assert (ST2 : stk asegs M2 lo spz) by (subst M2; apply stk_mem_denot; exact ST1).
    assert (SB2 : SHAD M2 b (cc_gen (c - b) (e - b))).
    { eapply SHAD_transport; [exact SB1 | exact MU2 | exact WM2 |]. rewrite cc_gen_length by lia. cbn. lia. }
    assert (SV2 : SHAD M2 v (repeat (b8 0) 3)).
    { eapply SHAD_transport; [exact SV1 | exact MU2 | exact WM2 |]. cbn [length repeat Z.of_nat Pos.of_succ_nat]. cbn. lia. }
    assert (S02 : stack0 M2 lo shi).
    { eapply stack0_transport; [exact S01 | exact MU2 | exact WM2 |].
      apply Forall_cons; [eapply (stack0_ok_aapp v 24); [exact VA | cbn; lia | cbn; lia] | apply Forall_nil]. }
    assert (AC2 : ACONST M2).
    { eapply ACONST_frame; [exact AC1 | exact MU2 | exact WM2 |].
      apply Forall_cons; [eapply (aconst_ok_app v 24); [exact VA | cbn; lia | cbn; lia] | apply Forall_nil]. }
    assert (CV2 : rw_cells asegs M2 v [C8 (wz b); C8 (wz b); C8 (wz c)]).
    { change [C8 (wz b); C8 (wz e); C8 (wz c)] with ([C8 (wz b)] ++ [C8 (wz e)] ++ [C8 (wz c)]) in CV1.
