  Definition vd3_m2 (ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 : word) (F : bvmap 5 word) (fc : bv 32)
      (spz v b c lo shi : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists w5 w6 w7 d10 d11 d12 d13 d14 d15 d16 d17 w28 w29 w30 w31 m3,
      ms' = MS (mkR (Z_to_bv 64 VD3_A2) (Z_to_bv 64 (spz - 64)) gp tp w5 w6 w7 (Z_to_bv 64 v) (Z_to_bv 64 (v + 16))
                    d10 d11 d12 d13 d14 d15 d16 d17 (Z_to_bv 64 (v + 8)) (vshw v) (vshw (v + 16)) (vshw (v + 8))
                    x22 x23 x24 x25 x26 x27 w28 w29 w30 w31)
               F (Z_to_bv 64 VD3_A2) fc None m3 (seg_rom asegs)
      /\ munch [(sh b, sh b + nsh (c - b)); (spz - 64 - AINTRIN_STACK, spz - 64)] m m3
      /\ wmono asegs m m3 /\ mem_inv asegs m3 /\ stk asegs m3 lo spz
      /\ rw_cells asegs m3 v [C8 (wz b); C8 (wz b); C8 (wz c)]
      /\ SHAD m3 v (repeat (b8 0) 3) /\ stack0 m3 lo shi /\ SHAD m3 b (shadow_of (c - b)) /\ ACONST m3
      /\ rw_cells asegs m3 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Lemma vd3_b : forall (ra gp tp s0 s1 s2 s3 s4 s5 w5 w6 w7 d10 d11 d12 d13 d14 d15 d16 d17 x22 x23 x24 x25 x26 x27 w28 w29 w30 w31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v b c lo shi : Z),
    stk asegs m lo spz -> mem_inv asegs m ->
    rw_cells asegs m v [C8 (wz b); C8 (wz b); C8 (wz c)] -> SHAD m v (repeat (b8 0) 3) -> stack0 m lo shi ->
    SHAD m b (cc_gen (c - b) 0) -> ACONST m ->
    rw_cells asegs m (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    v mod 8 = 0 -> aapp v 24 ->
    b <> 0 -> aapp b (c - b) -> b mod 16 = 0 -> b <= c -> c - b <= 2 ^ 40 -> (c <= v \/ v + 24 <= b) ->
    spz <= shi -> aceil <= lo -> lo <= spz - VDEL_STACK -> spz <= 2 ^ 47 ->
    evt asegs (vd3_m2 ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 F fc spz v b c lo shi m)
      (MS (mkR (Z_to_bv 64 VD3_A1) (Z_to_bv 64 (spz - 64)) gp tp w5 w6 w7 (Z_to_bv 64 v) (Z_to_bv 64 (v + 16))
               d10 d11 d12 d13 d14 d15 d16 d17 (Z_to_bv 64 (v + 8)) (vshw v) (vshw (v + 16)) (vshw (v + 8))
               x22 x23 x24 x25 x26 x27 w28 w29 w30 w31)
          F (Z_to_bv 64 VD3_A1) fc None m (seg_rom asegs)).
  Proof.
    intros until shi. intros ST MI CV SV S0 SH AC FR V8 VA B0 BA B16 BE BL VBD SHI CE LO SPH.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (stack0_bounds m lo shi S0) as SB0. unfold AAPP_HI in SB0.
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    pose proof (aapp_bounds b (c - b) BA ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5).
    unfold AIMG_TOP in VB1, PB1. unfold VDEL_STACK, AFREE_STACK in LO.
    assert (SPH' : sh b + nsh (c - b) <= AHI_LO)
      by (exact (sh_nsh_high b (c - b) ltac:(lia) ltac:(lia) ltac:(unfold AAPP_HI; lia))).
    assert (SPA : sh b + nsh (c - b) <= sh aceil) by (unfold sh, nsh; Z.div_mod_to_equations; nia).
    assert (SHV : sh v + 3 <= sh b \/ sh b + nsh (c - b) <= sh v).
    { clear - VBD V8 B16 BE. unfold sh, nsh. Z.div_mod_to_equations. nia. }
    assert (SSH : sh v + 3 <= AHI_LO)
      by (unfold sh, ASHADOW_BASE; unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO in VA |- *; Z.div_mod_to_equations; lia).
    assert (SVP : sh b + nsh (c - b) <= v \/ v + 24 <= sh b)
      by (pose proof (aapp_disjoint_sh v 24 b (c - b) VA ltac:(lia) ltac:(unfold AAPP_HI; lia) ltac:(lia)); lia).
    unfold AHI_LO in SPH', SSH.
    lazymatch goal with |- evt _ _ (MS ?T _ _ _ _ _ _) => remember T as R2 eqn:HR2 end.
    pose (E2 := Eseed R2 [Z_to_bv 64 v; Z_to_bv 64 (spz - 64); Z_to_bv 64 b; Z_to_bv 64 c]).
    assert (HR2s : regs_ok E2 (srs sr_id
       [(2%bv, EVar 33); (8%bv, EVar 32); (9%bv, EAlu ALU_ADD (EVar 32) (ELit 16)); (18%bv, EAlu ALU_ADD (EVar 32) (ELit 8));
        (19%bv, EAlu ALU_ADD (EAlu ALU_SRL (EVar 32) (ELit 3)) (ELit 2147450880));
        (20%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 16)) (ELit 3)) (ELit 2147450880));
        (21%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 8)) (ELit 3)) (ELit 2147450880))]) R2).
    { apply regs_ok_srs; [apply regs_ok_seed|].
