    assert (HF2 : rfull R2) by (rewrite HR2; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF2) as HF2'. cbn [ms_regs] in HF2'.
    readback HR' HF2' HR2 HRe2.
    rreg HR' 1%bv K1. rreg HR' 2%bv K2. rreg HR' 8%bv K8. rreg HR' 9%bv K9. rreg HR' 10%bv K10. rreg HR' 11%bv K11.
    rreg HR' 12%bv K12. rreg HR' 13%bv K13. rreg HR' 18%bv K18. rreg HR' 19%bv K19. rreg HR' 20%bv K20. rreg HR' 21%bv K21.
    rewrite ?w_add in K9 by lia. rewrite ?w_add in K18 by lia.
    eapply evt_of_msteps; [exact Hms|].
    rewrite mkst_MS, HRe2, K1, K2, K8, K9, K10, K11, K12, K13, K18, K19, K20, K21.
    clear HRe2 HR' Hlf Hms HF2' K1 K2 K8 K9 K10 K11 K12 K13 K18 K19 K20 K21.
    pose proof (stk_split asegs m lo (spz - 64) spz ST ltac:(lia)) as [STa STb].
    eapply evt_cut.
    { eapply HAN with (beg := b) (len := c - b) (oldmid := 0) (newmid := c - b) (lo := lo); rewrite ?u64_of_Z by lia.
      - reflexivity.
      - f_equal; lia.
      - rewrite Z.add_0_r. reflexivity.
      - f_equal; lia.
      - Z.div_mod_to_equations; lia.
      - lia.
      - lia.
      - lia.
      - exact BA.
      - unfold AAPP_HI; lia.
      - exact SH.
      - exact STa.
      - exact CE.
      - unfold AINTRIN_STACK; lia.
      - exact MI.
      - exact AC.
      - eapply aapp_in_app_mem; [exact BA | lia | lia]. }
    intros ms4 POST4.
    destruct POST4 as (v0 & v1 & v2 & e0 & e1 & e2 & e3 & e4 & e5 & e6 & e7 & v3 & v4 & v5 & v6 & m4 & EQ4 & MU4 & WM4 & MI4 & ST4 & SH4 & AC4).
    subst ms4. rewrite u64_of_Z in MU4, ST4 by lia.
