    assert (SV4 : SHAD m4 v (repeat (b8 0) 3)).
    { eapply SHAD_transport; [exact SV | exact MU4 | exact WM4 |]. cbn [length repeat Z.of_nat Pos.of_succ_nat]. cbn.
