  Definition vd1_m2 (ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 : word) (F : bvmap 5 word) (fc : bv 32)
      (spz v b c lo shi : Z) (m : mem) : machine_state -> Prop :=
