    split; [unfold vshw; rewrite ?w_add by lia; reflexivity|].
    split; [exact MU4|]. split; [exact WM4|]. split; [exact MI4|]. split; [exact ST4'|]. split; [exact CV4|].
    split; [exact SV4|]. split; [exact S04|]. split; [exact SH4|]. split; [exact AC4 | exact FR4].
  Qed.

  Definition vd1_ex (gp tp x22 x23 x24 x25 x26 x27 : word) (F : bvmap 5 word) (fc : bv 32) (spz v b : Z) (m : mem)
      : machine_state -> Prop :=
    fun ms' => exists w5 w6 w7 a1' a2' a3' a4' a5' a6' a7' w28 w29 w30 w31,
      ms' = MS (mkR (Z_to_bv 64 VDEL_RA_1) (Z_to_bv 64 (spz - 64)) gp tp w5 w6 w7 (Z_to_bv 64 v) (Z_to_bv 64 (v + 16))
                    (Z_to_bv 64 b) a1' a2' a3' a4' a5' a6' a7' (Z_to_bv 64 (v + 8)) (vshw v) (vshw (v + 16)) (vshw (v + 8))
                    x22 x23 x24 x25 x26 x27 w28 w29 w30 w31)
               F (Z_to_bv 64 AOPDEL2) fc None m (seg_rom asegs).

  Lemma vd1_c : forall (gp tp w5 w6 w7 d10 d11 d12 d13 d14 d15 d16 d17 x22 x23 x24 x25 x26 x27 w28 w29 w30 w31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v b c lo : Z),
    rw_cells asegs m v [C8 (wz b); C8 (wz b); C8 (wz c)] -> SHAD m v (repeat (b8 0) 3) ->
    v mod 8 = 0 -> aapp v 24 -> b <> 0 -> aapp b (c - b) -> b <= c ->
    aceil <= lo -> lo <= spz - VDEL_STACK -> spz <= 2 ^ 47 ->
    evt asegs (vd1_ex gp tp x22 x23 x24 x25 x26 x27 F fc spz v b m)
      (MS (mkR (Z_to_bv 64 VD1_A2) (Z_to_bv 64 (spz - 64)) gp tp w5 w6 w7 (Z_to_bv 64 v) (Z_to_bv 64 (v + 16))
               d10 d11 d12 d13 d14 d15 d16 d17 (Z_to_bv 64 (v + 8)) (vshw v) (vshw (v + 16)) (vshw (v + 8))
               x22 x23 x24 x25 x26 x27 w28 w29 w30 w31)
          F (Z_to_bv 64 VD1_A2) fc None m (seg_rom asegs)).
  Proof.
    intros until lo. intros CV SV V8 VA B0 BA BE CE LO SPH.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    pose proof (aapp_bounds b (c - b) BA ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5).
    unfold AIMG_TOP in VB1, PB1. unfold VDEL_STACK, AFREE_STACK in LO.
    lazymatch goal with |- evt _ _ (MS ?T _ _ _ _ _ _) => remember T as R3 eqn:HR3 end.
    pose (E3 := Eseed R3 [Z_to_bv 64 v; Z_to_bv 64 (spz - 64); Z_to_bv 64 b; Z_to_bv 64 c]).
    assert (HR3s : regs_ok E3 (srs sr_id
       [(2%bv, EVar 33); (8%bv, EVar 32); (9%bv, EAlu ALU_ADD (EVar 32) (ELit 16)); (18%bv, EAlu ALU_ADD (EVar 32) (ELit 8));
        (19%bv, EAlu ALU_ADD (EAlu ALU_SRL (EVar 32) (ELit 3)) (ELit 2147450880));
        (20%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 16)) (ELit 3)) (ELit 2147450880));
        (21%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 8)) (ELit 3)) (ELit 2147450880))]) R3).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R3; evs; try reflexivity;
        unfold vshw; rewrite ?w_addm, ?w_add by lia; reflexivity. }
    assert (GZV : gz m v 24) by (intros i Hi; eapply sh0_of_SHAD0; [exact SV | cbn; lia]).
    assert (HK3 : know_ok asegs E3 m
       (kn_fix 20 [AOPDEL2] (SCR [false; false; false; false] [] []) VD1_A2 (srs sr_id
          [(2%bv, EVar 33); (8%bv, EVar 32); (9%bv, EAlu ALU_ADD (EVar 32) (ELit 16)); (18%bv, EAlu ALU_ADD (EVar 32) (ELit 8));
           (19%bv, EAlu ALU_ADD (EAlu ALU_SRL (EVar 32) (ELit 3)) (ELit 2147450880));
           (20%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 16)) (ELit 3)) (ELit 2147450880));
           (21%bv, EAlu ALU_ADD (EAlu ALU_SRL (EAlu ALU_ADD (EVar 32) (ELit 8)) (ELit 3)) (ELit 2147450880))])
       [ KWord (SA (EVar 32) 0) 8 (EVar 34); KWord (SA (EVar 32) 8) 8 (EVar 34); KWord (SA (EVar 32) 16) 8 (EVar 35);
         KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) AIMG_TOP (2 ^ 47); KRange (EVar 34) AIMG_TOP (2 ^ 47);
         KAlign (EVar 32) 8 ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { kword_cell CV 0%nat (C8 (wz b)). }
      apply Forall_cons. { kword_cell CV 8%nat (C8 (wz b)). }
      apply Forall_cons. { kword_cell CV 16%nat (C8 (wz c)). }
      do 3 (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]).
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact V8]. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R3 VD1_A2 m (seg_rom asegs) HR3s HK3 200%nat [AOPDEL2] (SCR [false; false; false; false] [] []) 40%N.
    { split_scs.
      all: try (first [sc_br | vd_brw | vd_brx]).
      all: clear - E3 VA LO CE ACF1 ACF2 VB1 VB2 VB3 PB1 PB2 PB3 BE.
      all: unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO, AIMG_TOP in VA.
      all: first [ sc_shdj | sc_dj ]. }
    clear HK3.
    assert (HF3 : rfull R3) by (rewrite HR3; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF3) as HF3'. cbn [ms_regs] in HF3'.
    readback HR' HF3' HR3 HRe3.
    rreg HR' 1%bv J1. rreg HR' 2%bv J2. rreg HR' 8%bv J8. rreg HR' 9%bv J9. rreg HR' 10%bv J10.
    rreg HR' 18%bv J18. rreg HR' 19%bv J19. rreg HR' 20%bv J20. rreg HR' 21%bv J21.
    rewrite ?w_add in J9, J18, J20, J21 by lia.
    eapply evt_of_msteps; [exact Hms|].
    unfold vd1_ex, vshw. rewrite mkst_MS, HRe3, J1, J2, J8, J9, J10, J18, J19, J20, J21.
    apply evt_done.
    do 14 eexists. reflexivity.
  Qed.

  Lemma vd1_post : forall (ra gp tp s0 s1 s2 s3 s4 s5 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 x22 x23 x24 x25 x26 x27 t3 t4 t5 t6 w1 w2 w3 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v lo : Z),
    rw_cells asegs m v [C8 w1; C8 w2; C8 w3] -> accessible m v 24 -> shvis m v (v + 24) -> v mod 8 = 0 -> aapp v 24 ->
    v + 24 <= aceil ->
    rw_cells asegs m (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    stk asegs m lo spz -> aceil <= lo -> lo <= spz - VDEL_STACK -> spz <= 2 ^ 47 -> mem_inv asegs m -> ACONST m ->
    evt asegs (fun ms' => exists u5 u6 u7 u10 u11 u12 u13 u14 u15 u16 u17 u28 u29 u30 u31 m1,
        ms' = MS (mkR ra (Z_to_bv 64 spz) gp tp u5 u6 u7 s0 s1 u10 u11 u12 u13 u14 u15 u16 u17 s2 s3 s4 s5
                      x22 x23 x24 x25 x26 x27 u28 u29 u30 u31) F (ret_pc ra) fc None m1 (seg_rom asegs)
        /\ munch [(v, v + 24); (spz - 64 - AINTRIN_STACK, spz - 64)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
        /\ stk asegs m1 lo spz /\ rw_cells asegs m1 v [C8 (wz 0); C8 (wz 0); C8 (wz 0)] /\ ACONST m1)
      (MS (mkR (Z_to_bv 64 VDEL_RA_1) (Z_to_bv 64 (spz - 64)) gp tp t0 t1 t2 (Z_to_bv 64 v) (Z_to_bv 64 (v + 16))
               a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (v + 8)) (vshw v) (vshw (v + 16)) (vshw (v + 8))
               x22 x23 x24 x25 x26 x27 t3 t4 t5 t6)
          F (Z_to_bv 64 VDEL_RA_1) fc None m (seg_rom asegs)).
  Proof.
    intros until lo. intros CV ACC SHV V8 VA VCE FR ST CE LO SPH MI AC.
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5).
    unfold AIMG_TOP in VB1. unfold VDEL_STACK, AFREE_STACK in LO.
    lazymatch goal with |- evt _ _ (MS ?T _ _ _ _ _ _) => remember T as R4 eqn:HR4 end.
    pose (E4 := Eseed R4 [Z_to_bv 64 v; Z_to_bv 64 (spz - 64)]).
    assert (HR4s : regs_ok E4 (srs sr_id [(2%bv, EVar 33); (8%bv, EVar 32)]) R4).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R4; evs; reflexivity. }
    assert (HK4 : know_ok asegs E4 m
       (kn_fix 20 [AASAN_MEMSET] (SCR [] [] []) VDEL_RA_1 (srs sr_id [(2%bv, EVar 33); (8%bv, EVar 32)])
       [ KRange (EVar 33) (2 ^ 45) (2 ^ 47); KRange (EVar 32) AIMG_TOP (2 ^ 47); KAlign (EVar 32) 8 ] 40)).
    { kn_eval. unfold know_ok.
      do 2 (apply Forall_cons; [cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia|]).
      apply Forall_cons. { cbn [kentry_ok]. evs. rewrite u64_of_Z by lia. split; [lia | exact V8]. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R4 VDEL_RA_1 m (seg_rom asegs) HR4s HK4 200%nat [AASAN_MEMSET] (SCR [] [] []) 40%N.
    { split_scs. all: try (first [sc_br | vd_brw | vd_brx]). }
    clear HK4.
    assert (HF4 : rfull R4) by (rewrite HR4; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF4) as HF4'. cbn [ms_regs] in HF4'.
    readback HR' HF4' HR4 HRe4.
    rreg HR' 1%bv K1. rreg HR' 2%bv K2. rreg HR' 10%bv K10. rreg HR' 11%bv K11. rreg HR' 12%bv K12.
    eapply evt_of_msteps; [exact Hms|].
    rewrite mkst_MS, HRe4, K1, K2, K10, K11, K12.
    clear HRe4 HR' Hlf Hms HF4' K1 K2 K10 K11 K12.
    pose proof (stk_split asegs m lo (spz - 64) spz ST ltac:(lia)) as [STa STb].
    eapply evt_cut.
    { eapply (ah_memset H HH) with (c := 0) (junk := cells_bytes [C8 w1; C8 w2; C8 w3]) (lo := lo); rewrite ?u64_of_Z by lia.
      - reflexivity.
      - lia.
      - exact (rw_cells_to_CB m v [C8 w1; C8 w2; C8 w3] CV).
      - exact ACC.
      - exact SHV.
      - exact STa.
      - exact CE.
      - unfold AINTRIN_STACK; lia.
      - exact MI.
      - exact AC.
      - lia.
      - eapply aapp_in_app_mem; [exact VA | lia | lia].
      - eapply (aconst_ok_app v 24); [exact VA | cbn; lia | cbn; lia].
      - left; lia. }
    intros ms5 POST5.
    destruct POST5 as (u5 & u6 & u7 & u11 & u12 & u13 & u14 & u15 & u16 & u17 & u28 & u29 & u30 & u31 & m1 & EQ5 & MU5 & WM5 & MI5 & ST5 & ZR & AC5).
    subst ms5. rewrite ?u64_of_Z in MU5 by lia. rewrite ?u64_of_Z in ST5 by lia. rewrite ?u64_of_Z in ZR by lia. change (Z.to_nat 24) with 24%nat in ZR.
    rewrite ret_pc_even by (first [reflexivity | lia]).
    assert (FR5 : rw_cells asegs m1 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
      by (eapply rw_cells_transport; [exact FR | exact MU5 | exact WM5 | cbn; unfold AINTRIN_STACK; lia]).
    assert (ST5' : stk asegs m1 lo spz).
    { eapply (stk_merge asegs m1 lo (spz - 64) spz); [exact ST5 | | lia].
      eapply stk_transport_disjoint; [exact STb | exact MU5 | exact WM5 | cbn; unfold AINTRIN_STACK; lia]. }
    eapply evt_mono; [eapply vd1_end; [exact FR5 | lia | lia] |].
    intros ms' ->. do 15 eexists. exists m1.
    split; [reflexivity|]. split; [exact MU5|]. split; [exact WM5|]. split; [exact MI5|]. split; [exact ST5'|].
    split; [exact (vd_zero3 m1 v ZR) | exact AC5].
  Qed.

  Definition vd1_pre (ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 : word) (F : bvmap 5 word) (fc : bv 32)
      (spz v b c lo shi : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists m4, vd1_ex gp tp x22 x23 x24 x25 x26 x27 F fc spz v b m4 ms'
      /\ munch [(spz - 64 - AINTRIN_STACK, spz); (v + 8, v + 16); (sh b, sh b + nsh (c - b))] m m4
      /\ wmono asegs m m4 /\ mem_inv asegs m4 /\ stk asegs m4 lo spz
      /\ SHAD m4 b (shadow_of (c - b)) /\ ACONST m4 /\ stack0 m4 lo shi
      /\ rw_cells asegs m4 v [C8 (wz b); C8 (wz b); C8 (wz c)] /\ SHAD m4 v (repeat (b8 0) 3)
      /\ rw_cells asegs m4 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  Lemma vd1_pre_evt : forall (ra gp tp x5 x6 x7 s0 s1 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (fc : bv 32) (m : mem) (spz v b e c lo shi : Z),
    rw_cells asegs m v [C8 (wz b); C8 (wz e); C8 (wz c)] -> SHAD m v (repeat (b8 0) 3) -> v mod 8 = 0 -> aapp v 24 ->
    b <> 0 -> aapp b (c - b) -> b mod 16 = 0 -> b <= e <= c -> c - b <= 2 ^ 40 -> (e - b) mod 20 = 0 ->
    SHAD m b (cc_gen (c - b) (e - b)) -> (c <= v \/ v + 24 <= b) ->
    stack0 m lo shi -> spz <= shi ->
    stk asegs m lo spz -> aceil <= lo -> lo <= spz - VDEL_STACK -> mem_inv asegs m -> ACONST m ->
    evt asegs (vd1_pre ra gp tp s0 s1 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 F fc spz v b c lo shi m)
      (MS (mkR ra (Z_to_bv 64 spz) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 v) x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5
               x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
          F (Z_to_bv 64 VDEL_1) fc None m (seg_rom asegs)).
  Proof.
    intros until shi. intros CV SV V8 VA B0 BA B16 BE BL EM SB VBD S0 SHI ST CE LO MI AC.
    pose proof (stack0_bounds m lo shi S0) as SB0. unfold AAPP_HI in SB0.
    eapply evt_cut.
    { eapply (vd1_a ra gp tp x5 x6 x7 s0 s1 x11 x12 x13 x14 x15 x16 x17 s2 s3 s4 s5 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31
                F fc m spz v b e c lo shi);
        [exact CV | exact SV | exact V8 | exact VA | exact B0 | exact BA | exact B16 | exact BE | exact BL | exact EM
        | exact SB | exact VBD | exact S0 | exact SHI | exact ST | exact CE | exact LO | exact MI | exact AC]. }
    intros ms1 (w5 & w6 & w7 & d10 & d11 & d12 & d13 & d14 & d15 & d16 & d17 & w28 & w29 & w30 & w31 & m2
                & EQ1 & MU1 & WM1 & MI1 & ST1 & CV1 & SV1 & S01 & SB1 & AC1 & FR1).
    subst ms1.
    eapply evt_cut.
    { eapply vd1_b; [exact ST1 | exact MI1 | exact CV1 | exact SV1 | exact S01 | exact SB1 | exact AC1 | exact FR1
                    | exact V8 | exact VA | exact B0 | exact BA | exact B16 | lia | exact BL | lia
                    | exact SHI | exact CE | exact LO | lia]. }
    intros ms2 (y5 & y6 & y7 & e10 & e11 & e12 & e13 & e14 & e15 & e16 & e17 & y28 & y29 & y30 & y31 & m3
                & EQ2 & MU2 & WM2 & MI2 & ST2 & CV2 & SV2 & S02 & SH2 & AC2 & FR2).
    subst ms2.
    eapply evt_mono.
    { eapply vd1_c; [exact CV2 | exact SV2 | exact V8 | exact VA | exact B0 | exact BA | lia | exact CE | exact LO | lia]. }
    intros ms3 EX. exists m3. split; [exact EX|].
    split.
    { eapply munch_weaken; [| exact (munch_app _ _ _ _ _ MU1 MU2)].
      intros x Hx; cbn [app outside] in Hx |- *; unfold AINTRIN_STACK in Hx |- *; clear - Hx; lia. }
    split; [exact (wmono_trans asegs _ _ _ WM1 WM2)|].
    split; [exact MI2|]. split; [exact ST2|]. split; [exact SH2|]. split; [exact AC2|]. split; [exact S02|].
    split; [exact CV2|]. split; [exact SV2 | exact FR2].
  Qed.

  Lemma vdel1 : vdel_stmt_at VDEL_1 VDEL_RA_1 20.
  Proof.
    intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      F fc msF m mo s LB LF pid v b1 e1 c1 lo B shi errv
      VIS A0 CV HDR VCE B0E B1P OWN RH KR AL0 RA SPB SP16 ST CE LO ERR MI TP AC RF S0 SHI TRC.
    set (spz := bv_unsigned sp) in *.
    assert (SPZ : spz = bv_unsigned sp) by reflexivity. clearbody spz.
    assert (SPE : sp = Z_to_bv 64 spz) by (rewrite SPZ; symmetry; apply Z_to_bv_bv_unsigned).
    rewrite SPE, A0 in VIS. clear A0.
    subst tp. unfold errno_addr in ERR. rewrite u64_of_Z in ERR by (unfold ATP; lia).
    destruct HDR as (V8 & SV & f & INF & F1 & F2).
    pose proof (aceil_facts) as ACF. destruct ACF as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof (stack0_bounds m lo shi S0) as SB0. unfold AAPP_HI in SB0.
    pose proof (ah_RFS_range H HH _ _ RF) as [FSBOK FRR]. pose proof FSBOK as (FS1 & FS2 & FS3 & FS4). unfold AIMG_TOP in FS1.
    pose proof (FRR f INF) as (FK & FA1 & FA2 & _ & _). unfold AFS_HDR in FA1.
    pose proof (fsz_pos (ff_class f) ltac:(lia)) as FSZ.
    assert (VA : aapp v 24) by (eapply aapp_sub; [exact FS4 | lia | lia]).
    pose proof (aapp_bounds v 24 VA ltac:(lia)) as (VB1 & VB2 & VB3 & VB4 & VB5). unfold AIMG_TOP in VB1.
    assert (SAT : sh AIMG_TOP <= 2 ^ 45) by (apply Z.leb_le; vm_compute; reflexivity).
    assert (SSH : sh v + 3 <= AHI_LO)
      by (unfold sh, ASHADOW_BASE; unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO in VA |- *; Z.div_mod_to_equations; lia).
    assert (SVV : sh v + nsh 24 <= v \/ v + 24 <= sh v)
      by (pose proof (aapp_disjoint_sh v 24 v 24 VA ltac:(lia) ltac:(unfold AAPP_HI; lia) ltac:(lia)); lia).
    change (nsh 24) with 3 in SVV. unfold AHI_LO in SSH.
    assert (SFS : sh (as_FSB H) <= sh v /\ sh v + 3 <= sh (as_FSB H + AFS_SIZE)).
    { clear - V8 FA1 FA2 F1 F2. unfold sh. Z.div_mod_to_equations. lia. }
    assert (LOU : lo + 64 + AFREE_STACK <= spz) by (unfold VDEL_STACK in LO; lia).
    unfold AFREE_STACK in LOU.
    destruct (Z.eq_dec b1 0) as [Bz | Bnz].
    - destruct (B0E Bz) as [E0 C0]. subst b1 e1 c1.
      eapply (ahh_evt H HH); [exact KR | exact VIS | |].
      { eapply (vd1_zr ra gp (Z_to_bv 64 ATP) t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m spz v lo);
          [exact CV | exact SV | exact V8 | exact VA | exact ST | exact CE | lia | lia | exact MI | exact AC]. }
      intros msF1 mo1 KR1 MP1 (w10 & w11 & m1 & VIS1 & MU1 & WM1 & MI1 & ST1).
      assert (W1 : Forall (fun iv : Z * Z => aclient_write_ok H LB iv /\ afs_write_ok H LF iv /\ aconst_ok iv) [(spz - 56, spz)]).
      { apply Forall_cons; [| apply Forall_nil].
        split; [left; cbn; lia|].
        split; [left; cbn; unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP; split; lia|].
        apply aconst_ok_high; [cbn; lia | right; left; cbn; lia]. }
      pose proof (Forall_impl _ (fun iv (K : aclient_write_ok H LB iv /\ afs_write_ok H LF iv /\ aconst_ok iv) => proj1 K) W1) as W1C.
      pose proof (Forall_impl _ (fun iv (K : aclient_write_ok H LB iv /\ afs_write_ok H LF iv /\ aconst_ok iv) => proj1 (proj2 K)) W1) as W1F.
      pose proof (Forall_impl _ (fun iv (K : aclient_write_ok H LB iv /\ afs_write_ok H LF iv /\ aconst_ok iv) => proj2 (proj2 K)) W1) as W1A.
      pose proof (ah_costs H HH) as (_ & _ & CF0 & _).
      unfold vdel_post. rewrite <- SPZ. exists t0, t1, t2, w10, w11, a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, m1, s.
      split; [rewrite SPE; exact VIS1|].
      split; [exact KR1|]. split; [exact MP1|]. split; [exact MI1|]. split; [exact ST1|].
      split.
      { unfold errno_addr. rewrite u64_of_Z by (unfold ATP; lia).
        eapply rw_cells_transport; [exact ERR | exact MU1 | exact WM1 | cbn; unfold ATP; lia]. }
      split; [eapply (ah_rauxv_frame H HH); [exact RA | exact MU1 | exact WM1 | exact W1C]|].
      unfold vdel_LB, vdel_X. rewrite Z.eqb_refl.
      split.
      { eapply (xpres_of_munch H s LB spz _ _ m m m1); [exact HH | exact RH | exact MU1 | exact WM1 |].
        apply Forall_cons; [left; cbn; lia | apply Forall_nil]. }
      split; [eapply (ah_RHEAP_frame H HH); [exact RH | exact MU1 | exact WM1 | exact W1C]|].
      split; [exact (lb_own_wmono _ _ _ OWN WM1)|].
      split; [eapply rw_cells_transport; [exact CV | exact MU1 | exact WM1 | cbn; lia]|].
      split.
      { eapply SHAD_transport; [exact SV | exact MU1 | exact WM1 |]. cbn [length repeat Z.of_nat Pos.of_succ_nat]. cbn. lia. }
      split; [eapply (ah_RFS_frame H HH); [exact RF | exact MU1 | exact WM1 | exact W1F]|].
      split; [eapply ACONST_frame; [exact AC | exact MU1 | exact WM1 | exact W1A]|].
      split.
      { eapply stack0_transport; [exact S0 | exact MU1 | exact WM1 |].
        apply Forall_cons; [apply stack0_ok_app; cbn; unfold AHI_LO; lia | apply Forall_nil]. }
      specialize (CF0 (0 - 0) ltac:(lia)). lia.
    - destruct (B1P Bnz) as (INB & BE & BL & SB & EM & VBD).
      pose proof (ah_blocks H HH _ _ _ _ RH INB) as ABR. unfold blk_addr, blk_size in ABR. cbn [fst snd] in ABR.
      pose proof ABR as (BB0 & B16 & Bn & BI & BC & BF & BAPP). unfold AIMG_TOP in BI.
      assert (SPH : sh b1 + nsh (c1 - b1) <= AHI_LO)
        by (exact (sh_nsh_high b1 (c1 - b1) ltac:(lia) ltac:(lia) ltac:(unfold AAPP_HI; lia))).
      unfold AHI_LO in SPH.
      assert (SHL : ASHADOW_BASE <= sh b1) by (unfold sh; pose proof (Z.div_pos b1 8 ltac:(lia) ltac:(lia)); lia).
      unfold ASHADOW_BASE in SHL.
      assert (SPA : sh b1 + nsh (c1 - b1) <= sh aceil) by (unfold sh, nsh; Z.div_mod_to_equations; nia).
      eapply (ahh_evt_then H HH (vd1_pre ra gp (Z_to_bv 64 ATP) s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc spz v b1 c1 lo shi m));
        [exact KR | exact VIS | |].
      { eapply vd1_pre_evt; [exact CV | exact SV | exact V8 | exact VA | exact Bnz | exact BAPP | exact B16 | exact BE | exact BL
                            | exact EM | exact SB | lia | exact S0 | exact SHI | exact ST | exact CE | exact LO | exact MI | exact AC]. }
      intros msF1 mo1 KR1 MP1 (m1 & (w5 & w6 & w7 & u11 & u12 & u13 & u14 & u15 & u16 & u17 & w28 & w29 & w30 & w31 & VIS1)
                               & MU1 & WM1 & MI1 & ST1 & SH1 & AC1 & S01 & CV1 & SV1 & FR1).
      assert (W1 : Forall (fun iv : Z * Z => aclient_write_ok H LB iv /\ afs_write_ok H LF iv /\ aconst_ok iv)
                     [(spz - 64 - AINTRIN_STACK, spz); (v + 8, v + 16); (sh b1, sh b1 + nsh (c1 - b1))]).
      { apply Forall_cons.
        { split; [left; cbn; unfold AINTRIN_STACK; lia|].
          split; [left; cbn; unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, AINTRIN_STACK; split; lia|].
          apply aconst_ok_high; [cbn; unfold AINTRIN_STACK; lia | right; left; cbn; unfold AINTRIN_STACK; lia]. }
        apply Forall_cons.
        { split; [right; right; right; right; left; cbn; lia|].
          split; [right; exists f; split; [exact INF | cbn; lia]|].
          eapply (aconst_ok_app v 24); [exact VA | cbn; lia | cbn; lia]. }
        apply Forall_cons; [| apply Forall_nil].
        split; [right; right; right; left; exists (pid, b1, c1 - b1); split; [exact INB | cbn; lia]|].
        split.
        { left. cbn. pose proof (aapp_disjoint_sh (as_FSB H) AFS_SIZE b1 (c1 - b1) FS4 ltac:(lia) ltac:(unfold AAPP_HI; lia) ltac:(lia)) as S.
