      assert (CV2 : rw_cells asegs m2 v [C8 (wz b1); C8 (wz b1); C8 (wz c1)]).
      { eapply (apres_rw_cells H); [exact AP2 | exact CV1 | right; right; right; right; left; cbn; lia]. }
      assert (SV2 : SHAD m2 v (repeat (b8 0) 3)).
      { eapply (apres_SHAD H); [exact AP2 | exact SV1 | right; right; right; right; right; left; cbn; lia]. }
      assert (FR2 : rw_cells asegs m2 (spz - 56) [C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
      { eapply (apres_rw_cells H); [exact AP2 | exact FR1 | left; lia]. }
      assert (ST2' : stk asegs m2 lo spz).
      { apply (stk_merge asegs m2 lo (spz - 64) spz); [exact ST2 | | lia].
