      assert (ACC2 : accessible m2 v 24) by (eapply (addressable_accessible m2 v 24); [exact AD2 | lia | lia | unfold AAPP_HI; lia]).
      assert (SHV2 : shvis m2 v (v + 24)) by (eapply shvis_sub; [exact (ah_frm_shvis H HH _ _ f RF2 INF) | lia | lia | lia | lia | lia]).
      eapply (ahh_evt_then H HH); [exact KR2 | exact VIS2 | |].
      { eapply vd1_post; [exact CV2 | exact ACC2 | exact SHV2 | exact V8 | exact VA | lia | exact FR2 | exact ST2' | exact CE | exact LO
                         | lia | exact MI2 | exact AC2]. }
      intros msF3 mo3 KR3 MP3 (u5 & u6 & u7 & u10 & u11' & u12' & u13' & u14' & u15' & u16' & u17' & u28 & u29 & u30 & u31 & m3
                               & VIS3 & MU3 & WM3 & MI3 & ST3 & ZR3 & AC3).
      apply (ah_done H HH).
      assert (W3 : Forall (fun iv : Z * Z => aclient_write_ok H LB' iv /\ afs_write_ok H LF iv /\ aconst_ok iv)
