        split; [left; cbn; unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, AINTRIN_STACK; split; lia|].
        apply aconst_ok_high; [cbn; unfold AINTRIN_STACK; lia | right; left; cbn; unfold AINTRIN_STACK; lia]. }
      pose proof (Forall_impl _ (fun iv (K : aclient_write_ok H LB' iv /\ afs_write_ok H LF iv /\ aconst_ok iv) => proj1 K) W3) as W3C.
      pose proof (Forall_impl _ (fun iv (K : aclient_write_ok H LB' iv /\ afs_write_ok H LF iv /\ aconst_ok iv) => proj1 (proj2 K)) W3) as W3F.
      unfold vdel_post. rewrite <- SPZ.
      exists u5, u6, u7, u10, u11', u12', u13', u14', u15', u16', u17', u28, u29, u30, u31, m3, sA.
      split; [rewrite SPE; exact VIS3|].
      split; [exact KR3|].
      split; [eapply (ah_mpres_trans H HH); [exact MP1 | eapply (ah_mpres_trans H HH); [exact MP2 | exact MP3]]|].
