      split; [eapply (ah_rauxv_frame H HH); [exact RA2 | exact MU3 | exact WM3 | exact W3C]|].
      unfold vdel_LB, vdel_X. rewrite (proj2 (Z.eqb_neq b1 0) Bnz). fold LB'.
