  Lemma obj_facts : forall off, 0 <= off -> off + 40 <= 240 -> off mod 8 = 0 ->
    (AIMG_TOP <= st1 + off /\ st1 + off + 40 <= aceil /\ (st1 + off) mod 8 = 0 /\ in_app_mem (st1 + off) (st1 + off + 40))
    /\ (AIMG_TOP <= st2 + off /\ st2 + off + 40 <= 2 ^ 47 /\ (st2 + off) mod 8 = 0 /\ in_app_mem (st2 + off) (st2 + off + 40)
