  Lemma INV_step_z : forall s LBc m cA cB L s' LB' m' LBk o w cA' cB' L',
    INV s LBc m cA cB L ->
    xpres H LBk spz (XW o w) m m' -> 0 <= o -> 0 <= w -> o + w <= 240 ->
    (forall b, In b LB0 -> In b LBk) ->
    mem_inv asegs m' -> stk asegs m' lo spz -> rw_cells asegs m' (errno_addr tp) [C4 errv] -> as_rauxv_ok H m' B ->
    ACONST m' -> as_RFS H LF m' -> stack0 m' lo shi -> as_RHEAP H s' LB' m' -> lb_own LB' m' ->
    LbB_HStNT.sto_frame m' spf ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 ->
    as_AL H s' >= as_AL H s ->
    state_repA LB' m' st1 cA' -> state_sh m' cA' -> state_repA LB' m' st2 cB' -> state_sh m' cB' ->
    Permutation LB' (LB0 ++ L') ->
    INV s' LB' m' cA' cB' L'.
Proof.
    intros s LBc m cA cB L s' LB' m' LBk o w cA' cB' L' IV XP Ho Hw How SUB MI' STK' ERR' RA' AC' RFS' S0' RH' OWN' FR' AL'
      R1' SH1' R2' SH2' PRM'.
    destruct IV as (MI & STK & ERR & RA & AC & RFS & S0 & RH & OWN & FR & R1 & SH1 & R2 & SH2 & AD1 & AD2 & PRM & XP0 & AL).
    pose proof aceil_facts as ((ACL & ACH) & ACM & ACC).
    unfold ST_SIZE in *. assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    pose proof FSBOK as (FB1 & FB2 & FB3 & FB4).
    assert (ASTK : 96 < AST_MVA_STACK) by (unfold AST_MVA_STACK, AFREE_STACK; lia).
    assert (SHL : forall x, sh 0 + x / 8 = sh x) by (intros x; unfold sh; rewrite Zdiv_0_l; lia).
    assert (SH0 : sh 0 = 2147450880) by reflexivity.
    assert (SHC : forall x, x mod 8 = 0 -> 0 <= x -> x + 240 <= 2 ^ 47 ->
                  ((as_FSB H <= x /\ x + 240 <= as_FSB H + AFS_SIZE) \/ aceil <= x) ->
                  forall a, sh x <= a < sh x + nsh 240 -> xclient H LBk spz (XW o w) a).
    { intros x X8 X0 XH XR a Ha.
      assert (E : sh x + nsh 240 = sh (x + 240)).
      { replace (x + 240) with (x + 8 * 30) by lia. rewrite sh_add8. reflexivity. }
      pose proof (sh_nsh_high x 240 X0 ltac:(lia) ltac:(unfold AAPP_HI; lia)) as SNH.
      rewrite E in Ha, SNH.
      pose proof (sh_mono 0 x X0) as M0.
      split.
      - destruct XR as [XR|XR].
        + right; right; right; right; right; left. split.
          * eapply Z.le_trans; [apply sh_mono; exact (proj1 XR) | exact (proj1 Ha)].
          * eapply Z.lt_le_trans; [exact (proj2 Ha) | apply sh_mono; exact (proj2 XR)].
        + right; right; right; right; right; right. split; [eapply Z.le_trans; [apply sh_mono; exact XR | exact (proj1 Ha)] | lia].
      - unfold XW. cbn [rin_ivs fst snd].
        unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO in *. unfold AHI_LO in SNH.
        destruct FS2 as [K|K]; lia. }
    assert (XP1 : xpres H LB0 spz XST m0 m').
    { eapply xpres_trans; [exact XP0 |].
      eapply xpres_weaken; [exact XP | lia | exact SUB |].
      intros a Ha. unfold XW, XST in *. cbn [rin_ivs fst snd] in *. lia. }
    unfold INV.
    refine (conj MI' (conj STK' (conj ERR' (conj RA' (conj AC' (conj RFS' (conj S0' (conj RH' (conj OWN' (conj FR'
      (conj R1' (conj SH1' (conj R2' (conj SH2' (conj _ (conj _ (conj PRM' (conj XP1 _)))))))))))))))))).
    - eapply addressable_xp; [exact XP | exact AD1 |]. apply SHC; [exact ST1A | lia | lia | left; exact FS1].
    - eapply addressable_xp; [exact XP | exact AD2 |]. apply SHC; [exact ST2A | lia | | ].
      + destruct FS2 as [K|K]; [lia|]. unfold AAPP_HI in SHH. lia.
      + destruct FS2 as [K|K]; [left; exact K | right; lia].
    - lia.
  Qed.

  Ltac inapp_solve :=
    match goal with Hb : In ?b _ |- In ?b _ =>
      rewrite <- ?app_assoc in Hb; rewrite <- ?app_assoc;
      repeat rewrite in_app_iff in Hb; repeat rewrite in_app_iff;
      repeat match type of Hb with _ \/ _ => destruct Hb as [Hb|Hb] end;
      repeat (first [exact Hb | left; exact Hb | right])
    end.

  Lemma umap_sh_eta : forall (V : Type) m n (t : Z * Z * list (Z * (Z * V))),
    umap_sh m n (t3a t, t3b t, t3c t) <-> umap_sh m n t.
  Proof. intros V m n [[a b] c]. reflexivity. Qed.

  Lemma umap_sh_E3 : forall m n, umap_sh m n E3.
  Proof. intros m n. unfold umap_sh, E3, t3a, t3b, t3c. cbn [fst snd]. split; [intros C; exfalso; apply C; reflexivity | intros p k v []]. Qed.

  Lemma umap_sh_E3N : forall m n, umap_sh m n E3N.
  Proof. intros m n. unfold umap_sh, E3N, t3a, t3b, t3c. cbn [fst snd]. split; [intros C; exfalso; apply C; reflexivity | intros p k v []]. Qed.

  Lemma in_lbl_allb : forall (Lx : list block) b, In b Lx -> (forall b', In b' Lx -> In b' ALLB) ->
    (blk_addr b + blk_size b <= st1 \/ st1 + 240 <= blk_addr b) /\ (blk_addr b + blk_size b <= st2 \/ st2 + 240 <= blk_addr b).
  Proof.
    intros Lx [[p A] n] Hb SUBx. apply BAP. apply allb_lbl. apply (lbl_in ALLB p A n). exact (SUBx _ Hb).
  Qed.

  Ltac sv_lgcell Hlf WA k :=
    eapply (rw_cells_log_nth _ _ _ k);
    [ exact Hlf | reflexivity
    | repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia;
                                  cbn [a_off Z.of_nat Pos.of_succ_nat Pos.succ]; lia|]); apply Forall_nil
    | unfold estart; evs; rewrite ?u64_of_Z by lia; cbn [a_off]; lia
    | exact WA | reflexivity | exact I
    | first [ reflexivity | evs; rewrite ?w_add by lia; reflexivity
            | evs; match goal with HRx : ?R = mkR _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ =>
                     rewrite HRx; reflexivity end ] ].

  Ltac sv_brw := lazymatch goal with |- sc_denot _ _ _ (SCBr _ _ _ _) => idtac end; cbn [sc_denot]; evs;
    rewrite ?w_addm, ?w_add by lia; rewrite ?br_eq, ?br_ne, ?br_ltu, ?br_geu by lia; bool_lia.
  Definition AST_V1R : Z := 0xed284.
  Definition AST_V2R : Z := 0xed32c.
  Definition AST_V3R : Z := 0xed3d4.

  Lemma sv_split3 : forall m a w0 w1 w2, rw_cells asegs m a [C8 w0; C8 w1; C8 w2] ->
    rw_cells asegs m a [C8 w0] /\ rw_cells asegs m (a + 8) [C8 w1] /\ rw_cells asegs m (a + 16) [C8 w2].
  Proof.
    intros m a w0 w1 w2 HC. change [C8 w0; C8 w1; C8 w2] with ([C8 w0] ++ [C8 w1] ++ [C8 w2]) in HC.
    apply rw_cells_app in HC. destruct HC as [H0 HC]. cbn [cells_size csize] in HC.
    apply rw_cells_app in HC. destruct HC as [H1 H2]. cbn [cells_size csize] in H2.
    split; [exact H0|]. split; [replace (a + 8) with (a + Z.of_nat (8 + 0)) by lia; exact H1|].
    replace (a + 16) with (a + Z.of_nat (8 + 0) + Z.of_nat (8 + 0)) by lia. exact H2.
  Qed.

  Lemma sv_cells_of_vraw : forall L m A b e c, vraw MI_A L m A b e c -> AIMG_TOP <= A -> A + 24 <= 2 ^ 64 ->
    rw_cells asegs m A [C8 (wz b); C8 (wz e); C8 (wz c)].
  Proof.
    intros L m A b e c [VB VE VC _] HA HA2.
    apply rw_cells_cons8_c; [exact (rw_cells_of_cellw8 m A b VB HA ltac:(lia))|].
    apply rw_cells_cons8_c; [exact (rw_cells_of_cellw8 m (A + 8) e VE ltac:(lia) ltac:(lia))|].
    replace (A + 8 + 8) with (A + 16) by lia. exact (rw_cells_of_cellw8 m (A + 16) c VC ltac:(lia) ltac:(lia)).
  Qed.

  Lemma sv_vraw_rng : forall L m A b e c, vraw MI_A L m A b e c -> 0 <= b < 2 ^ 64 /\ 0 <= e < 2 ^ 64 /\ 0 <= c < 2 ^ 64.
  Proof.
    intros L m A b e c [[RB _] [RE _] [RC _] _]. cbn in RB, RE, RC. lia.
  Qed.

  Lemma sv_vraw_move : forall L m m' A A' b e c, vraw MI_A L m A b e c ->
    rw_cells asegs m' A' [C8 (wz b); C8 (wz e); C8 (wz c)] -> 0 <= A' -> vraw MI_A L m' A' b e c.
  Proof.
    intros L m m' A A' b e c V CW HA. pose proof (sv_vraw_rng _ _ _ _ _ _ V) as (RB & RE & RC).
    destruct V as [_ _ _ VK]. pose proof (sv_split3 _ _ _ _ _ CW) as (C0 & C1 & C2).
    constructor; [exact (cellw8_of_rw_cells m' A' b C0 RB HA) | exact (cellw8_of_rw_cells m' (A' + 8) e C1 RE ltac:(lia))
                 | exact (cellw8_of_rw_cells m' (A' + 16) c C2 RC ltac:(lia)) | exact VK].
  Qed.

  Lemma sv_vraw0 : forall L m A, rw_cells asegs m A [C8 (wz 0); C8 (wz 0); C8 (wz 0)] -> 0 <= A -> vraw MI_A L m A 0 0 0.
  Proof.
    intros L m A CW HA. pose proof (sv_split3 _ _ _ _ _ CW) as (C0 & C1 & C2).
    constructor; [exact (cellw8_of_rw_cells m A 0 C0 ltac:(lia) HA) | exact (cellw8_of_rw_cells m (A + 8) 0 C1 ltac:(lia) ltac:(lia))
                 | exact (cellw8_of_rw_cells m (A + 16) 0 C2 ltac:(lia) ltac:(lia)) | left; repeat split].
  Qed.

  Lemma sv_vdel_xp : forall s LB mq0 pid bq cq v m m', as_RHEAP H s LB mq0 -> (bq <> 0 -> In (pid, bq, cq - bq) LB) ->
    xpres H (vdel_LB H LB pid bq) spf (vdel_X v bq cq) m m' -> xpres H (vdel_LB H LB pid bq) spf [(v, v + 24)] m m'.
  Proof.
    intros s LB mq0 pid bq cq v m m' RH IN. unfold vdel_LB, vdel_X. destruct (Z.eqb_spec bq 0) as [E|E]; intros XP.
    - rewrite app_nil_r in XP. exact XP.
    - apply (xpres_drop_blk H HH s LB pid bq (cq - bq) spf [(v, v + 24)] mq0 m m' RH (IN E));
        [unfold spf, AST_MVA_STACK, AFREE_STACK in *; lia|].
      replace (bq + (cq - bq)) with cq by lia. exact XP.
  Qed.

  Lemma sv_gz : forall m A n o k, addressable m A n -> 0 <= o -> o + k <= 8 * (n / 8) -> gz m (A + o) k.
  Proof. intros m A n o k AD Ho Hk i Hi. apply (sh0_of_addressable m A n); [exact AD | lia]. Qed.

  Lemma sv_wr8 : forall m A n, wr_at asegs m A n -> forall a, A <= a -> a + 8 <= A + n -> wr_at asegs m a 8.
  Proof.
    intros m A n (W1 & W2 & W) a X1 X2. split; [lia|]. split; [lia|].
    intros i Hi. replace (a + i) with (A + (a - A + i)) by lia. apply W. lia.
  Qed.

  Lemma vcp3 : forall (m : mem) (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word)
      (F : bvmap 5 word) (b e c : Z),
    rw_cells asegs m (st2 + 216) [C8 (wz b); C8 (wz e); C8 (wz c)] -> wr_at asegs m (st1 + 216) 24 ->
    gz m (st1 + 216) 24 -> gz m (st2 + 216) 24 -> mem_inv asegs m ->
    0 <= b < 2 ^ 64 -> 0 <= e < 2 ^ 64 -> 0 <= c < 2 ^ 64 ->
    evt asegs (fun ms' => exists M2,
        ms' = MS (mkR (Z_to_bv 64 AST_FIN) (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2)
                      (Z_to_bv 64 (st2 + 216)) (Z_to_bv 64 0) (Z_to_bv 64 24) x13 x14 x15 x16 x17
                      (Z_to_bv 64 (st2 + 216)) (Z_to_bv 64 (st1 + 216)) x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                 F (Z_to_bv 64 AASAN_MEMSET) fc None M2 (seg_rom asegs)
        /\ munch [(st1 + 216, st1 + 216 + 24)] m M2 /\ wmono asegs m M2 /\ mem_inv asegs M2
        /\ rw_cells asegs M2 (st1 + 216) [C8 (wz b); C8 (wz e); C8 (wz c)])
      (MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13 x14 x15 x16 x17
               (Z_to_bv 64 (st2 + 216)) (Z_to_bv 64 (st1 + 216)) x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
          F (Z_to_bv 64 AST_V3R) fc None m (seg_rom asegs)).
  Proof.
    intros m x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 F b e c CW WA GZ1 GZ2 MI Rb Re Rc.
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (ZA1 : st1 + 240 <= ALOWSH_LO \/ AHI_LO <= st1).
    { pose proof FSBOK as (_ & _ & _ & FA). assert (VA : aapp st1 240) by (eapply aapp_sub; [exact FA | lia | lia]).
      unfold aapp, aapp_lo, aapp_hi in VA. lia. }
    assert (ZA2 : st2 + 240 <= ALOWSH_LO \/ AHI_LO <= st2).
    { pose proof FSBOK as (_ & _ & _ & FA). destruct FS2 as [K|K].
      - assert (VA : aapp st2 240) by (eapply aapp_sub; [exact FA | lia | lia]). unfold aapp, aapp_lo, aapp_hi in VA. lia.
      - right. unfold AHI_LO. lia. }
    lazymatch goal with |- evt _ _ (MS ?T _ _ _ _ _ _) => remember T as R eqn:HR0 end.
    pose (E := Eseed R [Z_to_bv 64 st1; Z_to_bv 64 st2; wz b; wz e; wz c]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EVar 32); (9%bv, EVar 33); (18%bv, EAlu ALU_ADD (EVar 33) (ELit 216));
                                       (19%bv, EAlu ALU_ADD (EVar 32) (ELit 216)); (22%bv, ELit 2147450880)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; rewrite ?w_add by lia; reflexivity] |]).
      apply Forall_nil. }
    assert (HK : know_ok asegs E m
       (kn_fix 20 [AASAN_MEMSET] (SCR [] [] []) AST_V3R
          (srs sr_id [(8%bv, EVar 32); (9%bv, EVar 33); (18%bv, EAlu ALU_ADD (EVar 33) (ELit 216));
                      (19%bv, EAlu ALU_ADD (EVar 32) (ELit 216)); (22%bv, ELit 2147450880)])
       [ KWord (SA (EVar 33) 216) 8 (EVar 34); KWord (SA (EVar 33) 224) 8 (EVar 35); KWord (SA (EVar 33) 232) 8 (EVar 36);
         KWr (SA (EVar 32) 216) (ELit 24) ] 40)).
    { kn_eval. unfold know_ok.
      apply Forall_cons. { kword_cell CW 0%nat (C8 (wz b)). }
      apply Forall_cons. { kword_cell CW 8%nat (C8 (wz e)). }
      apply Forall_cons. { kword_cell CW 16%nat (C8 (wz c)). }
      apply Forall_cons.
      { eapply kwr_of_wr_at; [exact WA | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off]; lia
                             | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; cbn [a_off]; lia
                             | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
      know_tac. }
    xrun_at (PropExec.mkFP F fc) asegs R AST_V3R m (seg_rom asegs) HR HK 80%nat [AASAN_MEMSET] (SCR [] [] []) 40%N.
    { split_scs. all: try (first [sc_br | sv_brw]). all: clear - E ST1L ST1H ST2L ST2H AP12 AIT ZA1 ZA2. all: unfold ALOWSH_LO, AHI_LO in ZA1, ZA2.
      all: first [ sc_shdj | sc_dj ]. }
    lazymatch type of Hlf with log_flat _ ?lg =>
      lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
        change mm with (mem_denot E m lg) in Hms; set (M2 := mem_denot E m lg) in Hms end end.
    assert (HF : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rreg HR' 1%bv L1. rreg HR' 8%bv L8. rreg HR' 9%bv L9. rreg HR' 10%bv L10. rreg HR' 11%bv L11. rreg HR' 12%bv L12.
    rreg HR' 18%bv L18. rreg HR' 19%bv L19. rreg HR' 22%bv L22.
    rewrite ?w_add in L10, L18, L19 by lia.
    assert (MU : munch [(st1 + 216, st1 + 216 + 24)] m M2).
    { subst M2. clear - Hlf ST1L ST1H AIT. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite u64_of_Z by lia;
                                  cbn [inside Z.of_nat Pos.of_succ_nat Pos.succ a_off]; lia|]).
      apply Forall_nil. }
    assert (WM : wmono asegs m M2) by (subst M2; apply wmono_mem_denot).
    assert (MI2 : mem_inv asegs M2) by exact (msteps_mem_inv asegs _ _ Hms MI).
    pose proof (sv_wr8 m (st1 + 216) 24 WA) as WS.
    assert (CW2 : rw_cells asegs M2 (st1 + 216) [C8 (wz b); C8 (wz e); C8 (wz c)]).
    { apply rw_cells_cons8_c. { subst M2. sv_lgcell Hlf (WS (st1 + 216) ltac:(lia) ltac:(lia)) 2%nat. }
      apply rw_cells_cons8_c. { subst M2. sv_lgcell Hlf (WS (st1 + 216 + 8) ltac:(lia) ltac:(lia)) 1%nat. }
      subst M2. sv_lgcell Hlf (WS (st1 + 216 + 8 + 8) ltac:(lia) ltac:(lia)) 0%nat. }
    eapply evt_of_msteps; [exact Hms|].
    rewrite mkst_MS, HRe, L1, L8, L9, L10, L11, L12, L18, L19, L22.
    apply evt_done. exists M2.
    split; [reflexivity|]. split; [exact MU|]. split; [exact WM|]. split; [exact MI2 | exact CW2].
  Qed.
  Lemma sv2_cells_same : forall m A cs cs', rw_cells asegs m A cs -> cells_wf cs' ->
    cells_bytes cs' = cells_bytes cs -> cells_size cs' = cells_size cs -> rw_cells asegs m A cs'.
  Proof.
    intros m A cs cs' [[_ HB] HW] Wf EB ES. split; [split; [exact Wf | rewrite EB; exact HB] | rewrite ES; exact HW].
  Qed.

  Lemma sv2_zero3 : forall m A, rw_cells asegs m A [CB 24 (poison_bytes 24 0)] ->
    rw_cells asegs m A [C8 (wz 0); C8 (wz 0); C8 (wz 0)].
  Proof.
    intros m A HC. eapply sv2_cells_same; [exact HC | cbn; tauto | vm_compute; reflexivity | reflexivity].
