  Lemma sv2_cb3 : forall m A b e c, rw_cells asegs m A [C8 (wz b); C8 (wz e); C8 (wz c)] ->
    rw_cells asegs m A [CB 24 (cells_bytes [C8 (wz b); C8 (wz e); C8 (wz c)])].
