    intros m A b e c HC. eapply sv2_cells_same; [exact HC | | exact (app_nil_r (cells_bytes [C8 (wz b); C8 (wz e); C8 (wz c)])) | reflexivity].
    cbn [cells_wf cell_wf]. split; [| exact I]. apply (cells_bytes_length [C8 (wz b); C8 (wz e); C8 (wz c)]). cbn; tauto.
  Qed.

  Lemma sv2_vraw_re : forall L L' m A b e c, vraw MI_A L m A b e c ->
    (b <> 0 -> In (b, c - b) L') -> vraw MI_A L' m A b e c.
  Proof.
    intros L L' m A b e c [VB VE VC VK] HI. constructor; [exact VB | exact VE | exact VC |].
    destruct VK as [K | (K1 & K2 & K3)]; [left; exact K | right; split; [exact K1 | split; [exact (HI K1) | exact K3]]].
