  Lemma sv1_shc : forall LBk SP X x, 0 <= x -> x + 240 <= 2 ^ 47 ->
    ((as_FSB H <= x /\ x + 240 <= as_FSB H + AFS_SIZE) \/ aceil <= x) ->
    (forall a, rin_ivs X a -> (st1 <= a < st1 + 240) \/ (st2 <= a < st2 + 240)) ->
    forall a, sh x <= a < sh x + nsh 240 -> xclient H LBk SP X a.
  Proof.
    intros LBk SP X x X0 XH XR XX a Ha.
    pose proof (sv2_shr x X0 XH a Ha) as SR.
    pose proof (sv2_appx st1 (or_introl eq_refl)) as AX1.
    pose proof (sv2_appx st2 (or_intror eq_refl)) as AX2.
    assert (E : sh x + nsh 240 = sh (x + 240)).
    { replace (x + 240) with (x + 8 * 30) by lia. rewrite sh_add8. reflexivity. }
    rewrite E in Ha.
    split.
    - destruct XR as [XR|XR].
      + right; right; right; right; right; left. split.
        * eapply Z.le_trans; [apply sh_mono; exact (proj1 XR) | exact (proj1 Ha)].
        * eapply Z.lt_le_trans; [exact (proj2 Ha) | apply sh_mono; exact (proj2 XR)].
      + right; right; right; right; right; right. split; [eapply Z.le_trans; [apply sh_mono; exact XR | exact (proj1 Ha)] | lia].
    - intros K. destruct (XX a K) as [K1|K1]; lia.
  Qed.

  Lemma sv1_blkx : forall LBk LBb X (Lx : list block),
    (forall b, In b Lx -> In b LBk /\ In b LBb) -> (forall b, In b Lx -> In b ALLB) ->
