    BLKX H LBk spf X LBb (lbl Lx).
  Proof.
    intros LBk LBb X Lx SUB ALL XR. apply blkx_intro. intros p n Hin.
    destruct (lbl_in_inv _ _ _ Hin) as (q & Hq).
    destruct (SUB _ Hq) as [K1 K2].
    pose proof (in_lbl_allb Lx (q, p, n) Hq ALL) as D. unfold blk_addr, blk_size in D. cbn [fst snd] in D.
    split; [exact (lbl_in LBk q p n K1)|]. split; [exact (lbl_in LBb q p n K2)|].
    intros a Ha K. destruct (XR a K) as [K3|K3]; lia.
  Qed.

