    assert (INV2 : INV sA LB' m3 (state_moved c1 c2) (state_emptied c2) L6)
      by exact (INV_step sA LB' m1 (set_v3 cA5 V0) cB5 L6 sA LB' m3 LB' 216 24 (state_moved c1 c2) (state_emptied c2) L6 INV1 XP13
                 ltac:(lia) ltac:(lia) ltac:(lia) SUB0 MI3 STK3 ERR3 RA3 AC3 RFS3 S03 RH3 OWN3 ltac:(lia) R1'' SH1'' R2'' SH2'' PL).
    eapply (stage_end sA LB' m3 msF4 mo4); [exact VIS4 | exact KR4 | | exact INV2].
    eapply (ah_mpres_trans H HH); [exact MP|].
    eapply (ah_mpres_trans H HH); [exact MP1|].
    eapply (ah_mpres_trans H HH); [exact MP2|].
    eapply (ah_mpres_trans H HH); [exact MP3 | exact MP4].
  Qed.

  Lemma stage_v2 : forall s LBc m msF mo
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word) (F : bvmap 5 word),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 AST_V2) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    INV s LBc m cA4 cB4 L4 ->
    as_SR H QF (mkCfg msF mo).
Proof.
    intros s LBc m msF mo x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 F
      VIS KR MP IV.
    pose proof IV as IV0.
    destruct IV as (MI & STK & ERR & RA & AC & RFS & S0 & RH & OWN & FR & R1 & SH1 & R2 & SH2 & AD1 & AD2 & PRM & XP0 & ALs).
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    pose proof FSBOK as (FB1 & FB2 & FB3 & FB4).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (SPF16 : spf mod 16 = 0) by (unfold spf; rewrite Zminus_mod, SP16; reflexivity).
    assert (Uspf : bv_unsigned (Z_to_bv 64 spf) = spf) by (apply u64_of_Z; unfold spf; lia).
    assert (U2v : bv_unsigned (Z_to_bv 64 (st2 + 192)) = st2 + 192) by (apply u64_of_Z; lia).
    assert (U24 : bv_unsigned (Z_to_bv 64 24) = 24) by (apply u64_of_Z; lia).
    assert (LOHf : aceil <= lo /\ lo <= spf - 96 - AFREE_STACK) by (unfold spf, AST_MVA_STACK in *; lia).
    assert (SWb : aceil <= spf - AINTRIN_STACK) by (unfold spf, AINTRIN_STACK, AST_MVA_STACK, AFREE_STACK in *; lia).
    assert (EAB : 0 <= errno_addr tp /\ errno_addr tp + 4 <= AIMG_TOP).
    { rewrite TPV. split; apply Z.leb_le; vm_compute; reflexivity. }
    assert (ASTK : 96 < AST_MVA_STACK) by (unfold AST_MVA_STACK, AFREE_STACK; lia).
    assert (STKf : stk asegs m lo spf) by exact (proj1 (stk_split asegs m lo spf spz STK ltac:(unfold spf; lia))).
    assert (AX1 : st1 + 240 <= ALOWSH_LO \/ AHI_LO <= st1) by exact (sv2_appx st1 (or_introl eq_refl)).
    assert (AX2 : st2 + 240 <= ALOWSH_LO \/ AHI_LO <= st2) by exact (sv2_appx st2 (or_intror eq_refl)).

    pose proof (sr_v2 _ _ _ _ _ _ _ (proj1 R1)) as V1. change (st_v2 cA4) with (st_v2 c1) in V1.
    pose proof (sr_v2 _ _ _ _ _ _ _ (proj1 R2)) as V2. change (st_v2 cB4) with (st_v2 c2) in V2.
    assert (SV1 : vec_sh m (st_v2 c1)) by exact (proj1 (proj2 (proj2 (proj2 (proj2 SH1))))).
    assert (SV2 : vec_sh m (st_v2 c2)) by exact (proj1 (proj2 (proj2 (proj2 (proj2 SH2))))).
    assert (VSt1 : t3a (st_v2 c1) <> 0 -> (t3b (st_v2 c1) - t3a (st_v2 c1)) mod 4 = 0) by exact (proj1 (proj2 (proj2 R1))).
    assert (VSt2 : t3a (st_v2 c2) <> 0 -> (t3b (st_v2 c2) - t3a (st_v2 c2)) mod 4 = 0) by exact (proj1 (proj2 (proj2 R2))).
    assert (CA5 : exists pid, (t3a (st_v2 c1) = 0 /\ A5 = [])
                    \/ (t3a (st_v2 c1) <> 0 /\ A5 = [(pid, t3a (st_v2 c1), t3c (st_v2 c1) - t3a (st_v2 c1))])).
    { destruct (vec_blk_cases A5 (st_v2 c1) LA5) as [K | (K & pid & K2)];
        [exists 0; left; exact K | exists pid; right; split; [exact K | exact K2]]. }
    destruct CA5 as (pid & CA5).
    pose proof (vec_blk_cases B5 (st_v2 c2) LB5) as CB5.
    set (b1 := t3a (st_v2 c1)) in *. set (e1 := t3b (st_v2 c1)) in *. set (q1 := t3c (st_v2 c1)) in *.
    set (b2 := t3a (st_v2 c2)) in *. set (e2 := t3b (st_v2 c2)) in *. set (q2 := t3c (st_v2 c2)) in *.
    pose proof (sv_vraw_rng _ _ _ _ _ _ V2) as (Rb2 & Re2 & Rq2).

    assert (CW1 : rw_cells asegs m (st1 + 192) [C8 (wz b1); C8 (wz e1); C8 (wz q1)])
      by exact (sv_cells_of_vraw _ _ _ _ _ _ V1 ltac:(lia) ltac:(lia)).
    assert (CW2 : rw_cells asegs m (st2 + 192) [C8 (wz b2); C8 (wz e2); C8 (wz q2)])
      by exact (sv_cells_of_vraw _ _ _ _ _ _ V2 ltac:(lia) ltac:(lia)).
    assert (ADv1 : addressable m (st1 + 192) 24)
      by exact (addressable_sub8 m st1 240 192 24 AD1 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (HDR : vdel_hdr_ok LF (st1 + 192) m).
    { split; [rewrite Zplus_mod, ST1A; reflexivity|]. split; [exact (proj2 ADv1)|].
      destruct FST1 as (f & Hf & Hf1 & Hf2). exists f. split; [exact Hf | lia]. }
    assert (BZ : b1 = 0 -> e1 = 0 /\ q1 = 0).
    { intros K. pose proof V1 as [_ _ _ VK]. destruct VK as [(_ & K2 & K3) | (K1 & _)]; [split; assumption | contradiction]. }
    assert (IN1 : b1 <> 0 -> In (b1, q1 - b1) (state_blocks c1)).
    { intros K. rewrite state_blocks_cb. do 4 (apply in_or_app; right). apply in_or_app; left. exact (sv2_vblk_in (st_v2 c1) K). }
    assert (INpid : b1 <> 0 -> In (pid, b1, q1 - b1) LBc).
    { intros K. destruct CA5 as [(K1 & _) | (_ & EA)]; [contradiction|].
      assert (Hb : In (pid, b1, q1 - b1) A5) by (rewrite EA; left; reflexivity).
      eapply Permutation_in; [apply Permutation_sym; exact PRM|]. unfold L4. inapp_solve. }

    lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
    pose (E := Eseed R [Z_to_bv 64 st1; Z_to_bv 64 st2]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EVar 32); (9%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (HK : know_ok asegs E m []) by (apply Forall_nil).
    xrun_at (PropExec.mkFP F fc) asegs R AST_V2 m (seg_rom asegs) HR HK 10%nat [VDEL_2] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1. }
    rreg HR' 1%bv G1. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 10%bv G10. rreg HR' 18%bv G18. rreg HR' 19%bv G19.
    rewrite w_add in G10 by lia. rewrite w_add in G18 by lia. rewrite w_add in G19 by lia.
    assert (HF0 : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF0) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rewrite ?G1, ?G8, ?G9, ?G10, ?G18, ?G19 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | rewrite HR0; apply rfull_mkR | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.
    assert (VIS1' : as_VIS H s msF1 = MS (mkR (Z_to_bv 64 AST_V2R) (Z_to_bv 64 spf) gp tp x5 x6 x7
        (Z_to_bv 64 st1) (Z_to_bv 64 st2) (Z_to_bv 64 (st1 + 192)) x11 x12 x13 x14 x15 x16 x17
        (Z_to_bv 64 (st2 + 192)) (Z_to_bv 64 (st1 + 192)) x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
        F (Z_to_bv 64 VDEL_2) fc None m (seg_rom asegs)).
    { rewrite VIS1, HRe. reflexivity. }
    clear VIS1.

    pose proof (proj1 (proj2 (vdel_ok H HH HAN))) as VD. unfold vdel_stmt_at in VD.
    eapply (ah_seq H HH).
    { eapply VD with (pid := pid) (v := st1 + 192) (b1 := b1) (e1 := e1) (c1 := q1) (LB := LBc) (LF := LF)
        (lo := lo) (B := B) (shi := shi) (errv := errv).
      1: exact VIS1'.
      all: rewrite ?Uspf.
      - reflexivity.
      - exact CW1.
      - exact HDR.
      - lia.
      - exact BZ.
      - intros K. split; [exact (INpid K)|]. split; [exact (vord_of_vraw _ _ _ _ _ _ V1)|].
        split; [exact (VB1 _ _ (IN1 K))|]. split; [exact (SV1 K)|]. split; [exact (VSt1 K)|].
        pose proof (BAP b1 (q1 - b1) ltac:(apply in_or_app; left; exact (IN1 K))) as [K1 _]. lia.
      - exact OWN.
      - exact RH.
      - exact KR1.
      - rewrite HCF. lia.
      - exact RA.
      - unfold spf; lia.
      - exact SPF16.
      - exact STKf.
      - lia.
      - unfold VDEL_STACK. lia.
      - exact ERR.
      - exact MI.
      - exact TPV.
      - exact AC.
      - exact RFS.
      - exact S0.
      - unfold spf; lia.
      - intros _. apply tr_of. unfold ST_MVA_DEL_RAS, VDEL_RA_2. repeat (first [left; reflexivity | right]). }
    intros cf POST. destruct cf as [msF2 mo2].
    destruct POST as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m1 & sq
      & VIS2 & KR2 & MP2 & MI2 & STK2 & ERR2 & RA2 & XP2 & RH2 & OWN2 & CZ2 & SZ2 & RFS2 & AC2 & S02 & AL2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite (ret_pc_even AST_V2R ltac:(unfold AST_V2R; lia) eq_refl) in VIS2.
    rewrite Uspf in STK2, XP2.
    rewrite HCF in AL2.
    set (LBq := vdel_LB H LBc pid b1) in *.

    assert (NDc : List.NoDup (map blk_id LBc)) by exact (ah_nodup H HH _ _ _ RH).
    assert (PL5 : Permutation LBq (LB0 ++ L5)).
    { unfold LBq, vdel_LB. destruct CA5 as [(K & EA) | (K & EA)].
      - rewrite (proj2 (Z.eqb_eq b1 0) K). eapply Permutation_trans; [exact PRM|]. unfold L4, L5. rewrite EA. perm_solve.
      - rewrite (proj2 (Z.eqb_neq b1 0) K).
        eapply Permutation_trans.
        + apply (lb_remove_perm_app H HH LBc (LB0 ++ B1 ++ B2 ++ B3 ++ B4) (A6 ++ B5 ++ B6) pid b1 (q1 - b1) NDc).
          eapply Permutation_trans; [exact PRM|]. unfold L4. rewrite EA. rewrite <- !app_assoc. apply Permutation_refl.
        + unfold L5. perm_solve. }
    assert (INq : forall b, In b (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ A6 ++ B6) -> In b LBq).
    { intros b Hb. eapply Permutation_in; [apply Permutation_sym; exact PL5|]. apply in_or_app; right. exact Hb. }
    assert (SUB0 : forall b, In b LB0 -> In b LBq).
    { intros b Hb. eapply Permutation_in; [apply Permutation_sym; exact PL5|]. apply in_or_app; left. exact Hb. }

    assert (XPv : xpres H LBq spf [(st1 + 192, st1 + 192 + 24)] m m1)
      by exact (sv_vdel_xp s LBc m pid b1 q1 (st1 + 192) m m1 RH INpid XP2).
    assert (CWm1 : rw_cells asegs m1 (st2 + 192) [C8 (wz b2); C8 (wz e2); C8 (wz q2)]).
    { eapply xpres_rw_cells; [exact XPv | exact CW2 |].
      match goal with |- xclient_range _ _ _ _ _ (Z.of_nat ?n) => let v := eval vm_compute in (Z.of_nat n) in change (Z.of_nat n) with v end.
      split; [destruct FS2 as [K|K]; [right; right; right; right; left; lia | left; unfold spf; lia] |].
      apply Forall_cons; [cbn [fst snd]; lia | apply Forall_nil]. }
    assert (AD2m1 : addressable m1 st2 240).
    { eapply addressable_xp; [exact XPv | exact AD2 |]. apply sv2_shc; [lia | lia | | lia | lia].
      destruct FS2 as [K|K]; [left; exact K | right; lia]. }
    assert (ADZ : addressable m1 (st1 + 192) 24) by (split; [lia | exact SZ2]).
    pose proof (sv_gz m1 (st1 + 192) 24 0 24 ADZ ltac:(lia) ltac:(vm_compute; intro X; discriminate X)) as GZ1. rewrite Z.add_0_r in GZ1.
    pose proof (sv_gz m1 st2 240 192 24 AD2m1 ltac:(lia) ltac:(vm_compute; intro X; discriminate X)) as GZ2.
    assert (WA1 : wr_at asegs m1 (st1 + 192) 24) by exact (own_of_rw_cells m1 (st1 + 192) 24 _ (sv2_cb3 _ _ _ _ _ CZ2) ltac:(lia)).

    eapply (ahh_evt_then H HH); [exact KR2 | exact VIS2 | |].
    { eapply (vcp2 m1) with (b := b2) (e := e2) (c := q2); [exact CWm1 | exact WA1 | exact GZ1 | exact GZ2 | exact MI2 | lia | lia | lia]. }
    intros msF3 mo3 KR3 MP3 PV. cbv beta in PV.
    destruct PV as (M2 & VIS3 & MU3 & WM3 & MI3 & CW3).

    assert (WO1 : aclient_write_ok H LBq (st1 + 192, st1 + 192 + 24)) by (right; right; right; right; left; cbn [fst snd]; lia).
    assert (FO1 : afs_write_ok H LF (st1 + 192, st1 + 192 + 24)).
    { right. pose proof F1 as (f & Hf & Hf1 & Hf2). exists f. unfold ST_SIZE in Hf2. cbn [fst snd]. split; [exact Hf | lia]. }
    assert (CO1 : aconst_ok (st1 + 192, st1 + 192 + 24)) by (eapply aconst_ok_app; [exact FB4 | lia | lia]).
    destruct (client_frame H HH sq LBq LF B _ m1 M2 RH2 RFS2 AC2 RA2 MU3 WM3
               (Forall_cons _ _ _ WO1 (Forall_nil _)) (Forall_cons _ _ _ FO1 (Forall_nil _)) (Forall_cons _ _ _ CO1 (Forall_nil _)))
      as (RHM2 & RFSM2 & ACM2 & RAM2).
    assert (S0M2 : stack0 M2 lo shi).
    { eapply stack0_transport; [exact S02 | exact MU3 | exact WM3 |].
      apply Forall_cons; [eapply stack0_ok_aapp; [exact FB4 | cbn [fst]; lia | cbn [snd]; lia] | apply Forall_nil]. }
    assert (ERRM2 : rw_cells asegs M2 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERR2 | exact MU3 | exact WM3 | cbn [disjoint_from cells_size csize]; split; [lia | exact I]]. }
    assert (STKM2 : stk asegs M2 lo spf).
    { eapply stk_transport; [exact STK2 | exact MU3 | exact WM3 |]. intros x Hx. left. cbn [outside]. split; [lia | exact I]. }
    assert (CWM2 : rw_cells asegs M2 (st2 + 192) [C8 (wz b2); C8 (wz e2); C8 (wz q2)]).
    { eapply rw_cells_transport; [exact CWm1 | exact MU3 | exact WM3 | cbn [disjoint_from cells_size csize]; split; [lia | exact I]]. }
    assert (AD2M2 : addressable M2 st2 240).
    { eapply addressable_transport; [exact AD2m1 | exact MU3 | exact WM3 |]. apply sv2_djsh; [lia | lia | lia]. }
    assert (ACC2 : accessible M2 (st2 + 192) 24) by (eapply (addressable_accessible M2 st2 240); [exact AD2M2 | lia | lia | unfold AAPP_HI; lia]).
    assert (SVM2 : shvis M2 (st2 + 192) (st2 + 192 + 24)).
    { pose proof F2 as [(f & Hf & Hf1 & Hf2) | (K1 & K2)]; unfold ST_SIZE in *.
      - pose proof (ah_frm_shvis H HH LF M2 f RFSM2 Hf) as SV.
        pose proof (ah_RFS_range H HH _ _ RFSM2) as [_ FRr]. pose proof (FRr f Hf) as (_ & Ff & _). unfold AFS_HDR in Ff.
        eapply shvis_sub; [exact SV | lia | lia | lia | lia | lia].
      - eapply (stack0_shvis M2 lo shi); [exact S0M2 | lia | lia | lia]. }
    assert (IA2 : in_app_mem (st2 + 192) (st2 + 192 + 24)).
    { destruct FS2 as [K|K]; [eapply aapp_in_app_mem; [exact FB4 | lia | lia] | eapply (stack0_in_app_mem M2 lo shi); [exact S0M2 | lia | unfold ST_SIZE in K; lia]]. }
    assert (CO2 : aconst_ok (st2 + 192, st2 + 192 + 24)).
    { destruct FS2 as [K|K]; [eapply aconst_ok_app; [exact FB4 | lia | lia] | assert (ACK : aceil <= st2 + 192) by lia; exact (proj2 (proj2 (stack_window_ok H LBq LF (st2 + 192) (st2 + 192 + 24) ACK FB2)))]. }

    eapply (ahh_evt_then H HH); [exact KR3 | exact VIS3 | |].
    { eapply (ah_memset H HH) with (c := 0) (junk := cells_bytes [C8 (wz b2); C8 (wz e2); C8 (wz q2)]) (lo := lo).
      all: rewrite ?U2v, ?U24, ?Uspf.
      - reflexivity.
      - lia.
      - exact (sv2_cb3 _ _ _ _ _ CWM2).
      - exact ACC2.
      - exact SVM2.
      - exact STKM2.
      - lia.
      - unfold spf, AINTRIN_STACK, AST_MVA_STACK, AFREE_STACK in *; lia.
      - exact MI3.
      - exact ACM2.
      - lia.
      - exact IA2.
      - exact CO2.
      - destruct FS2 as [K|K]; [left; lia | right; unfold spf; lia]. }
    intros msF4 mo4 KR4 MP4 PM.
    destruct PM as (t0'' & t1'' & t2'' & a1'' & a2'' & a3'' & a4'' & a5'' & a6'' & a7'' & t3'' & t4'' & t5'' & t6'' & m3
      & VIS4 & MU4 & WM4 & MI4 & STK4 & CB4 & AC4).
    rewrite ?U2v, ?U24, ?Uspf in MU4. rewrite ?Uspf in STK4. rewrite ?U2v, ?U24 in CB4.
    rewrite (ret_pc_even AST_V3 ltac:(unfold AST_V3; lia) eq_refl) in VIS4.
    assert (WO2 : Forall (aclient_write_ok H LBq) [(st2 + 192, st2 + 192 + 24); (spf - AINTRIN_STACK, spf)]).
    { apply Forall_cons; [| apply Forall_cons; [exact (proj1 (stack_window_ok H LBq LF _ spf SWb FB2)) | apply Forall_nil]].
      destruct FS2 as [K|K]; [right; right; right; right; left; cbn [fst snd]; lia | left; cbn [fst]; lia]. }
    assert (FO2 : Forall (afs_write_ok H LF) [(st2 + 192, st2 + 192 + 24); (spf - AINTRIN_STACK, spf)]).
    { apply Forall_cons; [| apply Forall_cons; [exact (proj1 (proj2 (stack_window_ok H LBq LF _ spf SWb FB2))) | apply Forall_nil]].
      destruct F2 as [(f & Hf & Hf1 & Hf2) | (K1 & K2)].
      - right. exists f. unfold ST_SIZE in Hf2. cbn [fst snd]. split; [exact Hf | lia].
      - assert (ACK : aceil <= st2 + 192) by lia.
        exact (proj1 (proj2 (stack_window_ok H LBq LF (st2 + 192) (st2 + 192 + 24) ACK FB2))). }
    assert (CO2' : Forall aconst_ok [(st2 + 192, st2 + 192 + 24); (spf - AINTRIN_STACK, spf)]).
    { apply Forall_cons; [exact CO2 | apply Forall_cons; [exact (proj2 (proj2 (stack_window_ok H LBq LF _ spf SWb FB2))) | apply Forall_nil]]. }
    destruct (client_frame H HH sq LBq LF B _ M2 m3 RHM2 RFSM2 ACM2 RAM2 MU4 WM4 WO2 FO2 CO2')
      as (RHm3 & RFSm3 & ACm3 & RAm3).
    assert (S0m3 : stack0 m3 lo shi).
    { eapply stack0_transport; [exact S0M2 | exact MU4 | exact WM4 |].
      apply Forall_cons; [| apply Forall_cons; [apply stack0_ok_app; unfold AHI_LO, spf, AINTRIN_STACK; lia | apply Forall_nil]].
      destruct FS2 as [K|K]; [eapply stack0_ok_aapp; [exact FB4 | cbn [fst]; lia | cbn [snd]; lia] | apply stack0_ok_app; cbn [fst]; unfold AHI_LO; lia]. }
    assert (ERRm3 : rw_cells asegs m3 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERRM2 | exact MU4 | exact WM4 |].
      cbn [disjoint_from cells_size csize]. split; [lia | split; [unfold spf, AINTRIN_STACK, AIMG_TOP in *; lia | exact I]]. }
    assert (OWNm3 : lb_own LBq m3) by exact (lb_own_wmono _ _ _ (lb_own_wmono _ _ _ OWN2 WM3) WM4).
    assert (CWm3 : rw_cells asegs m3 (st1 + 192) [C8 (wz b2); C8 (wz e2); C8 (wz q2)]).
    { eapply rw_cells_transport; [exact CW3 | exact MU4 | exact WM4 |].
      cbn [disjoint_from cells_size csize]. split; [lia | split; [lia | exact I]]. }
    pose proof (sv2_zero3 m3 (st2 + 192) CB4) as Z0.

    assert (XPa : xpres H LBq spf (XW 192 24) m m1).
    { eapply (xpres_weaken H); [exact XPv | lia | intros b Hb; exact Hb |]. intros a Ha. unfold XW. cbn [rin_ivs fst snd] in *. lia. }
    assert (XPb : xpres H LBq spf (XW 192 24) m1 M2).
    { eapply (xpres_of_munch H sq LBq spf (XW 192 24) _ m1 m1 M2 HH RH2 MU3 WM3).
      apply Forall_cons; [right; intros a Ha; cbn [fst snd] in Ha; unfold XW; cbn [rin_ivs fst snd]; left; lia | apply Forall_nil]. }
    assert (XPc : xpres H LBq spf (XW 192 24) M2 m3).
    { eapply (xpres_of_munch H sq LBq spf (XW 192 24) _ m1 M2 m3 HH RH2 MU4 WM4).
      apply Forall_cons; [right; intros a Ha; cbn [fst snd] in Ha; unfold XW; cbn [rin_ivs fst snd]; right; left; lia|].
      apply Forall_cons; [left; cbn [fst snd]; split; [exact SWb | lia] | apply Forall_nil]. }
    assert (XP : xpres H LBq spf (XW 192 24) m m3).
    { eapply (xpres_trans H); [eapply (xpres_trans H); [exact XPa | exact XPb] | exact XPc]. }

    assert (INB1 : forall b, In b (B1 ++ B2 ++ B3 ++ B4 ++ A6) -> In b LBq /\ In b LBq).
    { intros b Hb. assert (K : In b LBq) by (apply INq; inapp_solve). split; exact K. }
    assert (INA1 : forall b, In b (B1 ++ B2 ++ B3 ++ B4 ++ A6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (INB5 : forall b, In b B5 -> In b LBq /\ In b LBq).
    { intros b Hb. assert (K : In b LBq) by (apply INq; inapp_solve). split; exact K. }
    assert (INB6 : forall b, In b B6 -> In b LBq /\ In b LBq).
    { intros b Hb. assert (K : In b LBq) by (apply INq; inapp_solve). split; exact K. }
    assert (INA6 : forall b, In b B6 -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (EL1 : lbl (B1 ++ B2 ++ B3 ++ B4 ++ A6) = cb_m1 cA4 ++ cb_m2 cA4 ++ cb_m3 cA4 ++ cb_v1 cA4 ++ cb_v3 cA4)
      by (rewrite !lbl_app, LB1, LB2, LB3, LB4, LA6; reflexivity).
    assert (EL2 : lbl B6 = cb_m1 cB4 ++ cb_m2 cB4 ++ cb_m3 cB4 ++ cb_v1 cB4 ++ cb_v3 cB4).
    { change (cb_m1 cB4) with (@nil (Z * Z)). change (cb_m2 cB4) with (@nil (Z * Z)).
      change (cb_m3 cB4) with (@nil (Z * Z)). change (cb_v1 cB4) with (@nil (Z * Z)). rewrite !app_nil_l, LB6. reflexivity. }
    assert (V2m3 : vraw MI_A (lbl LBq) m3 (st1 + 192) b2 e2 q2).
    { eapply sv2_vraw_re; [exact (sv_vraw_move _ _ _ _ _ _ _ _ V2 CWm3 ltac:(lia)) |].
      intros K. destruct CB5 as [(K1 & _) | (_ & pid2 & EB)]; [contradiction|].
      assert (Hb : In (pid2, b2, q2 - b2) B5) by (rewrite EB; left; reflexivity).
      apply (lbl_in LBq pid2). apply INq. inapp_solve. }

    assert (R1N : state_repA LBq m3 st1 cA5).
    { unfold cA5. eapply (rep_upd_v2 H LBc LBq LBq spf (XW 192 24) m m3 st1 cA4 (st_v2 c2));
        [exact R1 | exact XP | exact (objx_st1 LBq 192 24 ltac:(lia) ltac:(lia)) | | exact V2m3 | | exact ST1L | exact ST1H | exact VSt2].
      - rewrite <- EL1. apply blkx_stage; [exact INB1 | exact INA1 | lia | lia].
      - eapply (nodup_fst_of_perm' H HH sq LBq m3 (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ A6) (LB0 ++ B6)); [exact RHm3 | |].
        + eapply Permutation_trans; [exact PL5|]. unfold L5. perm_solve.
        + rewrite state_blocks_cb, !lbl_app, LB1, LB2, LB3, LB4, LB5, LA6. apply Permutation_refl. }
    assert (SH1N : state_sh m3 cA5).
    { unfold cA5. eapply (sh_upd_v2 H LBc LBq spf (XW 192 24) m m3 st1 cA4 (st_v2 c2)); [exact R1 | exact SH1 | exact XP | |].
      - rewrite <- EL1. eapply blksh_stage; [exact RHm3 | exact INB1 | lia | lia].
      - eapply (vec_sh_xp H LBq spf (XW 192 24) m m3 (st_v2 c2)); [exact XP | exact SV2 | exact (vord_of_vraw _ _ _ _ _ _ V2) |].
        change (vec_blocks (st_v2 c2)) with (cb_v2 c2). rewrite <- LB5. eapply blksh_stage; [exact RHm3 | exact INB5 | lia | lia]. }
    assert (R2N : state_repA LBq m3 st2 cB5).
    { unfold cB5. eapply (rep_upd_v2 H LBc LBq LBq spf (XW 192 24) m m3 st2 cB4 V0);
        [exact R2 | exact XP | exact (objx_st2 LBq 192 24 ltac:(lia) ltac:(lia)) | | exact (sv_vraw0 _ _ _ Z0 ltac:(lia)) | | exact ST2L | exact ST2H
        | intros K; exfalso; apply K; reflexivity].
      - rewrite <- EL2. apply blkx_stage; [exact INB6 | exact INA6 | lia | lia].
      - eapply (nodup_fst_of_perm' H HH sq LBq m3 B6 (LB0 ++ B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ A6)); [exact RHm3 | |].
        + eapply Permutation_trans; [exact PL5|]. unfold L5. perm_solve.
        + rewrite state_blocks_cb, LB6.
          change (cb_m1 (set_v2 cB4 V0)) with (@nil (Z * Z)). change (cb_m2 (set_v2 cB4 V0)) with (@nil (Z * Z)).
          change (cb_m3 (set_v2 cB4 V0)) with (@nil (Z * Z)). change (cb_v1 (set_v2 cB4 V0)) with (@nil (Z * Z)).
          change (cb_v2 (set_v2 cB4 V0)) with (@nil (Z * Z)). rewrite !app_nil_l. apply Permutation_refl. }
    assert (SH2N : state_sh m3 cB5).
    { unfold cB5. eapply (sh_upd_v2 H LBc LBq spf (XW 192 24) m m3 st2 cB4 V0); [exact R2 | exact SH2 | exact XP | |].
      - rewrite <- EL2. eapply blksh_stage; [exact RHm3 | exact INB6 | lia | lia].
      - intros K. exfalso. apply K. reflexivity. }
    assert (ALq : as_AL H sq >= as_AL H s) by lia.
    eapply (stage_v3 sq LBq m3 msF4 mo4); [exact VIS4 | exact KR4 | |].
    - eapply (ah_mpres_trans H HH); [exact MP|]. eapply (ah_mpres_trans H HH); [exact MP1|].
      eapply (ah_mpres_trans H HH); [exact MP2|]. eapply (ah_mpres_trans H HH); [exact MP3 | exact MP4].
    - exact (INV_step s LBc m cA4 cB4 L4 sq LBq m3 LBq 192 24 cA5 cB5 L5 IV0 XP ltac:(lia) ltac:(lia) ltac:(lia) SUB0
               MI4 STK4 ERRm3 RAm3 ACm3 RFSm3 S0m3 RHm3 OWNm3 ALq R1N SH1N R2N SH2N PL5).
  Qed.

  Lemma stage_v1 : forall s LBc m msF mo
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word) (F : bvmap 5 word),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 AST_V1) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    INV s LBc m cA3 cB3 L3 ->
    as_SR H QF (mkCfg msF mo).
Proof.
    intros s LBc m msF mo x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 F
      VIS KR MP IV.
    pose proof IV as IV0.
    destruct IV as (MI & STK & ERR & RA & AC & RFS & S0 & RH & OWN & FR & R1 & SH1 & R2 & SH2 & AD1 & AD2 & PRM & XP0 & ALs).
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    pose proof FSBOK as (FB1 & FB2 & FB3 & FB4).
    pose proof (obj_facts 168 ltac:(lia) ltac:(lia) eq_refl) as (O1R & O2R & OAP & OFS1 & OFS2 & AFW1 & AFW2 & ACO1 & ACO2 & OSV2).
    pose proof O2R as (O2a & O2b & O2c & O2d & O2e).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (SPFd : spf = spz - 96) by reflexivity.
    assert (AIS : AINTRIN_STACK = 4096) by reflexivity.
    assert (VDS : VDEL_STACK = 8256) by reflexivity.
    assert (LOH2 : aceil <= lo /\ lo <= spz - 8448) by (unfold AST_MVA_STACK, AFREE_STACK in LOH; lia).
    assert (SPF16 : spf mod 16 = 0) by (unfold spf; rewrite Zminus_mod, SP16; reflexivity).
    assert (Uspf : bv_unsigned (Z_to_bv 64 spf) = spf) by (apply u64_of_Z; lia).
    assert (U2v : bv_unsigned (Z_to_bv 64 (st2 + 168)) = st2 + 168) by (apply u64_of_Z; lia).
    assert (U24 : bv_unsigned (Z_to_bv 64 24) = 24) by (apply u64_of_Z; lia).
    assert (EAB : 0 <= errno_addr tp /\ errno_addr tp + 4 <= AIMG_TOP).
    { rewrite TPV. split; apply Z.leb_le; vm_compute; reflexivity. }

    destruct (st_v1 c1) as [[b1 e1] q1] eqn:EV1.
    destruct (st_v1 c2) as [[b2 e2] q2] eqn:EV2.
    assert (V1A : vraw MI_A (lbl LBc) m (st1 + 168) b1 e1 q1).
    { pose proof (sr_v1 _ _ _ _ _ _ _ (proj1 R1)) as K. change (st_v1 cA3) with (st_v1 c1) in K. rewrite EV1 in K. exact K. }
    assert (V1B : vraw MI_A (lbl LBc) m (st2 + 168) b2 e2 q2).
    { pose proof (sr_v1 _ _ _ _ _ _ _ (proj1 R2)) as K. change (st_v1 cB3) with (st_v1 c2) in K. rewrite EV2 in K. exact K. }
    pose proof (vord_of_vraw _ _ _ _ _ _ V1A) as ORD1.
    pose proof (vord_of_vraw _ _ _ _ _ _ V1B) as ORD2.
    pose proof (sv_vraw_rng _ _ _ _ _ _ V1B) as (RB2 & RE2 & RC2).
    assert (Z1 : b1 = 0 -> e1 = 0 /\ q1 = 0).
    { intros K. pose proof V1A as [_ _ _ VK]. destruct VK as [(K1 & K2 & K3) | (K1 & _)]; [lia | lia]. }
    pose proof (vec_blk_cases A4 (st_v1 c1) LA4) as VC. rewrite EV1 in VC. unfold t3a, t3b, t3c in VC. cbn [fst snd] in VC.
    assert (PID : exists pid : bptr, (b1 <> 0 -> A4 = [(pid, b1, q1 - b1)]) /\ (b1 = 0 -> A4 = [])).
    { destruct VC as [(K1 & K2) | (K1 & pid & K2)].
      - exists 0. split; intros K; [lia | exact K2].
      - exists pid. split; intros K; [exact K2 | lia]. }
    destruct PID as (pid & PA1 & PA0).
    assert (INC : forall b, In b (LB0 ++ L3) -> In b LBc).
    { intros b Hb. eapply Permutation_in; [apply Permutation_sym; exact PRM | exact Hb]. }
    assert (IPA : b1 <> 0 -> In (pid, b1, q1 - b1) LBc).
    { intros NZ. apply INC. apply in_or_app; right. unfold L3. rewrite (PA1 NZ). rewrite !in_app_iff.
      right; right; right; left; left; reflexivity. }
    assert (ND : List.NoDup (map blk_id LBc)) by exact (ah_nodup H HH _ _ _ RH).
    set (LBq := vdel_LB H LBc pid b1).
    assert (PRMq : Permutation LBq (LB0 ++ L4)).
    { unfold LBq, vdel_LB. destruct (Z.eqb_spec b1 0) as [K|K].
      - eapply Permutation_trans; [exact PRM|]. unfold L3, L4. rewrite (PA0 K). perm_solve.
      - apply (lb_remove_perm_app H HH LBc LB0 _ pid b1 (q1 - b1) ND).
        eapply Permutation_trans; [exact PRM|]. unfold L3, L4. rewrite (PA1 K). perm_solve. }
    assert (INq : forall b, In b (LB0 ++ L4) -> In b LBq).
    { intros b Hb. eapply Permutation_in; [apply Permutation_sym; exact PRMq | exact Hb]. }

    lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
    pose (E := Eseed R [Z_to_bv 64 st1; Z_to_bv 64 st2]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EVar 32); (9%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (HK : know_ok asegs E m []) by (apply Forall_nil).
    xrun_at (PropExec.mkFP F fc) asegs R AST_V1 m (seg_rom asegs) HR HK 10%nat [VDEL_1] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1. }
    rreg HR' 1%bv G1. rreg HR' 10%bv G10. rreg HR' 18%bv G18. rreg HR' 19%bv G19. rreg HR' 8%bv G8. rreg HR' 9%bv G9.
    rewrite w_add in G10, G18, G19 by lia.
    assert (HF0 : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF0) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rewrite ?G1, ?G8, ?G9, ?G10, ?G18, ?G19 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact HF0 | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.
    assert (VIS1' : as_VIS H s msF1 = MS (mkR (Z_to_bv 64 AST_V1R) (Z_to_bv 64 spf) gp tp x5 x6 x7
        (Z_to_bv 64 st1) (Z_to_bv 64 st2) (Z_to_bv 64 (st1 + 168)) x11 x12 x13 x14 x15 x16 x17
        (Z_to_bv 64 (st2 + 168)) (Z_to_bv 64 (st1 + 168)) x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
        F (Z_to_bv 64 VDEL_1) fc None m (seg_rom asegs)).
    { rewrite VIS1, HRe. reflexivity. }
    clear VIS1.

    pose proof (proj1 (vdel_ok H HH HAN)) as VD1. unfold vdel_stmt_at in VD1.
    eapply (ah_seq H HH).
    { eapply (VD1 (Z_to_bv 64 AST_V1R) (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2)
        (Z_to_bv 64 (st1 + 168)) x11 x12 x13 x14 x15 x16 x17 (Z_to_bv 64 (st2 + 168)) (Z_to_bv 64 (st1 + 168)) x20 x21
        (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31 F fc msF1 m mo1 s LBc LF pid (st1 + 168) b1 e1 q1 lo B shi errv);
        rewrite ?Uspf.
      - exact VIS1'.
      - reflexivity.
      - exact (sv_cells_of_vraw _ _ _ _ _ _ V1A ltac:(lia) ltac:(lia)).
      - unfold vdel_hdr_ok. split; [Z.div_mod_to_equations; lia|]. split.
        + exact (proj2 (addressable_sub8 m st1 240 168 24 AD1 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia))).
        + destruct FST1 as (f & Hf & Hf1 & Hf2). exists f. split; [exact Hf | lia].
      - lia.
      - exact Z1.
      - intros NZ. pose proof V1A as [_ _ _ VK].
        destruct VK as [(K1 & _) | (_ & _ & K3)]; [lia|].
        assert (IB1 : In (b1, q1 - b1) (state_blocks c1)).
        { rewrite state_blocks_cb. apply in_app_iff; right. apply in_app_iff; right. apply in_app_iff; right.
          apply in_app_iff; left. rewrite <- LA4, (PA1 NZ). left; reflexivity. }
        split; [exact (IPA NZ)|]. split; [exact ORD1|]. split; [exact (VB1 _ _ IB1)|].
        split.
        { pose proof SH1 as (_ & _ & _ & VS1 & _ & _). change (st_v1 cA3) with (st_v1 c1) in VS1. rewrite EV1 in VS1.
          unfold vec_sh, t3a, t3b, t3c in VS1. cbn [fst snd] in VS1. exact (VS1 NZ). }
        split.
        { pose proof (proj2 R1) as (VS & _ & _). change (st_v1 cA3) with (st_v1 c1) in VS. rewrite EV1 in VS.
          unfold t3a, t3b, t3c in VS. cbn [fst snd] in VS. exact (VS NZ). }
        pose proof (BAP b1 (q1 - b1) ltac:(apply in_or_app; left; exact IB1)) as [D1 _]. lia.
      - exact OWN.
      - exact RH.
      - exact KR1.
      - rewrite HCF. lia.
      - exact RA.
      - lia.
      - exact SPF16.
      - exact (proj1 (stk_split asegs m lo spf spz STK ltac:(lia))).
      - lia.
      - lia.
      - exact ERR.
      - exact MI.
      - exact TPV.
      - exact AC.
      - exact RFS.
      - exact S0.
      - lia.
      - intros _. apply tr_of. unfold ST_MVA_DEL_RAS. repeat (first [left; reflexivity | right]). }
    intros [msF2 mo2] POST.
    destruct POST as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m1 & sq
      & VIS2 & KR2 & MP2 & MI1 & STK1 & ERR1 & RA1 & XP1 & RH1 & OWN1 & CW1 & SHD1 & RFS1 & AC1 & S01 & AL1).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite (ret_pc_even AST_V1R ltac:(unfold AST_V1R; lia) eq_refl) in VIS2.
    rewrite Uspf in STK1, XP1.
    change (vdel_LB H LBc pid b1) with LBq in XP1, RH1, OWN1.

    assert (XPv : xpres H LBq spf [(st1 + 168, st1 + 168 + 24)] m m1).
    { exact (sv_vdel_xp s LBc m pid b1 q1 (st1 + 168) m m1 RH IPA XP1). }
    assert (XR1 : forall a, rin_ivs [(st1 + 168, st1 + 168 + 24)] a -> (st1 <= a < st1 + 240) \/ (st2 <= a < st2 + 240)).
    { intros a Ha. cbn [rin_ivs fst snd] in Ha. lia. }
    assert (XRW : forall a, rin_ivs (XW 168 24) a -> (st1 <= a < st1 + 240) \/ (st2 <= a < st2 + 240)).
    { intros a Ha. unfold XW in Ha. cbn [rin_ivs fst snd] in Ha. lia. }
    assert (FSC2 : (as_FSB H <= st2 /\ st2 + 240 <= as_FSB H + AFS_SIZE) \/ aceil <= st2).
    { destruct FS2 as [K|K]; [left; exact K | right; lia]. }
    assert (AD1a : addressable m1 st1 240).
    { eapply (addressable_xp H LBq spf _ m m1 st1 240 XPv AD1). apply sv1_shc; [lia | lia | left; lia | exact XR1]. }
    assert (AD2a : addressable m1 st2 240).
    { eapply (addressable_xp H LBq spf _ m m1 st2 240 XPv AD2). apply sv1_shc; [lia | lia | exact FSC2 | exact XR1]. }
    assert (OB2 : OBJX H LBq spf [(st1 + 168, st1 + 168 + 24)] st2 0 0).
    { apply objx_intro; [destruct FS2 as [K|K]; [left; exact K | right; lia] |].
      intros a Ha _ K. cbn [rin_ivs fst snd] in K. lia. }
    assert (V1Bq : vraw MI_A (lbl LBq) m1 (st2 + 168) b2 e2 q2).
    { eapply (vraw_xp H LBq spf _ LBc LBq m m1 (st2 + 168) b2 e2 q2 XPv V1B); [| lia | lia |].
      - intros i Hi. apply OB2; lia.
      - rewrite <- EV2. change (vec_blocks (st_v1 c2)) with (cb_v1 c2). rewrite <- LB4.
        apply sv1_blkx; [| intros b Hb; unfold ALLB; inapp_solve | exact XR1].
        intros b Hb. assert (K : In b LBq) by (apply INq; apply in_or_app; right; unfold L4; inapp_solve). split; exact K. }
    assert (CWB1 : rw_cells asegs m1 (st2 + 168) [C8 (wz b2); C8 (wz e2); C8 (wz q2)])
      by exact (sv_cells_of_vraw _ _ _ _ _ _ V1Bq ltac:(lia) ltac:(lia)).
    assert (WRA1 : wr_at asegs m1 (st1 + 168) 24) by exact (proj2 CW1).
    assert (GZA : gz m1 (st1 + 168) 24) by (apply (sv_gz m1 st1 240 168 24 AD1a); [lia | Z.div_mod_to_equations; lia]).
    assert (GZB : gz m1 (st2 + 168) 24) by (apply (sv_gz m1 st2 240 168 24 AD2a); [lia | Z.div_mod_to_equations; lia]).

    eapply (ahh_evt_then H HH); [exact KR2 | exact VIS2 | |].
    { eapply vcp1; [exact CWB1 | exact WRA1 | exact GZA | exact GZB | exact MI1 | lia | lia | lia]. }
    intros msF3 mo3 KR3 MP3 P3. destruct P3 as (M2 & VIS3 & MU2 & WM2 & MI2 & CW2).
    assert (AW1 : aclient_write_ok H LBq (st1 + 168, st1 + 168 + 24)) by (right; right; right; right; left; cbn [fst snd]; lia).
    assert (FW1 : afs_write_ok H LF (st1 + 168, st1 + 168 + 24)) by (eapply sv1_afs_sub; [exact AFW1 | lia | lia]).
    assert (CO1 : aconst_ok (st1 + 168, st1 + 168 + 24)) by (eapply sv1_aco_sub; [exact ACO1 | lia | lia]).
    destruct (client_frame H HH sq LBq LF B _ m1 M2 RH1 RFS1 AC1 RA1 MU2 WM2
               (Forall_cons _ _ _ AW1 (Forall_nil _)) (Forall_cons _ _ _ FW1 (Forall_nil _)) (Forall_cons _ _ _ CO1 (Forall_nil _)))
      as (RH2 & RFS2 & AC2 & RA2).
    assert (S02 : stack0 M2 lo shi).
    { eapply stack0_transport; [exact S01 | exact MU2 | exact WM2 |].
      apply Forall_cons; [eapply stack0_ok_aapp; [exact FB4 | cbn [fst]; lia | cbn [snd]; lia] | apply Forall_nil]. }
    assert (ERR2 : rw_cells asegs M2 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERR1 | exact MU2 | exact WM2 | cbn [disjoint_from cells_size csize Z.of_nat]; lia]. }
    assert (OWN2 : lb_own LBq M2) by exact (lb_own_wmono _ _ _ OWN1 WM2).
    assert (STK2 : stk asegs M2 lo spf).
    { eapply stk_transport_disjoint; [exact STK1 | exact MU2 | exact WM2 | cbn [disjoint_from]; split; [lia | exact I]]. }
    assert (XPa : xpres H LBq spf (XW 168 24) m m1).
    { eapply (xpres_weaken H); [exact XPv | lia | intros b Hb; exact Hb |]. intros a Ha. unfold XW. cbn [rin_ivs fst snd] in *. lia. }
    assert (XPb : xpres H LBq spf (XW 168 24) m1 M2).
    { eapply (xpres_of_munch H sq LBq spf (XW 168 24) _ m1 m1 M2 HH RH1 MU2 WM2).
      apply Forall_cons; [right; intros a Ha; cbn [fst snd] in Ha; unfold XW; cbn [rin_ivs fst snd]; left; lia | apply Forall_nil]. }
    assert (AD2b : addressable M2 st2 240).
    { eapply (addressable_xp H LBq spf (XW 168 24) m M2 st2 240); [eapply (xpres_trans H); [exact XPa | exact XPb] | exact AD2 |].
      apply sv1_shc; [lia | lia | exact FSC2 | exact XRW]. }
    assert (ACC2 : accessible M2 (st2 + 168) 24).
    { eapply (addressable_accessible M2 st2 240); [exact AD2b | lia | lia | unfold AAPP_HI; lia]. }
    assert (SV2 : shvis M2 (st2 + 168) (st2 + 168 + 24)).
    { pose proof F2 as [(f & Hf & Hf1 & Hf2) | (K1 & K2)]; unfold ST_SIZE in *.
      - pose proof (ah_frm_shvis H HH LF M2 f RFS2 Hf) as SVf.
        pose proof (ah_RFS_range H HH _ _ RFS2) as [_ FRr]. pose proof (FRr f Hf) as (_ & Ff & _). unfold AFS_HDR in Ff.
        eapply shvis_sub; [exact SVf | lia | lia | lia | lia | lia].
      - eapply (stack0_shvis M2 lo shi); [exact S02 | lia | lia | lia]. }
    assert (CWB2 : rw_cells asegs M2 (st2 + 168) [C8 (wz b2); C8 (wz e2); C8 (wz q2)]).
    { eapply rw_cells_transport; [exact CWB1 | exact MU2 | exact WM2 | cbn [disjoint_from cells_size csize Z.of_nat]; lia]. }
    destruct (rw_cells_of_wr_hi M2 (st2 + 168) 24 (proj2 CWB2) ltac:(lia) ltac:(lia)) as (junk & CBJ).
    assert (IA2 : in_app_mem (st2 + 168) (st2 + 168 + 24)) by (eapply in_app_mem_sub; [exact O2d | lia | lia]).
    assert (CO2 : aconst_ok (st2 + 168, st2 + 168 + 24)) by (eapply sv1_aco_sub; [exact ACO2 | lia | lia]).

    eapply (ahh_evt_then H HH); [exact KR3 | exact VIS3 | |].
    { eapply (ah_memset H HH) with (c := 0) (junk := junk) (lo := lo); rewrite ?U2v, ?U24, ?Uspf.
      - reflexivity.
      - lia.
      - exact CBJ.
      - exact ACC2.
      - exact SV2.
      - exact STK2.
      - lia.
      - lia.
      - exact MI2.
      - exact AC2.
      - lia.
      - exact IA2.
      - exact CO2.
      - destruct O2e as [K|K]; [left; lia | right; lia]. }
    intros msF4 mo4 KR4 MP4 P4.
    destruct P4 as (u0 & u1 & u2 & w1 & w2 & w3 & w4 & w5 & w6 & w7 & u3 & u4 & u5 & u6 & M3 & VIS4 & MU3 & WM3 & MI3 & STK3 & CB3 & AC3).
    rewrite U2v, U24, Uspf in MU3. rewrite Uspf in STK3. rewrite U2v, U24 in CB3.
    rewrite (ret_pc_even AST_V2 ltac:(unfold AST_V2; lia) eq_refl) in VIS4.

    assert (AW2 : aclient_write_ok H LBq (st2 + 168, st2 + 168 + 24)).
    { destruct FS2 as [K|K]; [right; right; right; right; left; cbn [fst snd]; lia | left; cbn [fst]; lia]. }
    assert (FW2 : afs_write_ok H LF (st2 + 168, st2 + 168 + 24)) by (eapply sv1_afs_sub; [exact AFW2 | lia | lia]).
    assert (SWb : aceil <= spf - AINTRIN_STACK) by lia.
    destruct (stack_window_ok H LBq LF (spf - AINTRIN_STACK) spf SWb FB2) as (W3a & W3b & W3c).
    destruct (client_frame H HH sq LBq LF B _ M2 M3 RH2 RFS2 AC2 RA2 MU3 WM3
               (Forall_cons _ _ _ AW2 (Forall_cons _ _ _ W3a (Forall_nil _)))
               (Forall_cons _ _ _ FW2 (Forall_cons _ _ _ W3b (Forall_nil _)))
               (Forall_cons _ _ _ CO2 (Forall_cons _ _ _ W3c (Forall_nil _)))) as (RH3 & RFS3 & _ & RA3).
    assert (S03 : stack0 M3 lo shi).
    { eapply stack0_transport; [exact S02 | exact MU3 | exact WM3 |].
      apply Forall_cons; [| apply Forall_cons; [apply stack0_ok_app; unfold AHI_LO; lia | apply Forall_nil]].
      destruct FS2 as [K|K]; [eapply stack0_ok_aapp; [exact FB4 | cbn [fst]; lia | cbn [snd]; lia] | apply stack0_ok_app; unfold AHI_LO; lia]. }
    assert (ERR3 : rw_cells asegs M3 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERR2 | exact MU3 | exact WM3 | cbn [disjoint_from cells_size csize Z.of_nat]; lia]. }
    assert (OWN3 : lb_own LBq M3) by exact (lb_own_wmono _ _ _ OWN2 WM3).
    assert (XPc : xpres H LBq spf (XW 168 24) M2 M3).
    { eapply (xpres_of_munch H sq LBq spf (XW 168 24) _ m1 M2 M3 HH RH1 MU3 WM3).
      apply Forall_cons; [right; intros a Ha; cbn [fst snd] in Ha; unfold XW; cbn [rin_ivs fst snd]; right; left; lia|].
      apply Forall_cons; [left; cbn [fst snd]; lia | apply Forall_nil]. }
    assert (XPt : xpres H LBq spf (XW 168 24) m M3).
    { eapply (xpres_trans H); [eapply (xpres_trans H); [exact XPa | exact XPb] | exact XPc]. }

    assert (INB1 : forall b, In b (B1 ++ B2 ++ B3 ++ A5 ++ A6) -> In b LBq /\ In b LBq).
    { intros b Hb. assert (K : In b LBq) by (apply INq; apply in_or_app; right; unfold L4; inapp_solve). split; exact K. }
    assert (INA1 : forall b, In b (B1 ++ B2 ++ B3 ++ A5 ++ A6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (INB2 : forall b, In b (B5 ++ B6) -> In b LBq /\ In b LBq).
    { intros b Hb. assert (K : In b LBq) by (apply INq; apply in_or_app; right; unfold L4; inapp_solve). split; exact K. }
    assert (INA2 : forall b, In b (B5 ++ B6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (INB4 : forall b, In b B4 -> In b LBq /\ In b LBq).
    { intros b Hb. assert (K : In b LBq) by (apply INq; apply in_or_app; right; unfold L4; inapp_solve). split; exact K. }
    assert (EL1 : lbl (B1 ++ B2 ++ B3 ++ A5 ++ A6) = cb_m1 cA3 ++ cb_m2 cA3 ++ cb_m3 cA3 ++ cb_v2 cA3 ++ cb_v3 cA3)
      by (rewrite !lbl_app, LB1, LB2, LB3, LA5, LA6; reflexivity).
    assert (EL2 : lbl (B5 ++ B6) = cb_m1 cB3 ++ cb_m2 cB3 ++ cb_m3 cB3 ++ cb_v2 cB3 ++ cb_v3 cB3).
    { change (cb_m1 cB3) with (@nil (Z * Z)). change (cb_m2 cB3) with (@nil (Z * Z)). change (cb_m3 cB3) with (@nil (Z * Z)).
      rewrite !app_nil_l. rewrite !lbl_app, LB5, LB6. reflexivity. }
    assert (VR1 : vraw MI_A (lbl LBq) M3 (st1 + 168) b2 e2 q2).
    { eapply (sv_vraw_move _ m1 M3 (st2 + 168) (st1 + 168) b2 e2 q2 V1Bq); [| lia].
      eapply rw_cells_transport; [exact CW2 | exact MU3 | exact WM3 |]. cbn [disjoint_from cells_size csize Z.of_nat]. lia. }
    assert (CZ : rw_cells asegs M3 (st2 + 168) [C8 (wz 0); C8 (wz 0); C8 (wz 0)]) by exact (sv2_zero3 _ _ CB3).
    assert (R1N : state_repA LBq M3 st1 cA4).
    { eapply (rep_upd_v1 H LBc LBq LBq spf (XW 168 24) m M3 st1 cA3 (st_v1 c2) R1 XPt (objx_st1 LBq 168 24 ltac:(lia) ltac:(lia)));
        [| | | lia | lia |].
      - rewrite <- EL1. apply blkx_stage; [exact INB1 | exact INA1 | lia | lia].
      - rewrite EV2. exact VR1.
      - eapply (nodup_fst_of_perm' H HH sq LBq M3 (B1 ++ B2 ++ B3 ++ B4 ++ A5 ++ A6) (LB0 ++ B5 ++ B6)); [exact RH3 | |].
        + eapply Permutation_trans; [exact PRMq|]. unfold L4. perm_solve.
        + rewrite state_blocks_cb, !lbl_app, LB1, LB2, LB3, LB4, LA5, LA6. apply Permutation_refl.
      - exact (proj1 (proj2 R2)). }
    assert (SH1N : state_sh M3 cA4).
    { eapply (sh_upd_v1 H LBc LBq spf (XW 168 24) m M3 st1 cA3 (st_v1 c2) R1 SH1 XPt).
      - rewrite <- EL1. eapply blksh_stage; [exact RH3 | exact INB1 | lia | lia].
      - pose proof SH2 as (_ & _ & _ & VS2 & _ & _). change (st_v1 cB3) with (st_v1 c2) in VS2.
        eapply (vec_sh_xp H LBq spf (XW 168 24) m M3 (st_v1 c2) XPt VS2).
        + rewrite EV2. exact ORD2.
        + change (vec_blocks (st_v1 c2)) with (cb_v1 c2). rewrite <- LB4. eapply blksh_stage; [exact RH3 | exact INB4 | lia | lia]. }
    assert (R2N : state_repA LBq M3 st2 cB4).
    { eapply (rep_upd_v1 H LBc LBq LBq spf (XW 168 24) m M3 st2 cB3 V0 R2 XPt (objx_st2 LBq 168 24 ltac:(lia) ltac:(lia)));
        [| | | lia | lia |].
      - rewrite <- EL2. apply blkx_stage; [exact INB2 | exact INA2 | lia | lia].
      - exact (sv_vraw0 _ _ _ CZ ltac:(lia)).
      - eapply (nodup_fst_of_perm' H HH sq LBq M3 (B5 ++ B6) (LB0 ++ B1 ++ B2 ++ B3 ++ B4 ++ A5 ++ A6)); [exact RH3 | |].
        + eapply Permutation_trans; [exact PRMq|]. unfold L4. perm_solve.
        + rewrite state_blocks_cb, !lbl_app, LB5, LB6.
          change (cb_m1 (set_v1 cB3 V0)) with (@nil (Z * Z)). change (cb_m2 (set_v1 cB3 V0)) with (@nil (Z * Z)).
          change (cb_m3 (set_v1 cB3 V0)) with (@nil (Z * Z)). change (cb_v1 (set_v1 cB3 V0)) with (@nil (Z * Z)).
          rewrite !app_nil_l. apply Permutation_refl.
      - intros C. exfalso. apply C. reflexivity. }
    assert (SH2N : state_sh M3 cB4).
    { eapply (sh_upd_v1 H LBc LBq spf (XW 168 24) m M3 st2 cB3 V0 R2 SH2 XPt).
      - rewrite <- EL2. eapply blksh_stage; [exact RH3 | exact INB2 | lia | lia].
      - intros C. exfalso. apply C. reflexivity. }
    assert (IV4 : INV sq LBq M3 cA4 cB4 L4).
    { eapply (INV_step s LBc m cA3 cB3 L3 sq LBq M3 LBq 168 24 cA4 cB4 L4 IV0 XPt); try eassumption; try lia.
      - intros b Hb. apply INq. apply in_or_app; left; exact Hb.
      - rewrite HCF in AL1. lia. }
    eapply (stage_v2 sq LBq M3 msF4 mo4); [exact VIS4 | exact KR4 | | exact IV4].
    eapply (ah_mpres_trans H HH); [exact MP|]. eapply (ah_mpres_trans H HH); [exact MP1|].
    eapply (ah_mpres_trans H HH); [exact MP2|]. eapply (ah_mpres_trans H HH); [exact MP3 | exact MP4].
  Qed.

  Lemma stage_m3 : forall s LBc m msF mo
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word) (F : bvmap 5 word),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 AST_M3) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    INV s LBc m cA2 cB2 L2 ->
    as_SR H QF (mkCfg msF mo).
Proof.
    intros s LBc m msF mo x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 F
      VIS KR MP IV.
    pose proof IV as IV0.
    destruct IV as (MI & STK & ERR & RA & AC & RFS & S0 & RH & OWN & FR & R1 & SH1 & R2 & SH2 & AD1 & AD2 & PRM & XP0 & ALs).
    pose proof (obj_facts 128 ltac:(lia) ltac:(lia) eq_refl) as (O1R & O2R & AP & OFS1 & OFS2 & AFW1 & AFW2 & ACO1 & ACO2 & SV2).
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (ASTK : 96 < AST_MVA_STACK) by (unfold AST_MVA_STACK, AFREE_STACK; lia).
    assert (SPF16 : spf mod 16 = 0) by (unfold spf; rewrite Zminus_mod, SP16; reflexivity).
    lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
    pose (E := Eseed R [Z_to_bv 64 st1; Z_to_bv 64 st2]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EVar 32); (9%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (HK : know_ok asegs E m []) by (apply Forall_nil).
    xrun_at (PropExec.mkFP F fc) asegs R AST_M3 m (seg_rom asegs) HR HK 10%nat [LbB_HMva2.MVA] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1. }
    rreg HR' 1%bv G1. rreg HR' 10%bv G10. rreg HR' 11%bv G11. rreg HR' 12%bv G12. rreg HR' 8%bv G8. rreg HR' 9%bv G9.
    rewrite w_add in G10 by lia. rewrite w_add in G11 by lia.
    assert (HF0 : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF0) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rewrite ?G1, ?G8, ?G9, ?G10, ?G11, ?G12 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | rewrite HR0; apply rfull_mkR | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.
    assert (VIS1' : as_VIS H s msF1 = MS (mkR (Z_to_bv 64 AST_V1) (Z_to_bv 64 spf) gp tp x5 x6 x7
        (Z_to_bv 64 st1) (Z_to_bv 64 st2) (Z_to_bv 64 (st1 + 128)) (Z_to_bv 64 (st2 + 128)) (Z_to_bv 64 0)
        x13 x14 x15 x16 x17 x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
        F (Z_to_bv 64 LbB_HMva2.MVA) fc None m (seg_rom asegs)).
    { rewrite VIS1, HRe. reflexivity. }
    clear VIS1.
    set (LB0c := LB0 ++ B1 ++ B2 ++ A4 ++ A5 ++ A6 ++ B4 ++ B5 ++ B6).
    assert (STKf : stk asegs m lo spf) by exact (proj1 (stk_split asegs m lo spf spz STK ltac:(unfold spf; lia))).
    assert (ADD1 : addressable m (st1 + 128) 40) by exact (addressable_sub8 m st1 240 128 40 AD1 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (ADD2 : addressable m (st2 + 128) 40) by exact (addressable_sub8 m st2 240 128 40 AD2 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (ALp : 0 <= as_AL H s) by lia.
    assert (SPZRf : 2 ^ 45 <= spf - 96 /\ spf <= 2 ^ 47) by (unfold spf; lia).
    assert (LOHf : aceil <= lo /\ lo <= spf - 96 - AFREE_STACK) by (unfold spf, AST_MVA_STACK in *; lia).
    assert (SPBf : spf <= B) by (unfold spf; lia).
    assert (UMA1 := sr_m3 _ _ _ _ _ _ _ (proj1 R1)). assert (UMA2 := sr_m3 _ _ _ _ _ _ _ (proj1 R2)).
    assert (USA1 := proj1 (umap_sh_eta _ _ _ _) (proj1 (proj2 (proj2 SH1)))). assert (USA2 := proj1 (umap_sh_eta _ _ _ _) (proj1 (proj2 (proj2 SH2)))).
    eapply (ah_seq H HH).
    { eapply LbB_HMvaT2.mva_entry with (H := H) (ra := Z_to_bv 64 AST_V1) (gp := gp) (tp := tp)
        (s0 := Z_to_bv 64 st1) (s1 := Z_to_bv 64 st2) (s2 := x18) (s3 := x19) (s4 := x20) (s5 := x21)
        (s6 := Z_to_bv 64 2147450880) (s7 := x23) (s8 := x24) (s9 := x25) (s10 := x26) (s11 := s11)
        (fc := fc) (o1 := st1 + 128) (o2 := st2 + 128) (spz := spf) (lo := lo) (B := B) (shi := shi) (errv := errv) (LF := LF)
        (LB0 := LB0c) (m0 := m) (mo0 := mo1) (st0 := s)
        (bl1 := t3a (st_m3 c1)) (bc1 := t3b (st_m3 c1)) (ents1 := t3c (st_m3 c1))
        (bl2 := t3a (st_m3 c2)) (bc2 := t3b (st_m3 c2)) (ents2 := t3c (st_m3 c2))
        (LB := LBc) (LBs1 := A3) (LBs2 := B3).
      all: try first
        [ assumption | exact VIS1'
        | (apply tr_of; unfold ST_MVA_DEL_RAS; repeat (first [left; reflexivity | right]))
        | (eapply Permutation_trans; [exact PRM|]; unfold L2, LB0c; perm_solve)
        | (rewrite LA3; apply Permutation_refl)
        | (rewrite LB3; apply Permutation_refl)
        | (intros b Hb; destruct (in_lbl_allb B3 b Hb ltac:(intros b' Hb'; unfold ALLB; inapp_solve))
             as [K1 K2]; unfold apart; lia) ].
    }
    intros cf POST. destruct cf as [msF2 mo2].
    destruct POST as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & mq & sq & LBq & Fq
      & VIS2 & KR2 & MP2 & MI2 & STK2 & ERR2 & RA2 & RH2 & PRM2 & UM1 & US1 & UM2 & AD12 & AD22 & XP2 & RFS2 & AC2 & S02 & AL2 & OWN2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite (ret_pc_even AST_V1 ltac:(unfold AST_V1; lia) eq_refl) in VIS2.
    assert (INB : forall b, In b (B1 ++ B2 ++ A4 ++ A5 ++ A6) -> In b LB0c /\ In b LBq).
    { intros b Hb. split.
      - unfold LB0c. inapp_solve.
      - eapply Permutation_in; [apply Permutation_sym; exact PRM2|]. unfold LB0c. inapp_solve. }
    assert (INB2 : forall b, In b (B4 ++ B5 ++ B6) -> In b LB0c /\ In b LBq).
    { intros b Hb. split.
      - unfold LB0c. inapp_solve.
      - eapply Permutation_in; [apply Permutation_sym; exact PRM2|]. unfold LB0c. inapp_solve. }
    assert (INA : forall b, In b (B1 ++ B2 ++ A4 ++ A5 ++ A6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (INA2 : forall b, In b (B4 ++ B5 ++ B6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (EL1 : lbl (B1 ++ B2 ++ A4 ++ A5 ++ A6) = cb_m1 cA2 ++ cb_m2 cA2 ++ cb_v1 cA2 ++ cb_v2 cA2 ++ cb_v3 cA2)
      by (rewrite !lbl_app, LB1, LB2, LA4, LA5, LA6; reflexivity).
    assert (EL2 : lbl (B4 ++ B5 ++ B6) = cb_m1 cB2 ++ cb_m2 cB2 ++ cb_v1 cB2 ++ cb_v2 cB2 ++ cb_v3 cB2).
    { change (cb_m1 cB2) with (@nil (Z * Z)). change (cb_m2 cB2) with (@nil (Z * Z)). rewrite !app_nil_l.
      rewrite !lbl_app, LB4, LB5, LB6. reflexivity. }
    eapply (stage_v1 sq LBq mq msF2 mo2); [exact VIS2 | exact KR2 | eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2]] |].
    eapply (INV_step s LBc m cA2 cB2 L2 sq LBq mq LB0c 128 40); try eassumption; try lia.
    - intros b Hb. unfold LB0c. inapp_solve.
    - eapply (rep_upd_m3 H LBc LBq LB0c spf (XW 128 40) m mq st1 cA2 (st_m3 c2)); [exact R1 | exact XP2 | exact (objx_st1 LB0c 128 40 ltac:(lia) ltac:(lia)) | | exact UM1 | | lia | lia].
      + rewrite <- EL1. apply blkx_stage; [exact INB | exact INA | lia | lia].
      + eapply (nodup_fst_of_perm' H HH sq LBq mq (B1 ++ B2 ++ B3 ++ A4 ++ A5 ++ A6) (LB0 ++ B4 ++ B5 ++ B6)); [exact RH2 | |].
        * eapply Permutation_trans; [exact PRM2|]. unfold LB0c. perm_solve.
        * rewrite state_blocks_cb, !lbl_app, LB1, LB2, LB3, LA4, LA5, LA6. apply Permutation_refl.
    - eapply (sh_upd_m3 H LBc LB0c spf (XW 128 40) m mq st1 cA2 (st_m3 c2)); [exact R1 | exact SH1 | exact XP2 | | exact (proj2 (umap_sh_eta _ _ _ _) US1)].
      rewrite <- EL1. eapply blksh_stage; [exact RH2 | exact INB | lia | lia].
    - eapply (rep_upd_m3 H LBc LBq LB0c spf (XW 128 40) m mq st2 cB2 E3); [exact R2 | exact XP2 | exact (objx_st2 LB0c 128 40 ltac:(lia) ltac:(lia)) | | exact UM2 | | lia | lia].
      + rewrite <- EL2. apply blkx_stage; [exact INB2 | exact INA2 | lia | lia].
      + eapply (nodup_fst_of_perm' H HH sq LBq mq (B4 ++ B5 ++ B6) (LB0 ++ B1 ++ B2 ++ A4 ++ A5 ++ A6 ++ B3)); [exact RH2 | |].
        * eapply Permutation_trans; [exact PRM2|]. unfold LB0c. perm_solve.
        * rewrite state_blocks_cb, !lbl_app, LB4, LB5, LB6.
          change (cb_m1 (set_m3 cB2 E3)) with (@nil (Z * Z)). change (cb_m2 (set_m3 cB2 E3)) with (@nil (Z * Z)).
          change (cb_m3 (set_m3 cB2 E3)) with (@nil (Z * Z)). rewrite !app_nil_l. apply Permutation_refl.
    - eapply (sh_upd_m3 H LBc LB0c spf (XW 128 40) m mq st2 cB2 E3); [exact R2 | exact SH2 | exact XP2 | | exact (umap_sh_E3 mq 24)].
      rewrite <- EL2. eapply blksh_stage; [exact RH2 | exact INB2 | lia | lia].
    - eapply Permutation_trans; [exact PRM2|]. unfold LB0c, L3. perm_solve.
  Qed.

  Lemma stage_nt : forall s LBc m msF mo
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word) (F : bvmap 5 word),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 LbB_HStNT.NT_E) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    INV s LBc m cA1 cB1 L1 ->
    as_SR H QF (mkCfg msF mo).
Proof.
    intros s LBc m msF mo x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 F
      VIS KR MP IV.
    pose proof IV as IV0.
    destruct IV as (MI & STK & ERR & RA & AC & RFS & S0 & RH & OWN & FR & R1 & SH1 & R2 & SH2 & AD1 & AD2 & PRM & XP0 & ALs).
    pose proof (obj_facts 88 ltac:(lia) ltac:(lia) eq_refl) as (O1R & O2R & AP & OFS1 & OFS2 & AFW1 & AFW2 & ACO1 & ACO2 & SV2).
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (ASTK : 96 < AST_MVA_STACK) by (unfold AST_MVA_STACK, AFREE_STACK; lia).
    assert (O2Rn : AIMG_TOP <= st2 + 88 /\ st2 + 88 + 40 <= 2 ^ 47 /\ (st2 + 88) mod 8 = 0 /\ in_app_mem (st2 + 88) (st2 + 88 + 40)
                   /\ (st2 + 88 + 40 <= aceil \/ spz <= st2 + 88)).
    { destruct O2R as (Q1 & Q2 & Q3 & Q4 & Q5). refine (conj Q1 (conj Q2 (conj Q3 (conj Q4 _)))).
      destruct FS2 as [K|K]; [left; destruct FSBOK as (_ & FB2 & _); lia | right; lia]. }
    assert (ADD1 : addressable m (st1 + 88) 40) by exact (addressable_sub8 m st1 240 88 40 AD1 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (ADD2 : addressable m (st2 + 88) 40) by exact (addressable_sub8 m st2 240 88 40 AD2 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (ALp : 0 <= as_AL H s) by lia.
    assert (SPZRn : 2 ^ 45 <= spz - 96 /\ spz <= 2 ^ 47) by lia.
    assert (LOHn : aceil <= lo /\ lo <= spz - 96 - AFREE_STACK) by (unfold AST_MVA_STACK in *; lia).
    assert (UMA1 := sr_m2 _ _ _ _ _ _ _ (proj1 R1)). assert (UMA2 := sr_m2 _ _ _ _ _ _ _ (proj1 R2)).
    assert (USA1 := proj1 (umap_sh_eta _ _ _ _) (proj1 (proj2 SH1))).
    assert (USA2 := proj1 (umap_sh_eta _ _ _ _) (proj1 (proj2 SH2))).
    set (LB0c := LB0 ++ B1 ++ A3 ++ A4 ++ A5 ++ A6 ++ B3 ++ B4 ++ B5 ++ B6).
    eapply (ah_seq H HH).
    { eapply LbB_HStNT.ntm_entry with (H := H) (ra := ra) (gp := gp) (tp := tp) (s0 := s0) (s1 := s1) (s2 := s2) (s3 := s3)
        (s4 := s4) (s5 := s5) (s6 := s6) (s7 := s7) (s8 := s8) (s9 := s9) (s10 := s10) (s11 := s11) (fc := fc)
        (st1 := st1) (st2 := st2) (o1 := st1 + 88) (o2 := st2 + 88) (spz := spz) (lo := lo) (B := B) (shi := shi)
        (errv := errv) (LF := LF) (LB0 := LB0c) (m0 := m) (mo0 := mo) (st0 := s)
        (bl1 := t3a (st_m2 c1)) (bc1 := t3b (st_m2 c1)) (ents1 := t3c (st_m2 c1))
        (bl2 := t3a (st_m2 c2)) (bc2 := t3b (st_m2 c2)) (ents2 := t3c (st_m2 c2))
        (LB := LBc) (LBs1 := A2) (LBs2 := B2).
      all: try first
        [ assumption | exact VIS | reflexivity
        | exact (conj MI (conj STK (conj ERR (conj RA (conj AC (conj RFS (conj S0 (conj RH (conj FR (conj ADD1 (conj ADD2
            (conj USA2 (conj (xpres_refl _ _ _ _ _) OWN)))))))))))))
        | (apply tr_of; unfold ST_MVA_DEL_RAS; repeat (first [left; reflexivity | right]))
        | (eapply Permutation_trans; [exact PRM|]; unfold L1, LB0c; perm_solve)
        | (rewrite LA2; apply Permutation_refl)
        | (rewrite LB2; apply Permutation_refl)
        | (intros b Hb; destruct (in_lbl_allb B2 b Hb ltac:(intros b' Hb'; unfold ALLB; inapp_solve))
             as [K1 K2]; unfold apart; lia) ].
    }
    intros cf POST. destruct cf as [msF2 mo2].
    destruct POST as (y1 & y5 & y6 & y7 & y10 & y11 & y12 & y13 & y14 & y15 & y16 & y17 & y18 & y19 & y20 & y21 & y23 & y24
      & y25 & y26 & y28 & y29 & y30 & y31 & mq & sq & LBq & Fq
      & VIS2 & KR2 & MP2 & MI2 & STK2 & ERR2 & RA2 & RH2 & PRM2 & UM1 & US1 & UM2 & AD12 & AD22 & FR2 & XP2 & RFS2 & AC2 & S02 & AL2 & OWN2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    assert (INB : forall b, In b (B1 ++ A3 ++ A4 ++ A5 ++ A6) -> In b LB0c /\ In b LBq).
    { intros b Hb. split.
      - unfold LB0c. inapp_solve.
      - eapply Permutation_in; [apply Permutation_sym; exact PRM2|]. unfold LB0c. inapp_solve. }
    assert (INB2 : forall b, In b (B3 ++ B4 ++ B5 ++ B6) -> In b LB0c /\ In b LBq).
    { intros b Hb. split.
      - unfold LB0c. inapp_solve.
      - eapply Permutation_in; [apply Permutation_sym; exact PRM2|]. unfold LB0c. inapp_solve. }
    assert (INA : forall b, In b (B1 ++ A3 ++ A4 ++ A5 ++ A6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (INA2 : forall b, In b (B3 ++ B4 ++ B5 ++ B6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (EL1 : lbl (B1 ++ A3 ++ A4 ++ A5 ++ A6) = cb_m1 cA1 ++ cb_m3 cA1 ++ cb_v1 cA1 ++ cb_v2 cA1 ++ cb_v3 cA1)
      by (rewrite !lbl_app, LB1, LA3, LA4, LA5, LA6; reflexivity).
    assert (EL2 : lbl (B3 ++ B4 ++ B5 ++ B6) = cb_m1 cB1 ++ cb_m3 cB1 ++ cb_v1 cB1 ++ cb_v2 cB1 ++ cb_v3 cB1).
    { change (cb_m1 cB1) with (@nil (Z * Z)). rewrite app_nil_l. rewrite !lbl_app, LB3, LB4, LB5, LB6. reflexivity. }
    eapply (stage_m3 sq LBq mq msF2 mo2); [exact VIS2 | exact KR2 | eapply (ah_mpres_trans H HH); [exact MP | exact MP2] |].
    eapply (INV_step_z s LBc m cA1 cB1 L1 sq LBq mq LB0c 88 40); try eassumption; try lia.
    - intros b Hb. unfold LB0c. inapp_solve.
    - eapply (rep_upd_m2 H LBc LBq LB0c spz (XW 88 40) m mq st1 cA1 (st_m2 c2)); [exact R1 | exact XP2 | exact (objx_st1g LB0c spz 88 40 ltac:(lia) ltac:(lia)) | | exact UM1 | | lia | lia].
      + rewrite <- EL1. apply blkx_stageg; [exact INB | exact INA | lia | lia].
      + eapply (nodup_fst_of_perm' H HH sq LBq mq (B1 ++ B2 ++ A3 ++ A4 ++ A5 ++ A6) (LB0 ++ B3 ++ B4 ++ B5 ++ B6)); [exact RH2 | |].
        * eapply Permutation_trans; [exact PRM2|]. unfold LB0c. perm_solve.
        * rewrite state_blocks_cb, !lbl_app, LB1, LB2, LA3, LA4, LA5, LA6. apply Permutation_refl.
    - eapply (sh_upd_m2 H LBc LB0c spz (XW 88 40) m mq st1 cA1 (st_m2 c2)); [exact R1 | exact SH1 | exact XP2 | | exact (proj2 (umap_sh_eta _ _ _ _) US1)].
      rewrite <- EL1. eapply blksh_stageg; [exact RH2 | exact INB | lia | lia].
    - eapply (rep_upd_m2 H LBc LBq LB0c spz (XW 88 40) m mq st2 cB1 E3N); [exact R2 | exact XP2 | exact (objx_st2g LB0c spz 88 40 ltac:(lia) ltac:(lia) ltac:(lia)) | | exact UM2 | | lia | lia].
      + rewrite <- EL2. apply blkx_stageg; [exact INB2 | exact INA2 | lia | lia].
      + eapply (nodup_fst_of_perm' H HH sq LBq mq (B3 ++ B4 ++ B5 ++ B6) (LB0 ++ B1 ++ A3 ++ A4 ++ A5 ++ A6 ++ B2)); [exact RH2 | |].
        * eapply Permutation_trans; [exact PRM2|]. unfold LB0c. perm_solve.
        * rewrite state_blocks_cb, !lbl_app, LB3, LB4, LB5, LB6.
          change (cb_m1 (set_m2 cB1 E3N)) with (@nil (Z * Z)). change (cb_m2 (set_m2 cB1 E3N)) with (@nil (Z * Z)).
          rewrite !app_nil_l. apply Permutation_refl.
    - eapply (sh_upd_m2 H LBc LB0c spz (XW 88 40) m mq st2 cB1 E3N); [exact R2 | exact SH2 | exact XP2 | | exact (umap_sh_E3N mq 32)].
      rewrite <- EL2. eapply blksh_stageg; [exact RH2 | exact INB2 | lia | lia].
    - eapply Permutation_trans; [exact PRM2|]. unfold LB0c, L2. perm_solve.
