  Lemma stage_m1 : forall s LBc m msF mo
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 : word) (F : bvmap 5 word),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) (Z_to_bv 64 st2) x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 AST_M1) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    INV s LBc m cA0 c2 L0 ->
    as_SR H QF (mkCfg msF mo).
Proof.
    intros s LBc m msF mo x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x23 x24 x25 x26 x28 x29 x30 x31 F
      VIS KR MP IV.
    pose proof IV as IV0.
    destruct IV as (MI & STK & ERR & RA & AC & RFS & S0 & RH & OWN & FR & R1 & SH1 & R2 & SH2 & AD1 & AD2 & PRM & XP0 & ALs).
    pose proof (obj_facts 48 ltac:(lia) ltac:(lia) eq_refl) as (O1R & O2R & AP & OFS1 & OFS2 & AFW1 & AFW2 & ACO1 & ACO2 & SV2).
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (ASTK : 96 < AST_MVA_STACK) by (unfold AST_MVA_STACK, AFREE_STACK; lia).
    assert (SPF16 : spf mod 16 = 0) by (unfold spf; rewrite Zminus_mod, SP16; reflexivity).
    lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
    pose (E := Eseed R [Z_to_bv 64 st1; Z_to_bv 64 st2]).
    assert (HR : regs_ok E (srs sr_id [(8%bv, EVar 32); (9%bv, EVar 33)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat constructor; cbn [fst snd]; try (intros X; discriminate X); subst R; evs; reflexivity. }
    assert (HK : know_ok asegs E m []) by (apply Forall_nil).
    xrun_at (PropExec.mkFP F fc) asegs R AST_M1 m (seg_rom asegs) HR HK 10%nat [LbB_HMva.MVA] (SCR [] [] []) 40%N.
    { split_scs; try sc_auto1. }
    rreg HR' 1%bv G1. rreg HR' 10%bv G10. rreg HR' 11%bv G11. rreg HR' 12%bv G12. rreg HR' 8%bv G8. rreg HR' 9%bv G9.
    rewrite w_add in G10 by lia. rewrite w_add in G11 by lia.
    assert (HF0 : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose proof (msteps_full asegs _ _ Hms HF0) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rewrite ?G1, ?G8, ?G9, ?G10, ?G11, ?G12 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | rewrite HR0; apply rfull_mkR | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.
    assert (VIS1' : as_VIS H s msF1 = MS (mkR (Z_to_bv 64 LbB_HStNT.NT_E) (Z_to_bv 64 spf) gp tp x5 x6 x7
        (Z_to_bv 64 st1) (Z_to_bv 64 st2) (Z_to_bv 64 (st1 + 48)) (Z_to_bv 64 (st2 + 48)) (Z_to_bv 64 0)
        x13 x14 x15 x16 x17 x18 x19 x20 x21 (Z_to_bv 64 2147450880) x23 x24 x25 x26 s11 x28 x29 x30 x31)
        F (Z_to_bv 64 LbB_HMva.MVA) fc None m (seg_rom asegs)).
    { rewrite VIS1, HRe. reflexivity. }
    clear VIS1.
    set (LB0c := LB0 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6).
    assert (STKf : stk asegs m lo spf) by exact (proj1 (stk_split asegs m lo spf spz STK ltac:(unfold spf; lia))).
    assert (ADD1 : addressable m (st1 + 48) 40) by exact (addressable_sub8 m st1 240 48 40 AD1 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (ADD2 : addressable m (st2 + 48) 40) by exact (addressable_sub8 m st2 240 48 40 AD2 eq_refl eq_refl eq_refl ltac:(lia) ltac:(lia) ltac:(lia)).
    assert (ALp : 0 <= as_AL H s) by lia.
    assert (SPZRf : 2 ^ 45 <= spf - 96 /\ spf <= 2 ^ 47) by (unfold spf; lia).
    assert (LOHf : aceil <= lo /\ lo <= spf - 96 - AFREE_STACK) by (unfold spf, AST_MVA_STACK in *; lia).
    assert (SPBf : spf <= B) by (unfold spf; lia).
    assert (UMA1 := sr_m1 _ _ _ _ _ _ _ (proj1 R1)). assert (UMA2 := sr_m1 _ _ _ _ _ _ _ (proj1 R2)).
    assert (USA1 := proj1 (umap_sh_eta _ _ _ _) (proj1 SH1)). assert (USA2 := proj1 (umap_sh_eta _ _ _ _) (proj1 SH2)).
    eapply (ah_seq H HH).
    { eapply LbB_HMvaT.mva_entry with (H := H) (ra := Z_to_bv 64 LbB_HStNT.NT_E) (gp := gp) (tp := tp)
        (s0 := Z_to_bv 64 st1) (s1 := Z_to_bv 64 st2) (s2 := x18) (s3 := x19) (s4 := x20) (s5 := x21)
        (s6 := Z_to_bv 64 2147450880) (s7 := x23) (s8 := x24) (s9 := x25) (s10 := x26) (s11 := s11)
        (fc := fc) (o1 := st1 + 48) (o2 := st2 + 48) (spz := spf) (lo := lo) (B := B) (shi := shi) (errv := errv) (LF := LF)
        (LB0 := LB0c) (m0 := m) (mo0 := mo1) (st0 := s)
        (bl1 := t3a (st_m1 c1)) (bc1 := t3b (st_m1 c1)) (ents1 := t3c (st_m1 c1))
        (bl2 := t3a (st_m1 c2)) (bc2 := t3b (st_m1 c2)) (ents2 := t3c (st_m1 c2))
        (LB := LBc) (LBs1 := A1) (LBs2 := B1).
      all: try first
        [ assumption | exact VIS1'
        | (apply tr_of; unfold ST_MVA_DEL_RAS; repeat (first [left; reflexivity | right]))
        | (eapply Permutation_trans; [exact PRM|]; unfold L0, LB0c; perm_solve)
        | (rewrite LA1; apply Permutation_refl)
        | (rewrite LB1; apply Permutation_refl)
        | (intros b Hb; destruct (in_lbl_allb B1 b Hb ltac:(intros b' Hb'; unfold ALLB; inapp_solve))
             as [K1 K2]; unfold apart; lia) ].
    }
    intros cf POST. destruct cf as [msF2 mo2].
    destruct POST as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & mq & sq & LBq & Fq
      & VIS2 & KR2 & MP2 & MI2 & STK2 & ERR2 & RA2 & RH2 & PRM2 & UM1 & US1 & UM2 & AD12 & AD22 & XP2 & RFS2 & AC2 & S02 & AL2 & OWN2).
    cbn [cfg_ms cfg_model] in VIS2, KR2, MP2.
    rewrite (ret_pc_even LbB_HStNT.NT_E ltac:(unfold LbB_HStNT.NT_E; lia) eq_refl) in VIS2.
    assert (INB : forall b, In b (A2 ++ A3 ++ A4 ++ A5 ++ A6) -> In b LB0c /\ In b LBq).
    { intros b Hb. split.
      - unfold LB0c. inapp_solve.
      - eapply Permutation_in; [apply Permutation_sym; exact PRM2|]. unfold LB0c. inapp_solve. }
    assert (INB2 : forall b, In b (B2 ++ B3 ++ B4 ++ B5 ++ B6) -> In b LB0c /\ In b LBq).
    { intros b Hb. split.
      - unfold LB0c. inapp_solve.
      - eapply Permutation_in; [apply Permutation_sym; exact PRM2|]. unfold LB0c. inapp_solve. }
    assert (INA : forall b, In b (A2 ++ A3 ++ A4 ++ A5 ++ A6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (INA2 : forall b, In b (B2 ++ B3 ++ B4 ++ B5 ++ B6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (EL1 : lbl (A2 ++ A3 ++ A4 ++ A5 ++ A6) = cb_m2 cA0 ++ cb_m3 cA0 ++ cb_v1 cA0 ++ cb_v2 cA0 ++ cb_v3 cA0)
      by (rewrite !lbl_app, LA2, LA3, LA4, LA5, LA6; reflexivity).
    assert (EL2 : lbl (B2 ++ B3 ++ B4 ++ B5 ++ B6) = cb_m2 c2 ++ cb_m3 c2 ++ cb_v1 c2 ++ cb_v2 c2 ++ cb_v3 c2)
      by (rewrite !lbl_app, LB2, LB3, LB4, LB5, LB6; reflexivity).
    eapply (stage_nt sq LBq mq msF2 mo2); [exact VIS2 | exact KR2 | eapply (ah_mpres_trans H HH); [exact MP | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2]] |].
    eapply (INV_step s LBc m cA0 c2 L0 sq LBq mq LB0c 48 40); try eassumption; try lia.
    - intros b Hb. unfold LB0c. inapp_solve.
    - eapply (rep_upd_m1 H LBc LBq LB0c spf (XW 48 40) m mq st1 cA0 (st_m1 c2)); [exact R1 | exact XP2 | exact (objx_st1 LB0c 48 40 ltac:(lia) ltac:(lia)) | | exact UM1 | | lia | lia].
      + rewrite <- EL1. apply blkx_stage; [exact INB | exact INA | lia | lia].
      + eapply (nodup_fst_of_perm' H HH sq LBq mq (B1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6) (LB0 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6)); [exact RH2 | |].
        * eapply Permutation_trans; [exact PRM2|]. unfold LB0c. perm_solve.
        * rewrite state_blocks_cb, !lbl_app, LB1, LA2, LA3, LA4, LA5, LA6. apply Permutation_refl.
    - eapply (sh_upd_m1 H LBc LB0c spf (XW 48 40) m mq st1 cA0 (st_m1 c2)); [exact R1 | exact SH1 | exact XP2 | | exact (proj2 (umap_sh_eta _ _ _ _) US1)].
      rewrite <- EL1. eapply blksh_stage; [exact RH2 | exact INB | lia | lia].
    - eapply (rep_upd_m1 H LBc LBq LB0c spf (XW 48 40) m mq st2 c2 E3); [exact R2 | exact XP2 | exact (objx_st2 LB0c 48 40 ltac:(lia) ltac:(lia)) | | exact UM2 | | lia | lia].
      + rewrite <- EL2. apply blkx_stage; [exact INB2 | exact INA2 | lia | lia].
      + eapply (nodup_fst_of_perm' H HH sq LBq mq (B2 ++ B3 ++ B4 ++ B5 ++ B6) (LB0 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6 ++ B1)); [exact RH2 | |].
        * eapply Permutation_trans; [exact PRM2|]. unfold LB0c. perm_solve.
        * rewrite state_blocks_cb, !lbl_app, LB2, LB3, LB4, LB5, LB6. change (cb_m1 (set_m1 c2 E3)) with (@nil (Z * Z)). rewrite app_nil_l. apply Permutation_refl.
    - eapply (sh_upd_m1 H LBc LB0c spf (XW 48 40) m mq st2 c2 E3); [exact R2 | exact SH2 | exact XP2 | | exact (umap_sh_E3 mq 24)].
      rewrite <- EL2. eapply blksh_stage; [exact RH2 | exact INB2 | lia | lia].
    - eapply Permutation_trans; [exact PRM2|]. unfold LB0c, L1. perm_solve.
  Qed.

  Lemma sp_objx_re : forall LBk SP X X' st l0 h0, OBJX H LBk SP X st l0 h0 ->
    (forall a, st <= a < st + 240 -> rin_ivs X' a -> rin_ivs X a) -> OBJX H LBk SP X' st l0 h0.
  Proof.
    intros LBk SP X X' st l0 h0 O IMP a Ha Hn. destruct (O a Ha Hn) as [C N].
    split; [exact C | intros K; apply N, IMP; assumption].
  Qed.

  Lemma sp_blkx_re : forall LBk SP X X' LBb bs, BLKX H LBk SP X LBb bs ->
    (forall a, rin_ivs X' a -> rin_ivs X a) -> BLKX H LBk SP X' LBb bs.
  Proof.
    intros LBk SP X X' LBb bs BX IMP p n Hp. destruct (BX p n Hp) as [K I]. split; [|exact I].
    intros a Ha. destruct (K a Ha) as [C N]. split; [exact C | intros Q; apply N, IMP, Q].
  Qed.

  Lemma sp_blksh_re : forall LBk SP X X' bs, BLKSH H LBk SP X bs ->
    (forall a, rin_ivs X' a -> rin_ivs X a) -> BLKSH H LBk SP X' bs.
  Proof.
    intros LBk SP X X' bs BX IMP p n Hp a Ha. destruct (BX p n Hp a Ha) as [C N].
    split; [exact C | intros Q; apply N, IMP, Q].
  Qed.

  Lemma sp_cb_of_def : forall m a N n, HRep.defined m a N -> n <= N -> AIMG_TOP <= a -> 0 <= n -> a + n <= 2 ^ 64 ->
    exists bs, rw_cells asegs m a [CB (Z.to_nat n) bs] /\ bytes_at asegs m a bs /\ length bs = Z.to_nat n.
  Proof.
    intros m a N n D HnN Ha Hn Han.
    assert (W : wr_at asegs m a n).
    { split; [unfold AIMG_TOP in Ha; lia|]. split; [lia|]. intros i Hi. pose proof (D i ltac:(lia)) as Di.
      unfold wview, wa. destruct (m (Z_to_bv 64 (a + i))) as [b|] eqn:E; [discriminate | contradiction]. }
    destruct (rw_cells_of_wr_hi m a n W Ha Hn) as (bs & RW).
    exists bs. split; [exact RW|].
    pose proof RW as [[WF BA] _]. cbn [cells_wf cell_wf] in WF. cbn [cells_bytes cbytes] in BA. rewrite app_nil_r in BA.
    split; [exact BA | tauto].
  Qed.

  Lemma stage_p : forall LB msF (t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word),
    as_VIS H sk0 msF = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 st1) (Z_to_bv 64 st2) a2 a3 a4 a5 a6 a7
                               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (Z_to_bv 64 AST_MVA) fc None m0 (seg_rom asegs) ->
    as_AKREL H sk0 (mkCfg msF mo0) ->
    mem_inv asegs m0 -> stk asegs m0 lo spz -> rw_cells asegs m0 (errno_addr tp) [C4 errv] -> as_rauxv_ok H m0 B ->
    ACONST m0 -> as_RFS H LF m0 -> stack0 m0 lo shi -> as_RHEAP H sk0 LB m0 -> lb_own LB m0 ->
    state_repA LB m0 st1 c1 -> state_sh m0 c1 -> state_repA LB m0 st2 c2 -> state_sh m0 c2 ->
    addressable m0 st1 240 -> addressable m0 st2 240 ->
    Permutation LB (LB0 ++ L0) ->
    as_SR H QF (mkCfg msF mo0).
Proof.
    intros LB msF t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F VIS KR MI STK ERR RA AC RFS S0 RH OWN R1 SH1 R2 SH2 AD1 AD2 PRM.
    pose proof st_al_facts as (FST1 & ST1L & ST1H & ST2L & ST2H).
    pose proof aceil_facts as ((ACF1 & ACF2) & ACF3 & ACF4).
    pose proof FSBOK as (FB1 & FB2 & FB3 & FB4).
    assert (AIT : 0 < AIMG_TOP) by (unfold AIMG_TOP; lia).
    assert (LOH' : aceil <= lo /\ lo <= spz - 256 - 8192) by (unfold AST_MVA_STACK, AFREE_STACK in LOH; lia).
    assert (SUB0 : forall b, In b LB0 -> In b LB).
    { intros b Hb. eapply Permutation_in; [apply Permutation_sym; exact PRM | apply in_or_app; left; exact Hb]. }
    assert (INL : forall b, In b L0 -> In b LB).
    { intros b Hb. eapply Permutation_in; [apply Permutation_sym; exact PRM | apply in_or_app; right; exact Hb]. }
    assert (EB1 : state_blocks c1 = lbl (A1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6))
      by (rewrite state_blocks_cb, !lbl_app, LA1, LA2, LA3, LA4, LA5, LA6; reflexivity).
    assert (EB2 : state_blocks c2 = lbl (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6))
      by (rewrite state_blocks_cb, !lbl_app, LB1, LB2, LB3, LB4, LB5, LB6; reflexivity).
    assert (IN1 : forall b, In b (A1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6) -> In b LB /\ In b LB).
    { intros b Hb. assert (K : In b LB) by (apply INL; unfold L0; inapp_solve). split; exact K. }
    assert (IN2 : forall b, In b (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6) -> In b LB /\ In b LB).
    { intros b Hb. assert (K : In b LB) by (apply INL; unfold L0; inapp_solve). split; exact K. }
    assert (AL1 : forall b, In b (A1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (AL2 : forall b, In b (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6) -> In b ALLB) by (intros b Hb; unfold ALLB; inapp_solve).
    assert (EAB : 0 <= errno_addr tp /\ errno_addr tp + 4 <= AIMG_TOP).
    { rewrite TPV. split; apply Z.leb_le; vm_compute; reflexivity. }
    assert (U1 : bv_unsigned (Z_to_bv 64 st1) = st1) by (apply u64_of_Z; lia).
    assert (U2 : bv_unsigned (Z_to_bv 64 st2) = st2) by (apply u64_of_Z; lia).
    assert (U46 : bv_unsigned (Z_to_bv 64 46) = 46) by (apply u64_of_Z; lia).
    assert (Uspf : bv_unsigned (Z_to_bv 64 spf) = spf) by (apply u64_of_Z; unfold spf; lia).

    pose proof (ACONST_shbase m0 AC) as [CG CS].
    lazymatch type of VIS with _ = MS ?T _ _ _ _ _ _ => remember T as R eqn:HR0 end.
    assert (FHF : rfull R) by (rewrite HR0; apply rfull_mkR).
    pose (E := Eseed R [Z_to_bv 64 st1; Z_to_bv 64 st2; Z_to_bv 64 spz]).
    assert (HR : regs_ok E (srs sr_id [(10%bv, EVar 32); (11%bv, EVar 33); (2%bv, EVar 34)]) R).
    { apply regs_ok_srs; [apply regs_ok_seed|].
      repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X | subst R; evs; reflexivity] |]). apply Forall_nil. }
    assert (KG1 : kentry_ok asegs E m0 (KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL))).
    { eapply (kword_of_rw_cells asegs E m0 AGOT_SHBASE _ 0%nat);
        [exact CG | reflexivity | reflexivity | lia | reflexivity | unfold AGOT_SHBASE; lia | unfold AGOT_SHBASE; cbn; lia | reflexivity]. }
    assert (KG2 : kentry_ok asegs E m0 (KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit LbB_Kit.SHBASE))).
    { eapply (kword_of_rw_cells asegs E m0 ASHBASE_CELL _ 0%nat);
        [exact CS | reflexivity | reflexivity | lia | reflexivity | unfold ASHBASE_CELL; lia | unfold ASHBASE_CELL; cbn; lia | reflexivity]. }
    assert (KW : kentry_ok asegs E m0 (KWr (SA (EVar 34) (-96)) (ELit 96))).
    { eapply kwr_of_stk; [exact STK | unfold estart; evs; rewrite u64_of_Z by lia; lia
                         | unfold estart, elenZ; evs; rewrite !u64_of_Z by lia; lia | unfold elenZ; evs; rewrite u64_of_Z by lia; lia]. }
    assert (KQ : kentry_ok asegs E m0 (KRange (EVar 34) (2 ^ 45) (2 ^ 47))) by (cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; lia).
    assert (HK : know_ok asegs E m0 [KWord (SA (ELit 0) AGOT_SHBASE) 8 (ELit ASHBASE_CELL); KWord (SA (ELit 0) ASHBASE_CELL) 8 (ELit LbB_Kit.SHBASE);
                                    KWr (SA (EVar 34) (-96)) (ELit 96); KRange (EVar 34) (2 ^ 45) (2 ^ 47)]).
    { unfold know_ok. apply Forall_cons; [exact KG1|]. apply Forall_cons; [exact KG2|]. apply Forall_cons; [exact KW|].
      apply Forall_cons; [exact KQ | apply Forall_nil]. }
    xrun_at (PropExec.mkFP F fc) asegs R AST_MVA m0 (seg_rom asegs) HR HK 40%nat [AASAN_MEMCPY] (SCR [] [] []) 50%N.
    { split_scs; try sc_auto1. }
    lazymatch type of Hlf with log_flat _ ?lg =>
      lazymatch type of Hms with CatSim.msteps _ _ (@PropExec.mkst _ _ _ ?mm _) =>
        change mm with (mem_denot E m0 lg) in Hms; set (M1 := mem_denot E m0 lg) in Hms end;
      assert (LGE : lg = c8log (EVar 34) (-96) [EVar 26; EVar 25; EVar 24; EVar 23; EVar 22; EVar 21; EVar 20; EVar 19; EVar 18;
                                                EVar 9; EVar 8; EVar 1]) by reflexivity end.

    assert (MU1 : munch [(spf, spz)] m0 M1).
    { subst M1. apply munch_mem_denot; [exact Hlf|].
      repeat (apply Forall_cons; [cbn [e_addr e_width]; unfold estart; evs; rewrite ?u64_of_Z by lia;
                                  cbn [inside a_off a_base Z.of_nat Pos.of_succ_nat Pos.succ]; unfold spf; lia|]).
      apply Forall_nil. }
    assert (WM1 : wmono asegs m0 M1) by (subst M1; apply wmono_mem_denot).
    assert (MI1 : mem_inv asegs M1) by exact (msteps_mem_inv asegs _ _ Hms MI).
    assert (STK1 : stk asegs M1 lo spz) by (subst M1; apply stk_mem_denot; exact STK).
    assert (CE : map (fun v => C8 (edenot E v)) [EVar 26; EVar 25; EVar 24; EVar 23; EVar 22; EVar 21; EVar 20; EVar 19; EVar 18;
                                                 EVar 9; EVar 8; EVar 1]
                 = [C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra])
      by (unfold E; subst R; reflexivity).
    assert (FR1 : LbB_HStNT.sto_frame M1 spf ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10).
    { unfold LbB_HStNT.sto_frame. rewrite <- CE. subst M1. rewrite LGE. rewrite LGE in Hlf.
      apply rw_cells_c8log; [exact Hlf | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base]; unfold spf; lia |].
      destruct STK as (STa & STb & STc). cbn [length Z.of_nat Pos.of_succ_nat Pos.succ Pos.mul Z.mul].
      split; [unfold spf; lia|]. split; [unfold spf; lia|]. intros i Hi. exact (proj1 (STc (spf + i) ltac:(unfold spf in *; lia))). }
    assert (ERR1 : rw_cells asegs M1 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERR | exact MU1 | exact WM1 | cbn [disjoint_from cells_size csize Z.of_nat]; unfold spf, AIMG_TOP in *; lia]. }
    assert (SWa : aceil <= spf) by (unfold spf; lia).
    destruct (stack_window_ok H LB LF spf spz SWa FB2) as (W1a & W1b & W1c).
    destruct (client_frame H HH sk0 LB LF B [(spf, spz)] m0 M1 RH RFS AC RA MU1 WM1
               (Forall_cons _ _ _ W1a (Forall_nil _)) (Forall_cons _ _ _ W1b (Forall_nil _)) (Forall_cons _ _ _ W1c (Forall_nil _)))
      as (RH1 & RFS1 & AC1 & RA1).
    assert (S01 : stack0 M1 lo shi).
    { eapply stack0_transport; [exact S0 | exact MU1 | exact WM1 |].
      apply Forall_cons; [apply stack0_ok_app; unfold AHI_LO, spf; lia | apply Forall_nil]. }
    assert (OWN1 : lb_own LB M1) by exact (lb_own_wmono _ _ _ OWN WM1).
    assert (XP01 : xpres H LB spz (XW 0 0) m0 M1).
    { eapply (xpres_of_munch H sk0 LB spz (XW 0 0) _ m0 m0 M1 HH RH MU1 WM1).
      apply Forall_cons; [left; cbn [fst snd]; unfold spf; lia | apply Forall_nil]. }
    assert (XP0M : xpres H LB0 spz XST m0 M1).
    { eapply (xpres_weaken H); [exact XP01 | lia | exact SUB0 |]. intros a Ha. unfold XW, XST in *. cbn [rin_ivs fst snd] in *. lia. }
    assert (R1M : state_repA LB M1 st1 c1).
    { eapply (rep_keep H LB LB LB spz (XW 0 0) m0 M1 st1 c1 R1 XP01 (objx_st1g LB spz 0 0 ltac:(lia) ltac:(lia))); [| lia | lia].
      rewrite EB1. apply blkx_stageg; [exact IN1 | exact AL1 | lia | lia]. }
    assert (SH1M : state_sh M1 c1).
    { eapply (sh_keep H LB LB spz (XW 0 0) m0 M1 st1 c1 R1 SH1 XP01).
      rewrite EB1. eapply blksh_stageg; [exact RH | exact IN1 | lia | lia]. }
    assert (R2M : state_repA LB M1 st2 c2).
    { eapply (rep_keep H LB LB LB spz (XW 0 0) m0 M1 st2 c2 R2 XP01 (objx_st2g LB spz 0 0 ltac:(lia) ltac:(lia) ltac:(lia))); [| lia | lia].
      rewrite EB2. apply blkx_stageg; [exact IN2 | exact AL2 | lia | lia]. }
    assert (SH2M : state_sh M1 c2).
    { eapply (sh_keep H LB LB spz (XW 0 0) m0 M1 st2 c2 R2 SH2 XP01).
      rewrite EB2. eapply blksh_stageg; [exact RH | exact IN2 | lia | lia]. }
    assert (DJ1 : forall A, 0 <= A -> A + 240 <= 2 ^ 47 -> disjoint_from [(spf, spz)] (sh A) (nsh 240)).
    { intros A HA HA2. pose proof (sh_nsh_high A 240 HA ltac:(lia) ltac:(unfold AAPP_HI; lia)) as K.
      cbn [disjoint_from]. split; [left; unfold AHI_LO in K; unfold spf; lia | exact I]. }
    assert (AD1M : addressable M1 st1 240) by exact (addressable_transport _ _ _ _ _ AD1 MU1 WM1 (DJ1 st1 ltac:(lia) ST1H)).
    assert (AD2M : addressable M1 st2 240) by exact (addressable_transport _ _ _ _ _ AD2 MU1 WM1 (DJ1 st2 ltac:(lia) ST2H)).
    assert (IV1 : INV sk0 LB M1 c1 c2 L0).
    { unfold INV.
      refine (conj MI1 (conj STK1 (conj ERR1 (conj RA1 (conj AC1 (conj RFS1 (conj S01 (conj RH1 (conj OWN1 (conj FR1
        (conj R1M (conj SH1M (conj R2M (conj SH2M (conj AD1M (conj AD2M (conj PRM (conj XP0M _)))))))))))))))))).
      lia. }

    pose proof (msteps_full asegs _ _ Hms FHF) as HF1. cbn [ms_regs] in HF1.
    readback HR' HF1 HR0 HRe.
    rreg HR' 1%bv G1. rreg HR' 2%bv G2. rreg HR' 8%bv G8. rreg HR' 9%bv G9. rreg HR' 10%bv G10. rreg HR' 11%bv G11.
    rreg HR' 12%bv G12. rreg HR' 22%bv G22.
    rewrite (w_addm spz (-96)) in G2 by lia. replace (spz + -96) with spf in G2 by (unfold spf; lia).
    rewrite G1, G2, G8, G9, G10, G11, G12, G22 in HRe.
    eapply (sr_blk H HH); [exact KR | exact VIS | exact FHF | exact Hms |].
    intros msF1 mo1 KR1 MP1 VIS1.
    assert (VIS1' : as_VIS H sk0 msF1 = MS (mkR (Z_to_bv 64 AST_M1) (Z_to_bv 64 spf) gp tp t0 t1 t2 (Z_to_bv 64 st1) (Z_to_bv 64 st2)
        (Z_to_bv 64 st1) (Z_to_bv 64 st2) (Z_to_bv 64 46) a3 a4 a5 a6 a7 s2 s3 s4 s5 (Z_to_bv 64 2147450880) s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 AASAN_MEMCPY) fc None M1 (seg_rom asegs)).
    { rewrite VIS1, HRe. reflexivity. }
    clear VIS1.

    pose proof R1M as [[_ _ _ _ _ _ _ _ _ _ _ _ _ D1 _ _] _].
    pose proof R2M as [[_ _ _ _ _ _ _ _ _ _ _ _ _ D2 _ _] _].
    destruct (sp_cb_of_def M1 st1 240 46 D1 ltac:(lia) ST1L ltac:(lia) ltac:(lia)) as (bs1 & CB1M & _ & _).
    destruct (sp_cb_of_def M1 st2 240 46 D2 ltac:(lia) ST2L ltac:(lia) ltac:(lia)) as (bs2 & _ & BA2M & LEN2).
    assert (SV1 : shvis M1 st1 (st1 + 46)).
    { pose proof F1 as (f & Hf & Hf1 & Hf2). unfold ST_SIZE in Hf2.
      pose proof (ah_frm_shvis H HH LF M1 f RFS1 Hf) as SV.
      pose proof (ah_RFS_range H HH _ _ RFS1) as [_ FRr]. pose proof (FRr f Hf) as (_ & Ff & _). unfold AFS_HDR in Ff.
      eapply shvis_sub; [exact SV | lia | lia | lia | lia | lia]. }
    assert (SV2 : shvis M1 st2 (st2 + 46)).
    { pose proof F2 as [(f & Hf & Hf1 & Hf2) | (K1 & K2)]; unfold ST_SIZE in *.
      - pose proof (ah_frm_shvis H HH LF M1 f RFS1 Hf) as SV.
        pose proof (ah_RFS_range H HH _ _ RFS1) as [_ FRr]. pose proof (FRr f Hf) as (_ & Ff & _). unfold AFS_HDR in Ff.
        eapply shvis_sub; [exact SV | lia | lia | lia | lia | lia].
      - eapply (stack0_shvis M1 lo shi); [exact S01 | lia | lia | lia]. }
    assert (ACC1 : accessible M1 st1 46) by (eapply (addressable_accessible M1 st1 240); [exact AD1M | lia | lia | unfold AAPP_HI; lia]).
    assert (ACC2 : accessible M1 st2 46) by (eapply (addressable_accessible M1 st2 240); [exact AD2M | lia | lia | unfold AAPP_HI; lia]).
    assert (IA1 : in_app_mem st1 (st1 + 46)) by (eapply aapp_in_app_mem; [exact FB4 | lia | lia]).
    assert (IA2 : in_app_mem st2 (st2 + 46)).
    { pose proof FS2 as [K|K]; [eapply aapp_in_app_mem; [exact FB4 | lia | lia] | eapply (stack0_in_app_mem M1 lo shi); [exact S01 | lia | unfold ST_SIZE in K; lia]]. }
    assert (ACO1 : aconst_ok (st1, st1 + 46)) by (eapply aconst_ok_app; [exact FB4 | lia | lia]).

    eapply (ahh_evt_then H HH); [exact KR1 | exact VIS1' | |].
    { eapply (ah_memcpy H HH) with (src := bs2) (junk := bs1) (lo := lo); rewrite ?U1, ?U2, ?U46, ?Uspf.
      - exact BA2M.
      - exact LEN2.
      - exact CB1M.
      - lia.
      - exact ACC2.
      - exact ACC1.
      - exact SV2.
      - exact SV1.
      - exact (proj1 (stk_split asegs M1 lo spf spz STK1 ltac:(unfold spf; lia))).
      - lia.
      - unfold spf, AINTRIN_STACK; lia.
      - exact MI1.
      - exact AC1.
      - lia.
      - exact IA2.
      - exact IA1.
      - exact ACO1.
      - left; lia.
      - pose proof FS2 as [K|K]; [left; lia | right; unfold spf; lia]. }
    intros msF2 mo2 KR2 MP2 POST.
    destruct POST as (t0' & t1' & t2' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m2
                      & VIS2 & MU2 & WM2 & MI2 & ST2 & CB2 & SB2 & AC2).
    rewrite ?U1, ?U2, ?U46, ?Uspf in MU2. rewrite ?U1, ?U2, ?U46, ?Uspf in ST2. rewrite ?U1, ?U2, ?U46, ?Uspf in CB2.
    rewrite (ret_pc_even AST_M1 ltac:(unfold AST_M1; lia) eq_refl) in VIS2.

    assert (W2a : aclient_write_ok H LB (st1, st1 + 46)) by (right; right; right; right; left; cbn [fst snd]; lia).
    assert (W2b : afs_write_ok H LF (st1, st1 + 46)).
    { right. pose proof F1 as (f & Hf & Hf1 & Hf2). exists f. unfold ST_SIZE in Hf2. cbn [fst snd]. split; [exact Hf | lia]. }
    assert (SWb : aceil <= spf - AINTRIN_STACK) by (unfold spf, AINTRIN_STACK; lia).
    destruct (stack_window_ok H LB LF (spf - AINTRIN_STACK) spf SWb FB2) as (W3a & W3b & W3c).
    destruct (client_frame H HH sk0 LB LF B _ M1 m2 RH1 RFS1 AC1 RA1 MU2 WM2
               (Forall_cons _ _ _ W2a (Forall_cons _ _ _ W3a (Forall_nil _)))
               (Forall_cons _ _ _ W2b (Forall_cons _ _ _ W3b (Forall_nil _)))
               (Forall_cons _ _ _ ACO1 (Forall_cons _ _ _ W3c (Forall_nil _)))) as (RH2 & RFS2 & _ & RA2).
    assert (S02 : stack0 m2 lo shi).
    { eapply stack0_transport; [exact S01 | exact MU2 | exact WM2 |].
      apply Forall_cons; [eapply stack0_ok_aapp; [exact FB4 | cbn [fst]; lia | cbn [snd]; lia]|].
      apply Forall_cons; [apply stack0_ok_app; unfold AHI_LO, spf, AINTRIN_STACK; lia | apply Forall_nil]. }
    assert (ERR2 : rw_cells asegs m2 (errno_addr tp) [C4 errv]).
    { eapply rw_cells_transport; [exact ERR1 | exact MU2 | exact WM2 | cbn [disjoint_from cells_size csize Z.of_nat]; unfold spf, AINTRIN_STACK, AIMG_TOP in *; lia]. }
    assert (OWN2 : lb_own LB m2) by exact (lb_own_wmono _ _ _ OWN1 WM2).
    assert (XPa : xpres H LB spf (XW 0 46) M1 m2).
    { eapply (xpres_of_munch H sk0 LB spf (XW 0 46) _ m0 M1 m2 HH RH MU2 WM2).
      apply Forall_cons; [right; intros a Ha; cbn [fst snd] in Ha; unfold XW; cbn [rin_ivs fst snd]; left; lia|].
      apply Forall_cons; [left; cbn [fst snd]; unfold spf, AINTRIN_STACK; lia | apply Forall_nil]. }
    assert (XPb : xpres H LB spf [(st1, st1 + 46)] M1 m2).
    { eapply (xpres_of_munch H sk0 LB spf [(st1, st1 + 46)] _ m0 M1 m2 HH RH MU2 WM2).
      apply Forall_cons; [right; intros a Ha; cbn [fst snd] in Ha; cbn [rin_ivs fst snd]; left; lia|].
      apply Forall_cons; [left; cbn [fst snd]; unfold spf, AINTRIN_STACK; lia | apply Forall_nil]. }

    pose proof (scal_of_rep LB M1 st2 c2 R2M) as (N0 & N1 & N2 & N3 & N4 & N5 & N6).
    pose proof (rw_cells_bytes_at asegs m2 st1 _ CB2) as BA1. cbn [cells_bytes cbytes] in BA1. rewrite app_nil_r in BA1.
    assert (LENn : Z.of_nat (length bs2) = 46) by (rewrite LEN2; reflexivity).
    pose proof (cellw_copy M1 m2 st2 st1 bs2 0 8 (st_words c2) BA2M BA1 ltac:(rewrite Z.add_0_r; exact N0) ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C0.
    rewrite Z.add_0_r in C0.
    pose proof (cellw_copy M1 m2 st2 st1 bs2 8 8 (st_nwords c2) BA2M BA1 N1 ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C1.
    pose proof (cellw_copy M1 m2 st2 st1 bs2 16 8 (st_diag c2) BA2M BA1 N2 ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C2.
    pose proof (cellw_copy M1 m2 st2 st1 bs2 24 8 (st_widx c2) BA2M BA1 N3 ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C3.
    pose proof (cellw_copy M1 m2 st2 st1 bs2 32 8 (st_icount c2) BA2M BA1 N4 ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C4.
    pose proof (cellw_copy M1 m2 st2 st1 bs2 40 4 (st_endian c2) BA2M BA1 N5 ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C5.
    pose proof (cellw_copy M1 m2 st2 st1 bs2 44 2 (st_flags c2) BA2M BA1 N6 ltac:(lia) ltac:(rewrite LENn; cbn; lia)) as C6.
    assert (SC2 : scal_cells m2 st1 c2) by exact (conj C0 (conj C1 (conj C2 (conj C3 (conj C4 (conj C5 C6)))))).
    assert (R1N : state_repA LB m2 st1 cA0).
    { unfold cA0. eapply (rep_upd_scal H LB LB LB spf (XW 0 46) M1 m2 st1 c1 c2 R1M XPa (objx_st1 LB 0 46 ltac:(lia) ltac:(lia)));
        [| exact SC2 | lia | lia].
      rewrite EB1. apply blkx_stage; [exact IN1 | exact AL1 | lia | lia]. }
    assert (SH1N : state_sh m2 cA0).
    { unfold cA0. change (state_sh m2 c1). eapply (sh_keep H LB LB spf (XW 0 46) M1 m2 st1 c1 R1M SH1M XPa).
      rewrite EB1. eapply blksh_stage; [exact RH1 | exact IN1 | lia | lia]. }
    assert (R2N : state_repA LB m2 st2 c2).
    { eapply (rep_keep H LB LB LB spf [(st1, st1 + 46)] M1 m2 st2 c2 R2M XPb); [| | lia | lia].
      - eapply (sp_objx_re LB spf (XW 0 0) [(st1, st1 + 46)] st2 0 0 (objx_st2 LB 0 0 ltac:(lia) ltac:(lia))).
        intros a Ha Hr. cbn [rin_ivs fst snd] in Hr. lia.
      - rewrite EB2. eapply (sp_blkx_re LB spf (XW 0 46)); [apply blkx_stage; [exact IN2 | exact AL2 | lia | lia] |].
        intros a Hr. unfold XW. cbn [rin_ivs fst snd] in *. lia. }
    assert (SH2N : state_sh m2 c2).
    { eapply (sh_keep H LB LB spf [(st1, st1 + 46)] M1 m2 st2 c2 R2M SH2M XPb).
      rewrite EB2. eapply (sp_blksh_re LB spf (XW 0 46)); [eapply blksh_stage; [exact RH1 | exact IN2 | lia | lia] |].
      intros a Hr. unfold XW. cbn [rin_ivs fst snd] in *. lia. }
    assert (IV2 : INV sk0 LB m2 cA0 c2 L0)
      by exact (INV_step sk0 LB M1 c1 c2 L0 sk0 LB m2 LB 0 46 cA0 c2 L0 IV1 XPa ltac:(lia) ltac:(lia) ltac:(lia) SUB0
                  MI2 ST2 ERR2 RA2 AC2 RFS2 S02 RH2 OWN2 ltac:(lia) R1N SH1N R2N SH2N PRM).
    eapply (stage_m1 sk0 LB m2 msF2 mo2); [exact VIS2 | exact KR2 | eapply (ah_mpres_trans H HH); [exact MP1 | exact MP2] | exact IV2].
  Qed.

  Lemma stage_p_all : forall LB msF (t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word),
    as_VIS H sk0 msF = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 st1) (Z_to_bv 64 st2) a2 a3 a4 a5 a6 a7
                               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                          F (Z_to_bv 64 AST_MVA) fc None m0 (seg_rom asegs) ->
    as_AKREL H sk0 (mkCfg msF mo0) ->
    mem_inv asegs m0 -> stk asegs m0 lo spz -> rw_cells asegs m0 (errno_addr tp) [C4 errv] -> as_rauxv_ok H m0 B ->
    ACONST m0 -> as_RFS H LF m0 -> stack0 m0 lo shi -> as_RHEAP H sk0 LB m0 -> lb_own LB m0 ->
    state_repA LB m0 st1 c1 -> state_sh m0 c1 -> state_repA LB m0 st2 c2 -> state_sh m0 c2 ->
    addressable m0 st1 240 -> addressable m0 st2 240 ->
    Permutation LB (LB0 ++ L0) ->
    as_SR H QF (mkCfg msF mo0).
  Proof using All.
    exact stage_p.
  Qed.
End StMva.

