Theorem st_mva_ok : forall {HCEIL : HeapCeil} (H : asr), asan_rt_hyps_bp H -> st_mva_stmt H.
Proof.
  intros HCEIL H HBP.
  destruct HBP as (HH & _ & _ & _ & HAN & [HCF _]).
  unfold st_mva_stmt.
  intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    F fc msF m mo s LB LB0 LBs1 LBs2 LF st1 st2 c1 c2 lo B shi errv
    VIS FRZ E0 E1 RA1 SH1 RA2 SH2 PLB PL1 PL2 VB1 AD1 AD2 AP12 DJ1 DJ2 F1 F2 ST1C RH AK AL0 RX SPB BLT
    SP16 STK LO1 LO2 RW MI TPV RAE AC RFS S0 SPS LBO TRS.
  subst a0 a1.
  destruct (split6 LBs1 c1 PL1) as (A1 & A2 & A3 & A4 & A5 & A6 & PA & LA1 & LA2 & LA3 & LA4 & LA5 & LA6).
  destruct (split6 LBs2 c2 PL2) as (B1 & B2 & B3 & B4 & B5 & B6 & PB2 & LB1 & LB2 & LB3 & LB4 & LB5 & LB6).
  pose proof aceil_facts as ((ACL & ACH) & ACM & ACC).
  pose proof (stack0_bounds _ _ _ S0) as (S0L & S0M & S0H).
  pose proof (ah_RFS_range H HH LF m RFS) as [FSB0 AFR].
  assert (SPR : 2 ^ 45 <= bv_unsigned sp - 192 /\ bv_unsigned sp <= 2 ^ 47)
    by (unfold AST_MVA_STACK, AFREE_STACK, AAPP_HI in *; lia).
  assert (LOH : aceil <= lo /\ lo <= bv_unsigned sp - AST_MVA_STACK) by (split; assumption).
  assert (SHH : bv_unsigned sp <= shi /\ shi <= AAPP_HI) by (split; assumption).
  assert (FS1 : as_FSB H <= st1 /\ st1 + 240 <= as_FSB H + AFS_SIZE).
  { destruct F1 as (f & INf & Fa & Fb). destruct (AFR f INf) as (_ & G1 & G2 & _).
    unfold ST_SIZE, AFS_HDR in *. lia. }
  assert (FS2 : (as_FSB H <= st2 /\ st2 + 240 <= as_FSB H + AFS_SIZE)
                \/ (bv_unsigned sp <= st2 /\ st2 + ST_SIZE + 64 <= shi)).
  { destruct F2 as [(f & INf & Fa & Fb)|X]; [left|right; exact X].
    destruct (AFR f INf) as (_ & G1 & G2 & _). unfold ST_SIZE, AFS_HDR in *. lia. }
  assert (FSBOK : AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil /\ as_FSB H mod 4096 = 0
                  /\ aapp (as_FSB H) AFS_SIZE) by exact FSB0.
  assert (ST1A : st1 mod 8 = 0) by (destruct RA1 as [[] _]; assumption).
  assert (ST2A : st2 mod 8 = 0) by (destruct RA2 as [[] _]; assumption).
  assert (BAP : forall p n, In (p, n) (state_blocks c1 ++ state_blocks c2) ->
                  (p + n <= st1 \/ st1 + 240 <= p) /\ (p + n <= st2 \/ st2 + 240 <= p)).
  { intros p n IN.
    assert (INB : exists b, In b (LBs1 ++ LBs2) /\ snd (fst b) = p /\ snd b = n).
    { apply in_app_or in IN. destruct IN as [IN|IN].
      - apply (Permutation_in _ (Permutation_sym PL1)) in IN. unfold lbl in IN. apply in_map_iff in IN.
        destruct IN as (b & Eb & INb). injection Eb as Ep En.
        exists b. split; [apply in_or_app; left; exact INb| split; assumption].
      - apply (Permutation_in _ (Permutation_sym PL2)) in IN. unfold lbl in IN. apply in_map_iff in IN.
        destruct IN as (b & Eb & INb). injection Eb as Ep En.
        exists b. split; [apply in_or_app; right; exact INb| split; assumption]. }
    destruct INB as (b & INb & Ep & En).
    assert (INL : In b LB).
    { apply (Permutation_in _ (Permutation_sym PLB)). apply in_or_app. right. exact INb. }
    pose proof (DJ1 b INL) as D1. pose proof (DJ2 b INL) as D2.
    unfold blk_addr, blk_size, ST_SIZE in D1, D2. subst p n. lia. }
  assert (PL : Permutation LB (LB0 ++ (A1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6) ++ (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6))).
  { eapply Permutation_trans; [exact PLB|]. apply Permutation_app_head. apply Permutation_app; assumption. }
  rewrite <- !app_assoc in PL.
  assert (ESP : Z_to_bv 64 (bv_unsigned sp) = sp) by apply Z_to_bv_bv_unsigned.
  rewrite <- ESP in VIS. rewrite <- ESP.
  exact (@stage_p_all HCEIL H HH HCF HAN ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 fc (bv_unsigned sp)
           st1 st2 c1 c2 LB0 LBs2 A1 A2 A3 A4 A5 A6 B1 B2 B3 B4 B5 B6 LF lo B shi errv m mo s
           FRZ SP16 SPR LOH SHH TPV F1 F2 FS1 FS2 FSBOK ST1C AP12 AL0 SPB TRS PB2
           LA1 LA2 LA3 LA4 LA5 LA6 LB1 LB2 LB3 LB4 LB5 LB6 ST1A ST2A VB1 BAP
           LB msF t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F VIS AK MI STK RW RX AC RFS S0 RH LBO
           RA1 SH1 RA2 SH2 AD1 AD2 PL).
Qed.
